local SafeStore = {}

-- Settings: change these!
local TRIES = 4
local FIRST_WAIT = 1 -- seconds; doubles after each failed try (1, 2, 4...)

local function retry(action)
	local waitTime = FIRST_WAIT
	local lastError
	for attempt = 1, TRIES do
		local ok, result = pcall(action)
		if ok then
			return true, result
		end
		lastError = result
		warn("DataStore try " .. attempt .. " failed: " .. tostring(result))
		if attempt < TRIES then
			task.wait(waitTime)
			waitTime *= 2
		end
	end
	return false, lastError
end

-- Get: returns ok, value
function SafeStore.Get(store, key)
	return retry(function()
		return store:GetAsync(key)
	end)
end

-- Update: transform gets the old value and returns the new one
function SafeStore.Update(store, key, transform)
	return retry(function()
		return store:UpdateAsync(key, transform)
	end)
end

-- Set: overwrite with a new value
function SafeStore.Set(store, key, value)
	return retry(function()
		return store:SetAsync(key, value)
	end)
end

return SafeStore

const int DATA_PIN = 11;
const int CLOCK_PIN = 12;
const int LATCH_PIN = 8;

// Send 8 on/off bits to the chip, then "latch" them so the LEDs update together.
void writeLeds(byte pattern) {
  digitalWrite(LATCH_PIN, LOW);
  shiftOut(DATA_PIN, CLOCK_PIN, MSBFIRST, pattern);
  digitalWrite(LATCH_PIN, HIGH);
}

void setup() {
  pinMode(DATA_PIN, OUTPUT);
  pinMode(CLOCK_PIN, OUTPUT);
  pinMode(LATCH_PIN, OUTPUT);
}

void loop() {
  // Pattern 1: one light walking along.
  for (int i = 0; i < 8; i++) {
    writeLeds(1 << i);
    delay(100);
  }
  // Pattern 2: fill up.
  byte bar = 0;
  for (int i = 0; i < 8; i++) {
    bar |= (1 << i);
    writeLeds(bar);
    delay(100);
  }
  // Pattern 3: flash odd and even LEDs.
  for (int i = 0; i < 6; i++) {
    writeLeds(i % 2 ? 0b10101010 : 0b01010101);
    delay(200);
  }
  writeLeds(0);
  delay(300);
}

#include <LedControl.h>

LedControl matrix(12, 11, 10, 1);  // DIN, CLK, CS, number of matrices

// Each row is one byte: 1 = LED on. Draw them in binary so you can "see" the picture.
const byte SMILE[8]    = {0b00111100, 0b01000010, 0b10100101, 0b10000001,
                          0b10100101, 0b10011001, 0b01000010, 0b00111100};
const byte HEART[8]    = {0b00000000, 0b01100110, 0b11111111, 0b11111111,
                          0b11111111, 0b01111110, 0b00111100, 0b00011000};
const byte SURPRISE[8] = {0b00111100, 0b01000010, 0b10100101, 0b10000001,
                          0b10011001, 0b10011001, 0b01000010, 0b00111100};

void showPicture(const byte picture[8]) {
  for (int row = 0; row < 8; row++) {
    matrix.setRow(0, row, picture[row]);
  }
}

void setup() {
  matrix.shutdown(0, false);  // wake it up (it starts asleep)
  matrix.setIntensity(0, 4);  // brightness 0 to 15
  matrix.clearDisplay(0);
}

void loop() {
  showPicture(SMILE);
  delay(1500);
  // Make the heart beat.
  for (int i = 0; i < 3; i++) {
    showPicture(HEART);
    matrix.setIntensity(0, 12);
    delay(250);
    matrix.setIntensity(0, 3);
    delay(250);
  }
  matrix.setIntensity(0, 4);
  showPicture(SURPRISE);
  delay(1500);
}

const int BATTERY_PIN = A0;
const int GREEN = 4, YELLOW = 5, RED = 6;

void setup() {
  pinMode(GREEN, OUTPUT);
  pinMode(YELLOW, OUTPUT);
  pinMode(RED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  float volts = analogRead(BATTERY_PIN) * 5.0 / 1023.0;

  digitalWrite(GREEN, LOW);
  digitalWrite(YELLOW, LOW);
  digitalWrite(RED, LOW);

  Serial.print("Battery: ");
  Serial.print(volts, 2);
  Serial.print(" V  ");

  if (volts < 0.1) {
    Serial.println("(no battery)");
  } else if (volts >= 1.4) {
    digitalWrite(GREEN, HIGH);
    Serial.println("good");
  } else if (volts >= 1.2) {
    digitalWrite(YELLOW, HIGH);
    Serial.println("ok");
  } else {
    digitalWrite(RED, HIGH);
    Serial.println("dead, recycle it");
  }
  delay(500);
}

const int TRIG_PIN = 9, ECHO_PIN = 10, BUZZER_PIN = 8;
// C major scale, two octaves.
const int SCALE[] = {262, 294, 330, 349, 392, 440, 494, 523, 587, 659, 698, 784, 880, 988};
const int SCALE_SIZE = 14;

long distanceCm() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  unsigned long d = pulseIn(ECHO_PIN, HIGH, 20000UL);
  return d == 0 ? 999 : d / 58;
}

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
}

void loop() {
  long cm = distanceCm();
  if (cm >= 5 && cm <= 40) {
    // Each 2.5 cm or so is one step on the scale.
    int note = map(cm, 5, 40, 0, SCALE_SIZE - 1);
    tone(BUZZER_PIN, SCALE[note]);
  } else {
    noTone(BUZZER_PIN);  // no hand: silence
  }
  delay(50);
}

