const int SENSOR_PIN = A0;
const int PUMP_RELAY = 7;
const int DRY_LEVEL = 700;           // higher number = drier soil (check yours)
const unsigned long PUMP_MS = 3000;  // water for 3 seconds
const unsigned long SOAK_MS = 60000; // then wait a minute for it to soak in

void setup() {
  pinMode(PUMP_RELAY, OUTPUT);
  digitalWrite(PUMP_RELAY, LOW);
  Serial.begin(9600);
}

void loop() {
  int reading = analogRead(SENSOR_PIN);
  Serial.print("Soil reading: ");
  Serial.println(reading);

  if (reading > DRY_LEVEL) {
    Serial.println("Too dry! Pumping water...");
    digitalWrite(PUMP_RELAY, HIGH);
    delay(PUMP_MS);
    digitalWrite(PUMP_RELAY, LOW);
    Serial.println("Done. Waiting for the water to soak in.");
    delay(SOAK_MS);  // stops it flooding the pot before the sensor notices
  } else {
    delay(5000);
  }
}

const int FIRST_PIN = 2;

void setup() {
  for (int i = 0; i < 8; i++) pinMode(FIRST_PIN + i, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  for (int number = 0; number <= 255; number++) {
    // Bit 0 is worth 1, bit 1 is worth 2, bit 2 is worth 4... up to 128.
    for (int b = 0; b < 8; b++) {
      digitalWrite(FIRST_PIN + b, bitRead(number, b) ? HIGH : LOW);
    }
    Serial.print(number);
    Serial.print(" = ");
    Serial.println(number, BIN);
    delay(400);
  }
}

// How long the LED stays on (and off), in milliseconds.
const unsigned long BLINK_TIME = 1000;

void setup() {
  // Tell the board this pin is an output (it sends power out).
  pinMode(LED_BUILTIN, OUTPUT);
}

void loop() {
  digitalWrite(LED_BUILTIN, HIGH);  // LED on
  delay(BLINK_TIME);                // wait 1 second
  digitalWrite(LED_BUILTIN, LOW);   // LED off
  delay(BLINK_TIME);                // wait 1 second
}

const int LED_A = 8;
const int LED_B = 9;
const unsigned long A_EVERY = 250;
const unsigned long B_EVERY = 1000;

unsigned long lastA = 0;
unsigned long lastB = 0;
bool aOn = false;
bool bOn = false;

void setup() {
  pinMode(LED_A, OUTPUT);
  pinMode(LED_B, OUTPUT);
}

void loop() {
  // delay() would freeze everything. Instead we check the clock and only act when it's time.
  unsigned long now = millis();

  if (now - lastA >= A_EVERY) {
    lastA = now;
    aOn = !aOn;
    digitalWrite(LED_A, aOn);
  }

  if (now - lastB >= B_EVERY) {
    lastB = now;
    bOn = !bOn;
    digitalWrite(LED_B, bOn);
  }
  // loop() runs thousands of times a second, so there's time for more jobs here!
}

#include <SoftwareSerial.h>

SoftwareSerial bluetooth(2, 3);  // RX, TX (the Arduino's side)
const int ENA = 5, IN1 = 7, IN2 = 8, ENB = 6, IN3 = 9, IN4 = 10;
int speed = 200;
unsigned long lastCommand = 0;

void motors(int left, int right) {
  digitalWrite(IN1, left > 0);
  digitalWrite(IN2, left < 0);
  analogWrite(ENA, abs(left));
  digitalWrite(IN3, right > 0);
  digitalWrite(IN4, right < 0);
  analogWrite(ENB, abs(right));
}

void setup() {
  int pins[] = {ENA, IN1, IN2, ENB, IN3, IN4};
  for (int i = 0; i < 6; i++) pinMode(pins[i], OUTPUT);
  bluetooth.begin(9600);  // HC-05 and HC-06 usually talk at 9600
  Serial.begin(9600);
}

void loop() {
  if (bluetooth.available()) {
    char c = bluetooth.read();
    lastCommand = millis();
    Serial.println(c);
    switch (c) {
      case 'F': motors(speed, speed); break;
      case 'B': motors(-speed, -speed); break;
      case 'L': motors(-speed, speed); break;
      case 'R': motors(speed, -speed); break;
      case 'G': motors(speed / 3, speed); break;   // forward left
      case 'I': motors(speed, speed / 3); break;   // forward right
      case 'S': motors(0, 0); break;
      default:
        // Many apps send '0' to '9' for the speed slider ('q' means full).
        if (c >= '0' && c <= '9') speed = map(c - '0', 0, 9, 100, 255);
        if (c == 'q') speed = 255;
    }
  }

  // Safety: if the phone goes quiet for 1 second (out of range), stop.
  if (millis() - lastCommand > 1000) motors(0, 0);
}

const int LED_PIN = 9;
const float BREATH_SECONDS = 4.0;  // one full in-and-out breath

void setup() {
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  float seconds = millis() / 1000.0;
  // sin() swings from -1 to 1. Shift it to 0..1, then to 0..255.
  float wave = (sin(seconds * TWO_PI / BREATH_SECONDS) + 1.0) / 2.0;
  // Squaring the wave makes the dim part last longer, which looks nicer.
  int brightness = (int)(wave * wave * 255);
  analogWrite(LED_PIN, brightness);
  delay(10);
}

const int BUTTON = 2;
volatile unsigned int pressCount = 0;   // volatile: it changes inside the interrupt
volatile unsigned long lastPressTime = 0;

// An ISR (interrupt service routine) must be short and fast. No Serial or delay in here!
void onPress() {
  unsigned long now = millis();
  if (now - lastPressTime > 50) {  // ignore bounces
    pressCount++;
    lastPressTime = now;
  }
}

void setup() {
  pinMode(BUTTON, INPUT_PULLUP);
  // FALLING = when the pin goes from HIGH to LOW (the moment you press).
  attachInterrupt(digitalPinToInterrupt(BUTTON), onPress, FALLING);
  Serial.begin(9600);
}

void loop() {
  // Pretend the loop is very busy. The interrupt still counts every press!
  delay(3000);

  noInterrupts();  // pause interrupts while we copy the number safely
  unsigned int count = pressCount;
  interrupts();

  Serial.print("Presses so far: ");
  Serial.println(count);
}

const int BUTTON_PIN = 2;
const int LED_PIN = LED_BUILTIN;
const unsigned long DEBOUNCE_MS = 50;  // ignore wobbles shorter than this

bool ledOn = false;
int lastReading = HIGH;          // what the pin said last time
int stableState = HIGH;          // the "real" button state after debounce
unsigned long lastChangeTime = 0;

void setup() {
  // INPUT_PULLUP keeps the pin HIGH until the button connects it to GND.
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int reading = digitalRead(BUTTON_PIN);

  // The reading changed, so restart the debounce timer.
  if (reading != lastReading) {
    lastChangeTime = millis();
  }

  // It stayed the same long enough, so trust it.
  if (millis() - lastChangeTime > DEBOUNCE_MS && reading != stableState) {
    stableState = reading;

    // LOW means pressed (the pin is pulled to GND).
    if (stableState == LOW) {
      ledOn = !ledOn;
      digitalWrite(LED_PIN, ledOn ? HIGH : LOW);
      Serial.println(ledOn ? "LED ON" : "LED OFF");
    }
  }

  lastReading = reading;
}

const int BUZZER_PIN = 8;

// Note pitches in Hz (0 means a rest).
const int NOTE_C = 262, NOTE_D = 294, NOTE_E = 330, NOTE_F = 349, NOTE_G = 392, NOTE_A = 440;

const int melody[] = {
  NOTE_C, NOTE_C, NOTE_G, NOTE_G, NOTE_A, NOTE_A, NOTE_G, 0,
  NOTE_F, NOTE_F, NOTE_E, NOTE_E, NOTE_D, NOTE_D, NOTE_C, 0
};

// How long each note lasts: 4 = quarter note, 2 = half note.
const int beats[] = {
  4, 4, 4, 4, 4, 4, 2, 4,
  4, 4, 4, 4, 4, 4, 2, 4
};

const int NOTE_COUNT = sizeof(melody) / sizeof(melody[0]);
const int WHOLE_NOTE_MS = 1600;  // smaller = faster song

void setup() {
  pinMode(BUZZER_PIN, OUTPUT);
}

void loop() {
  for (int i = 0; i < NOTE_COUNT; i++) {
    int noteLength = WHOLE_NOTE_MS / beats[i];

    if (melody[i] > 0) {
      tone(BUZZER_PIN, melody[i], noteLength);
    }

    // Wait a little longer than the note so notes don't blur together.
    delay(noteLength * 13 / 10);
    noTone(BUZZER_PIN);
  }

  delay(2000);  // pause before playing again
}

const int S0 = 4, S1 = 5, S2 = 6, S3 = 7, OUT_PIN = 8;

// The sensor sends pulses. A SHORTER pulse means MORE of that color.
unsigned long readColor(int s2, int s3) {
  digitalWrite(S2, s2);
  digitalWrite(S3, s3);
  delay(20);
  return pulseIn(OUT_PIN, LOW, 50000UL);
}

void setup() {
  pinMode(S0, OUTPUT);
  pinMode(S1, OUTPUT);
  pinMode(S2, OUTPUT);
  pinMode(S3, OUTPUT);
  pinMode(OUT_PIN, INPUT);
  digitalWrite(S0, HIGH);  // S0 high + S1 low = 20% speed, good for Arduino
  digitalWrite(S1, LOW);
  Serial.begin(9600);
}

void loop() {
  unsigned long red = readColor(LOW, LOW);
  unsigned long blue = readColor(LOW, HIGH);
  unsigned long green = readColor(HIGH, HIGH);

  Serial.print("R: ");
  Serial.print(red);
  Serial.print("  G: ");
  Serial.print(green);
  Serial.print("  B: ");
  Serial.print(blue);
  Serial.print("  -> ");

  // The smallest number is the strongest color.
  if (red < green && red < blue) Serial.println("RED");
  else if (green < red && green < blue) Serial.println("GREEN");
  else if (blue < red && blue < green) Serial.println("BLUE");
  else Serial.println("not sure");
  delay(500);
}

#include <SoftwareSerial.h>

SoftwareSerial bluetooth(10, 11);  // RX, TX
const int LED_PIN = 9;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  bluetooth.begin(9600);
  bluetooth.println("Hi! Send 1 (on), 0 (off) or a to j (brightness).");
}

void loop() {
  if (!bluetooth.available()) return;
  char c = bluetooth.read();

  if (c == '1') {
    digitalWrite(LED_PIN, HIGH);
    bluetooth.println("LED on");
  } else if (c == '0') {
    digitalWrite(LED_PIN, LOW);
    bluetooth.println("LED off");
  } else if (c >= 'a' && c <= 'j') {
    int level = (c - 'a' + 1) * 25;  // a = 25 ... j = 250
    analogWrite(LED_PIN, level);
    bluetooth.print("Brightness ");
    bluetooth.println(level);
  }
  // Anything else (like the Enter key) is ignored.
}

#include <IRremote.hpp>

const int IR_PIN = 11;
const int LED_PINS[] = {4, 5, 6};

// These are the codes for the common little "Car MP3" style remote.
const uint16_t BUTTON_0 = 0x16;
const uint16_t BUTTON_1 = 0x0C;
const uint16_t BUTTON_2 = 0x18;
const uint16_t BUTTON_3 = 0x5E;

bool ledOn[3] = {false, false, false};

void toggle(int which) {
  ledOn[which] = !ledOn[which];
  digitalWrite(LED_PINS[which], ledOn[which] ? HIGH : LOW);
}

void setup() {
  for (int i = 0; i < 3; i++) pinMode(LED_PINS[i], OUTPUT);
  IrReceiver.begin(IR_PIN);
}

void loop() {
  if (!IrReceiver.decode()) return;  // nothing pressed yet

  bool isRepeat = IrReceiver.decodedIRData.flags & IRDATA_FLAGS_IS_REPEAT;
  uint16_t code = IrReceiver.decodedIRData.command;
  IrReceiver.resume();
  if (isRepeat) return;

  switch (code) {
    case BUTTON_1: toggle(0); break;
    case BUTTON_2: toggle(1); break;
    case BUTTON_3: toggle(2); break;
    case BUTTON_0:
      for (int i = 0; i < 3; i++) {
        ledOn[i] = false;
        digitalWrite(LED_PINS[i], LOW);
      }
      break;
  }
}

#include <EEPROM.h>

const int ADDRESS = 0;  // where in EEPROM we keep our number

void setup() {
  Serial.begin(9600);

  unsigned long boots;
  EEPROM.get(ADDRESS, boots);  // read 4 bytes into "boots"

  // A brand new EEPROM is full of 255s, which reads as a giant number. Start from 0.
  if (boots == 0xFFFFFFFFUL) boots = 0;

  boots++;
  EEPROM.put(ADDRESS, boots);  // put only writes bytes that changed (EEPROM wears out after ~100,000 writes)

  Serial.print("I have started ");
  Serial.print(boots);
  Serial.println(" times!");
}

