const int SEG_PINS[7] = {2, 3, 4, 5, 6, 7, 8};
const int BUTTON_PIN = 10;
const int BUZZER_PIN = 11;

// Bit patterns: bit 0 = a, bit 1 = b ... bit 6 = g.
const byte PATTERNS[7] = {0, 0b0000110, 0b1011011, 0b1001111, 0b1100110, 0b1101101, 0b1111101};

void show(int number) {
  for (int s = 0; s < 7; s++) {
    digitalWrite(SEG_PINS[s], bitRead(PATTERNS[number], s) ? HIGH : LOW);
  }
}

void setup() {
  for (int s = 0; s < 7; s++) pinMode(SEG_PINS[s], OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(BUZZER_PIN, OUTPUT);
  randomSeed(analogRead(A0));
  show(1);
}

void loop() {
  if (digitalRead(BUTTON_PIN) == LOW) {
    // Spin: start fast, get slower, like a real rolling die.
    for (int wait = 20; wait < 300; wait = wait * 12 / 10 + 1) {
      show(random(1, 7));  // 1 to 6 (the top number is not included)
      tone(BUZZER_PIN, 1200, 10);
      delay(wait);
    }
    int result = random(1, 7);
    show(result);
    tone(BUZZER_PIN, 1800, 200);
    while (digitalRead(BUTTON_PIN) == LOW) delay(10);
  }
}

const int LED_PIN = 9;  // PWM pins have a ~: 3, 5, 6, 9, 10, 11
int brightness = 0;
int step = 5;           // how much to change each time

void setup() {
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  analogWrite(LED_PIN, brightness);  // 0 = off, 255 = full on
  brightness += step;

  // At the top or bottom, turn around.
  if (brightness <= 0 || brightness >= 255) {
    step = -step;
  }
  delay(30);
}

#include <DHT.h>

DHT dht(2, DHT22);

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  delay(2500);
  float humidity = dht.readHumidity();
  float tempC = dht.readTemperature();
  if (isnan(humidity) || isnan(tempC)) {
    Serial.println("Sensor error");
    return;
  }

  // false = we give it Celsius and want Celsius back.
  float feelsLike = dht.computeHeatIndex(tempC, humidity, false);

  Serial.print("Real: ");
  Serial.print(tempC, 1);
  Serial.print(" C  Humidity: ");
  Serial.print(humidity, 0);
  Serial.print("%  Feels like: ");
  Serial.print(feelsLike, 1);
  Serial.print(" C  -> ");

  if (feelsLike < 18) Serial.println("Chilly, grab a hoodie.");
  else if (feelsLike < 27) Serial.println("Comfy!");
  else if (feelsLike < 32) Serial.println("Warm, drink some water.");
  else Serial.println("Very hot! Stay in the shade.");
}

#include <IRremote.hpp>

const int IR_PIN = 11;

void setup() {
  Serial.begin(9600);
  // ENABLE_LED_FEEDBACK makes the built-in LED flicker when a signal arrives.
  IrReceiver.begin(IR_PIN, ENABLE_LED_FEEDBACK);
  Serial.println("Point a remote at the sensor and press buttons.");
}

void loop() {
  if (IrReceiver.decode()) {
    // A held button sends "repeat" messages; skip those.
    if (!(IrReceiver.decodedIRData.flags & IRDATA_FLAGS_IS_REPEAT)) {
      Serial.print("Button code: 0x");
      Serial.print(IrReceiver.decodedIRData.command, HEX);
      Serial.print("   (");
      Serial.print(IrReceiver.decodedIRData.command);
      Serial.println(" in normal numbers)");
    }
    IrReceiver.resume();  // get ready for the next button
  }
}

const int PINS[] = {3, 5, 6, 9, 10, 11};
const int COUNT = 6;

void glow(int pin) {
  for (int b = 0; b <= 255; b += 5) {  // fade in
    analogWrite(pin, b);
    delay(4);
  }
  for (int b = 255; b >= 0; b -= 3) {  // fade out slower
    analogWrite(pin, b);
    delay(6);
  }
}

void setup() {
  for (int i = 0; i < COUNT; i++) pinMode(PINS[i], OUTPUT);
  randomSeed(analogRead(A0));  // an unconnected pin gives a random start
}

void loop() {
  int which = random(COUNT);  // 0 to 5
  glow(PINS[which]);
  delay(random(100, 1500));   // wait a random time before the next one
}

