const int BUZZER_PIN = 8;
const int BUTTONS[] = {2, 3, 4, 5};
const int NOTES[] = {262, 294, 330, 392};  // C, D, E, G
const int KEY_COUNT = 4;

void setup() {
  for (int i = 0; i < KEY_COUNT; i++) pinMode(BUTTONS[i], INPUT_PULLUP);
  pinMode(BUZZER_PIN, OUTPUT);
}

void loop() {
  int playing = -1;  // -1 means no key is held
  for (int i = 0; i < KEY_COUNT; i++) {
    if (digitalRead(BUTTONS[i]) == LOW) {
      playing = i;
      break;  // a buzzer can only play one note at a time
    }
  }

  if (playing >= 0) tone(BUZZER_PIN, NOTES[playing]);
  else noTone(BUZZER_PIN);
  delay(10);
}

int secret;
int tries;

void newGame() {
  secret = random(1, 101);
  tries = 0;
  Serial.println("\nI'm thinking of a number from 1 to 100. Guess!");
}

void setup() {
  Serial.begin(9600);
  randomSeed(analogRead(A0));
  newGame();
}

void loop() {
  if (Serial.available() == 0) return;

  int guess = Serial.parseInt();
  while (Serial.available()) Serial.read();  // clear the Enter key
  if (guess < 1 || guess > 100) {
    Serial.println("Type a number from 1 to 100.");
    return;
  }

  tries++;
  Serial.print(guess);
  if (guess < secret) {
    Serial.println(" is too LOW.");
  } else if (guess > secret) {
    Serial.println(" is too HIGH.");
  } else {
    Serial.print(" is RIGHT! You got it in ");
    Serial.print(tries);
    Serial.println(" tries.");
    newGame();
  }
}

const int BUZZER_PIN = 8;
const int BUTTON_PIN = 2;

// Note frequencies in Hz.
const int C4 = 262, D4 = 294, E4 = 330, F4 = 349, G4 = 392, A4n = 440, AS4 = 466, C5 = 523;

const int melody[] = {C4, C4, D4, C4, F4, E4,  C4, C4, D4, C4, G4, F4,
                      C4, C4, C5, A4n, F4, E4, D4,  AS4, AS4, A4n, F4, G4, F4};
// 4 = quarter note, 2 = half note, 8 = eighth note.
const int beats[] = {8, 8, 4, 4, 4, 2,  8, 8, 4, 4, 4, 2,
                     8, 8, 4, 4, 4, 4, 2,  8, 8, 4, 4, 4, 2};
const int NOTE_COUNT = sizeof(melody) / sizeof(melody[0]);

void playSong() {
  for (int i = 0; i < NOTE_COUNT; i++) {
    int duration = 1000 / beats[i];
    tone(BUZZER_PIN, melody[i], duration);
    delay(duration * 13 / 10);  // a little gap so the notes don't blur
  }
  noTone(BUZZER_PIN);
}

void setup() {
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
}

void loop() {
  if (digitalRead(BUTTON_PIN) == LOW) {
    playSong();
  }
}

const int BUZZER = 8;
const int LED = 13;
const int START_BUTTON = 2;

void setup() {
  pinMode(BUZZER, OUTPUT);
  pinMode(LED, OUTPUT);
  pinMode(START_BUTTON, INPUT_PULLUP);
  randomSeed(analogRead(A0));
}

void explode() {
  for (int f = 1500; f > 100; f -= 20) {  // falling "boom" sound
    tone(BUZZER, f);
    digitalWrite(LED, f / 100 % 2);
    delay(8);
  }
  noTone(BUZZER);
  digitalWrite(LED, HIGH);
  delay(2000);
  digitalWrite(LED, LOW);
}

void loop() {
  if (digitalRead(START_BUTTON) == HIGH) return;  // wait for a press

  // The potato blows up after 10 to 30 seconds. Nobody knows when!
  unsigned long fuse = random(10000, 30000);
  unsigned long start = millis();

  while (millis() - start < fuse) {
    unsigned long left = fuse - (millis() - start);
    // Tick faster as time runs out (but players can't see the time).
    int gap = left > 8000 ? 600 : (left > 3000 ? 300 : 120);
    tone(BUZZER, 1000, 30);
    digitalWrite(LED, HIGH);
    delay(30);
    digitalWrite(LED, LOW);
    delay(gap);
  }
  explode();
}

#include <Wire.h>

void setup() {
  Wire.begin();
  Serial.begin(9600);
}

void loop() {
  Serial.println("Scanning...");
  int found = 0;

  for (int address = 1; address < 127; address++) {
    // Knock on each address. 0 means somebody answered.
    Wire.beginTransmission(address);
    byte result = Wire.endTransmission();
    if (result == 0) {
      Serial.print("Found a device at 0x");
      if (address < 16) Serial.print("0");
      Serial.println(address, HEX);
      found++;
    }
  }

  if (found == 0) Serial.println("Nothing found. Check the SDA and SCL wires.");
  else Serial.println("Done.");
  delay(5000);
}

#include <Keypad.h>
#include <Servo.h>

const byte ROWS = 4;
const byte COLS = 4;
char keys[ROWS][COLS] = {
  {'1', '2', '3', 'A'}, {'4', '5', '6', 'B'}, {'7', '8', '9', 'C'}, {'*', '0', '#', 'D'}
};
byte rowPins[ROWS] = {9, 8, 7, 6};
byte colPins[COLS] = {5, 4, 3, 2};
Keypad keypad = Keypad(makeKeymap(keys), rowPins, colPins, ROWS, COLS);

Servo lock;
const int BUZZER_PIN = A0;
const char SECRET[] = "1234";  // change me!
char typed[9];                 // up to 8 keys plus the end marker
byte typedCount = 0;

void setup() {
  lock.attach(10);
  lock.write(0);
  pinMode(BUZZER_PIN, OUTPUT);
  Serial.begin(9600);
  Serial.println("Type the code, then press #. Press * to clear.");
}

void loop() {
  char key = keypad.getKey();
  if (key == NO_KEY) return;
  tone(BUZZER_PIN, 1500, 40);  // little click for every key

  if (key == '*') {
    typedCount = 0;
    Serial.println("Cleared");
  } else if (key == '#') {
    typed[typedCount] = '\0';  // finish the text
    if (strcmp(typed, SECRET) == 0) {
      Serial.println("Correct! Unlocked for 5 seconds.");
      lock.write(90);
      delay(5000);
      lock.write(0);
    } else {
      Serial.println("Wrong code!");
      tone(BUZZER_PIN, 200, 800);
    }
    typedCount = 0;
  } else if (typedCount < 8) {
    typed[typedCount++] = key;
    Serial.print('*');  // show stars, not the real keys
  }
}

#include <TM1637Display.h>

TM1637Display display(2, 3);
const int KNOB = A0, START_BUTTON = 4, BUZZER = 8;

void showTime(long totalSeconds, bool colon) {
  int minutes = totalSeconds / 60;
  int seconds = totalSeconds % 60;
  display.showNumberDecEx(minutes * 100 + seconds, colon ? 0b01000000 : 0, true);
}

void setup() {
  pinMode(START_BUTTON, INPUT_PULLUP);
  pinMode(BUZZER, OUTPUT);
  display.setBrightness(5);
}

void loop() {
  // Setting mode: the knob picks the minutes.
  int minutes = map(analogRead(KNOB), 0, 1023, 1, 60);
  showTime(minutes * 60L, true);

  if (digitalRead(START_BUTTON) == LOW) {
    while (digitalRead(START_BUTTON) == LOW) delay(10);
    long remaining = minutes * 60L;
    unsigned long lastTick = millis();

    while (remaining > 0) {
      if (millis() - lastTick >= 1000) {
        lastTick += 1000;
        remaining--;
      }
      showTime(remaining, (millis() / 500) % 2 == 0);  // blinking colon while running
      if (digitalRead(START_BUTTON) == LOW) {          // press again to cancel
        while (digitalRead(START_BUTTON) == LOW) delay(10);
        return;
      }
    }

    // Time's up: beep until the button is pressed.
    while (digitalRead(START_BUTTON) == HIGH) {
      tone(BUZZER, 2000, 150);
      showTime(0, true);
      delay(300);
      display.clear();
      delay(300);
    }
    while (digitalRead(START_BUTTON) == LOW) delay(10);
  }
}

const int FIRST_PIN = 2;
const int LED_COUNT = 8;  // pins 2, 3, 4, 5, 6, 7, 8, 9

void setup() {
  for (int i = 0; i < LED_COUNT; i++) pinMode(FIRST_PIN + i, OUTPUT);
}

void lightOnly(int which) {
  for (int i = 0; i < LED_COUNT; i++) {
    digitalWrite(FIRST_PIN + i, i == which ? HIGH : LOW);
  }
}

int speedDelay() {
  return map(analogRead(A0), 0, 1023, 20, 200);  // knob: 20 ms to 200 ms
}

void loop() {
  for (int i = 0; i < LED_COUNT; i++) {  // go right
    lightOnly(i);
    delay(speedDelay());
  }
  for (int i = LED_COUNT - 2; i > 0; i--) {  // come back (skip the ends so they don't double)
    lightOnly(i);
    delay(speedDelay());
  }
}

const int ENA = 5, IN1 = 7, IN2 = 8;   // left motor
const int ENB = 6, IN3 = 9, IN4 = 10;  // right motor

// speed: -255 (full backward) to 255 (full forward)
void setMotor(int en, int inA, int inB, int speed) {
  digitalWrite(inA, speed > 0 ? HIGH : LOW);
  digitalWrite(inB, speed < 0 ? HIGH : LOW);
  analogWrite(en, abs(speed));
}

void drive(int left, int right, int ms) {
  setMotor(ENA, IN1, IN2, left);
  setMotor(ENB, IN3, IN4, right);
  delay(ms);
}

void setup() {
  int pins[] = {ENA, IN1, IN2, ENB, IN3, IN4};
  for (int i = 0; i < 6; i++) pinMode(pins[i], OUTPUT);
  Serial.begin(9600);
}

void loop() {
  Serial.println("Forward");    drive(200, 200, 1500);
  Serial.println("Stop");       drive(0, 0, 500);
  Serial.println("Backward");   drive(-200, -200, 1500);
  Serial.println("Stop");       drive(0, 0, 500);
  Serial.println("Spin left");  drive(-180, 180, 800);
  Serial.println("Spin right"); drive(180, -180, 800);
  Serial.println("Stop");       drive(0, 0, 2000);
}

#include <EEPROM.h>

const int LED = 9, BUTTON = 2;
const int SAVE_ADDRESS = 10;
const byte LEVELS[] = {0, 20, 60, 130, 255};
const byte LEVEL_COUNT = 5;
byte level;
bool lastButton = HIGH;

void setup() {
  pinMode(LED, OUTPUT);
  pinMode(BUTTON, INPUT_PULLUP);
  level = EEPROM.read(SAVE_ADDRESS);
  if (level >= LEVEL_COUNT) level = 2;  // first time ever: a medium setting
  analogWrite(LED, LEVELS[level]);
}

void loop() {
  bool button = digitalRead(BUTTON);
  if (button == LOW && lastButton == HIGH) {
    level = (level + 1) % LEVEL_COUNT;
    analogWrite(LED, LEVELS[level]);
    EEPROM.update(SAVE_ADDRESS, level);  // update skips the write if it's the same, saving wear
    delay(40);
  }
  lastButton = button;
}

const int LASER_PIN = 7;
const int SENSOR_PIN = A0;
const int BUZZER_PIN = 8;
const int RESET_PIN = 2;

int threshold = 0;
bool alarm = false;

void setup() {
  pinMode(LASER_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(RESET_PIN, INPUT_PULLUP);
  Serial.begin(9600);

  digitalWrite(LASER_PIN, HIGH);
  delay(500);
  // Learn how bright the laser is, then trip at 70% of that.
  int laserLevel = analogRead(SENSOR_PIN);
  threshold = laserLevel * 7 / 10;
  Serial.print("Laser level ");
  Serial.print(laserLevel);
  Serial.print(", alarm below ");
  Serial.println(threshold);
}

void loop() {
  if (!alarm && analogRead(SENSOR_PIN) < threshold) {
    alarm = true;
    Serial.println("BEAM BROKEN! Press the button to reset.");
  }

  if (alarm) {
    tone(BUZZER_PIN, 1500, 150);
    delay(300);
    if (digitalRead(RESET_PIN) == LOW) {
      alarm = false;
      noTone(BUZZER_PIN);
      Serial.println("Alarm reset.");
      delay(500);
    }
  }
}

