#include <Wire.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);
const int START_STOP = 2, LAP_RESET = 3;

bool running = false;
unsigned long startTime = 0;  // when we pressed start
unsigned long saved = 0;      // time counted before the last stop
bool lastStart = HIGH, lastLap = HIGH;

unsigned long elapsed() {
  return running ? saved + (millis() - startTime) : saved;
}

void printTime(unsigned long ms) {
  unsigned long minutes = ms / 60000;
  unsigned long seconds = (ms / 1000) % 60;
  unsigned long hundredths = (ms / 10) % 100;
  if (minutes < 10) lcd.print('0');
  lcd.print(minutes);
  lcd.print(':');
  if (seconds < 10) lcd.print('0');
  lcd.print(seconds);
  lcd.print('.');
  if (hundredths < 10) lcd.print('0');
  lcd.print(hundredths);
}

void setup() {
  pinMode(START_STOP, INPUT_PULLUP);
  pinMode(LAP_RESET, INPUT_PULLUP);
  lcd.init();
  lcd.backlight();
}

void loop() {
  bool start = digitalRead(START_STOP), lap = digitalRead(LAP_RESET);

  if (start == LOW && lastStart == HIGH) {
    if (running) saved = elapsed();  // stopping: remember the time
    else startTime = millis();       // starting: note the start moment
    running = !running;
    delay(20);
  }
  if (lap == LOW && lastLap == HIGH) {
    if (running) {  // while running: show a lap time
      lcd.setCursor(0, 1);
      lcd.print("Lap ");
      printTime(elapsed());
    } else {        // while stopped: reset everything
      saved = 0;
      lcd.clear();
    }
    delay(20);
  }
  lastStart = start;
  lastLap = lap;

  lcd.setCursor(0, 0);
  lcd.print(running ? "RUN  " : "STOP ");
  printTime(elapsed());
  delay(30);
}

class Blinker {
public:
  Blinker(int pin, unsigned long onMs, unsigned long offMs)
      : pin_(pin), onMs_(onMs), offMs_(offMs) {}

  void begin() {
    pinMode(pin_, OUTPUT);
  }

  // Call this as often as possible. It decides by itself if it is time to switch.
  void update() {
    unsigned long now = millis();
    unsigned long wait = on_ ? onMs_ : offMs_;
    if (now - lastChange_ >= wait) {
      on_ = !on_;
      digitalWrite(pin_, on_ ? HIGH : LOW);
      lastChange_ = now;
    }
  }

private:
  int pin_;
  unsigned long onMs_, offMs_;
  bool on_ = false;
  unsigned long lastChange_ = 0;
};

// Four objects from one class, each with its own timing.
Blinker leds[] = {
  Blinker(3, 100, 900),  // quick flash once a second
  Blinker(4, 500, 500),  // steady blink
  Blinker(5, 50, 150),   // fast flicker
  Blinker(6, 2000, 1000) // long on, short off
};

void setup() {
  for (Blinker &b : leds) b.begin();
}

void loop() {
  for (Blinker &b : leds) b.update();
}

// Dot positions:  TL=0  TR=1
//                 ML=2  C=3  MR=4
//                 BL=5  BR=6
const int DOTS[7] = {2, 3, 4, 5, 6, 7, 8};
const int BUTTON = 10;

// Which dots are on for faces 1 to 6 (bit 0 = TL ... bit 6 = BR).
const byte FACES[7] = {
  0,
  0b0001000,  // 1: center
  0b0100010,  // 2: top-right, bottom-left
  0b0101010,  // 3: diagonal
  0b1100011,  // 4: corners
  0b1101011,  // 5: corners + center
  0b1110111   // 6: two columns
};

void showFace(int n) {
  for (int d = 0; d < 7; d++) digitalWrite(DOTS[d], bitRead(FACES[n], d));
}

void setup() {
  for (int d = 0; d < 7; d++) pinMode(DOTS[d], OUTPUT);
  pinMode(BUTTON, INPUT_PULLUP);
  randomSeed(analogRead(A0));
  showFace(6);
}

void loop() {
  if (digitalRead(BUTTON) == LOW) {
    for (int i = 0; i < 15; i++) {  // tumble
      showFace(random(1, 7));
      delay(40 + i * 10);
    }
    showFace(random(1, 7));
    while (digitalRead(BUTTON) == LOW) delay(10);
  }
}

const int POT_PIN = A0;
const int LED_PIN = 9;  // PWM pin (has a ~ next to it)

void setup() {
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  int knob = analogRead(POT_PIN);  // 0 to 1023
  // analogWrite only goes up to 255, so divide by 4.
  int brightness = knob / 4;
  analogWrite(LED_PIN, brightness);
  delay(10);
}

const int LIGHT_PIN = A0;
const int LED_PIN = 9;  // must be a ~ pin: 3, 5, 6, 9, 10 or 11 on an Uno

float smoothLight = 512;  // a running average stops flicker

void setup() {
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  int raw = analogRead(LIGHT_PIN);
  // Move 10% of the way toward the new reading each time.
  smoothLight = smoothLight * 0.9 + raw * 0.1;

  // Bright room (1023) -> LED off (0). Dark room (0) -> LED full (255).
  int brightness = map((int)smoothLight, 0, 1023, 255, 0);
  brightness = constrain(brightness, 0, 255);
  analogWrite(LED_PIN, brightness);
  delay(20);
}

const int LIGHT_PIN = A0;

