const int BUZZER = 8;
int question = 0;
int score = 0;
int answer;

void ask() {
  int a = random(2, 13);
  int b = random(2, 13);
  int kind = random(3);
  Serial.print("Question ");
  Serial.print(question + 1);
  Serial.print(": ");
  Serial.print(a);
  if (kind == 0) { Serial.print(" + "); answer = a + b; }
  else if (kind == 1) { Serial.print(" - "); answer = a - b; }
  else { Serial.print(" x "); answer = a * b; }
  Serial.print(b);
  Serial.println(" = ?");
}

void setup() {
  pinMode(BUZZER, OUTPUT);
  Serial.begin(9600);
  randomSeed(analogRead(A0));
  Serial.println("Math quiz! 10 questions. Go!");
  ask();
}

void loop() {
  if (!Serial.available()) return;
  long typed = Serial.parseInt();  // also reads negative numbers like -3
  while (Serial.available()) Serial.read();

  if (typed == answer) {
    Serial.println("Correct!");
    score++;
    tone(BUZZER, 1500, 150);
  } else {
    Serial.print("Oops, it was ");
    Serial.println(answer);
    tone(BUZZER, 200, 400);
  }

  question++;
  if (question == 10) {
    Serial.print("\nYou scored ");
    Serial.print(score);
    Serial.println(" out of 10!");
    if (score == 10) Serial.println("PERFECT! You're a math wizard.");
    Serial.println("\nNew quiz starting...");
    question = 0;
    score = 0;
    delay(2000);
  }
  ask();
}

const int ENA = 5, IN1 = 7, IN2 = 8, ENB = 6, IN3 = 9, IN4 = 10;
const int TRIG = A2, ECHO = A3, EDGE_SENSOR = A0, START_BUTTON = 2;

void motors(int left, int right) {
  digitalWrite(IN1, left > 0);
  digitalWrite(IN2, left < 0);
  analogWrite(ENA, abs(left));
  digitalWrite(IN3, right > 0);
  digitalWrite(IN4, right < 0);
  analogWrite(ENB, abs(right));
}

long distanceCm() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  unsigned long d = pulseIn(ECHO, HIGH, 15000UL);
  return d == 0 ? 200 : d / 58;
}

void setup() {
  int pins[] = {ENA, IN1, IN2, ENB, IN3, IN4, TRIG};
  for (int i = 0; i < 7; i++) pinMode(pins[i], OUTPUT);
  pinMode(START_BUTTON, INPUT_PULLUP);
  pinMode(LED_BUILTIN, OUTPUT);

  while (digitalRead(START_BUTTON) == HIGH) {}  // wait for the start button
  for (int i = 0; i < 5; i++) {                // the rules say wait 5 seconds
    digitalWrite(LED_BUILTIN, HIGH);
    delay(500);
    digitalWrite(LED_BUILTIN, LOW);
    delay(500);
  }
}

void loop() {
  // Most line modules read LOW over the white edge (light bounces back).
  if (digitalRead(EDGE_SENSOR) == LOW) {
    motors(-255, -255);  // edge! reverse fast
    delay(300);
    motors(200, -200);   // and turn around
    delay(350);
    return;
  }

  if (distanceCm() < 40) {
    motors(255, 255);    // enemy in front: CHARGE!
  } else {
    motors(140, -140);   // spin slowly to search
  }
}

#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <DHT.h>

DHT dht(2, DHT11);
LiquidCrystal_I2C lcd(0x27, 16, 2);
const int PAGE_BUTTON = 3;

float tempC = 0, humidity = 0;
float lowest = 999, highest = -999;
int page = 0;
unsigned long lastRead = 0;
bool lastButton = HIGH;

void readSensors() {
  float t = dht.readTemperature();
  float h = dht.readHumidity();
  if (isnan(t) || isnan(h)) return;  // keep the old values on a bad read
  tempC = t;
  humidity = h;
  if (t < lowest) lowest = t;
  if (t > highest) highest = t;
}

void drawPage() {
  lcd.clear();
  if (page == 0) {
    lcd.print("Temp: ");
    lcd.print(tempC, 1);
    lcd.print(" C");
    lcd.setCursor(0, 1);
    lcd.print("Humid: ");
    lcd.print(humidity, 0);
    lcd.print(" %");
  } else if (page == 1) {
    int light = analogRead(A0);
    lcd.print("Light: ");
    lcd.print(light);
    lcd.setCursor(0, 1);
    lcd.print(light < 200 ? "Night" : (light < 700 ? "Cloudy" : "Sunny"));
  } else {
    lcd.print("Low:  ");
    lcd.print(lowest, 1);
    lcd.print(" C");
    lcd.setCursor(0, 1);
    lcd.print("High: ");
    lcd.print(highest, 1);
    lcd.print(" C");
  }
}

void setup() {
  pinMode(PAGE_BUTTON, INPUT_PULLUP);
  dht.begin();
  lcd.init();
  lcd.backlight();
  delay(1000);
  readSensors();
  drawPage();
}

void loop() {
  bool button = digitalRead(PAGE_BUTTON);
  if (button == LOW && lastButton == HIGH) {
    page = (page + 1) % 3;
    drawPage();
    delay(40);
  }
  lastButton = button;

  if (millis() - lastRead >= 3000) {  // fresh readings every 3 seconds
    lastRead = millis();
    readSensors();
    drawPage();
  }
}

const int R = 9, G = 10, B = 11, BUTTON = 2;
int mode = 0;
const int MODES = 5;
bool lastButton = HIGH;

void color(int r, int g, int b) {
  analogWrite(R, r);
  analogWrite(G, g);
  analogWrite(B, b);
}

void setup() {
  pinMode(R, OUTPUT);
  pinMode(G, OUTPUT);
  pinMode(B, OUTPUT);
  pinMode(BUTTON, INPUT_PULLUP);
}

void loop() {
  bool button = digitalRead(BUTTON);
  if (button == LOW && lastButton == HIGH) {  // just pressed
    mode = (mode + 1) % MODES;
    delay(40);  // tiny debounce
  }
  lastButton = button;

  unsigned long t = millis();
  switch (mode) {
    case 0: color(255, 90, 10); break;   // warm
    case 1: color(40, 120, 255); break;  // cool
    case 2:                              // party: new color every 150 ms
      if ((t / 150) % 3 == 0) color(255, 0, 0);
      else if ((t / 150) % 3 == 1) color(0, 255, 0);
      else color(0, 0, 255);
      break;
    case 3: {                            // slow rainbow using sine waves
      float s = t / 1000.0;
      color((sin(s) + 1) * 127, (sin(s + 2.1) + 1) * 127, (sin(s + 4.2) + 1) * 127);
      break;
    }
    default: color(0, 0, 0); break;      // off
  }
}

const int LED = 13, BUZZER = 8;
const int UNIT = 120;  // ms for one dot

// Morse for A to Z, then 0 to 9.
const char *LETTERS[26] = {".-", "-...", "-.-.", "-..", ".", "..-.", "--.", "....", "..", ".---",
                           "-.-", ".-..", "--", "-.", "---", ".--.", "--.-", ".-.", "...", "-",
                           "..-", "...-", ".--", "-..-", "-.--", "--.."};
const char *DIGITS[10] = {"-----", ".----", "..---", "...--", "....-",
                          ".....", "-....", "--...", "---..", "----."};

void signal(int units) {
  digitalWrite(LED, HIGH);
  tone(BUZZER, 700);
  delay(UNIT * units);
  digitalWrite(LED, LOW);
  noTone(BUZZER);
  delay(UNIT);  // gap inside a letter
}

void sendChar(char c) {
  c = toupper(c);
  const char *code = nullptr;
  if (c >= 'A' && c <= 'Z') code = LETTERS[c - 'A'];
  else if (c >= '0' && c <= '9') code = DIGITS[c - '0'];
  else if (c == ' ') { Serial.print(" / "); delay(UNIT * 4); return; }  // word gap
  if (code == nullptr) return;  // skip symbols we don't know

  Serial.print(code);
  Serial.print(' ');
  for (int i = 0; code[i] != '\0'; i++) {
    signal(code[i] == '.' ? 1 : 3);  // a dash is 3 dots long
  }
  delay(UNIT * 2);  // gap between letters
}

void setup() {
  pinMode(LED, OUTPUT);
  pinMode(BUZZER, OUTPUT);
  Serial.begin(9600);
  Serial.println("Type a message:");
}

void loop() {
  if (Serial.available()) {
    char c = Serial.read();
    if (c == '\n' || c == '\r') Serial.println();
    else sendChar(c);
  }
}

const int PIR_PIN = 2;
const int LIGHT_PIN = 9;
const unsigned long STAY_ON_MS = 20000;  // 20 seconds

unsigned long lastMotionTime = 0;
bool lightOn = false;

void setup() {
  pinMode(PIR_PIN, INPUT);
  pinMode(LIGHT_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  // Every time we see motion, restart the timer.
  if (digitalRead(PIR_PIN) == HIGH) {
    lastMotionTime = millis();
    if (!lightOn) {
      lightOn = true;
      digitalWrite(LIGHT_PIN, HIGH);
      Serial.println("Light ON");
    }
  }

  // millis() - start is the safe way to measure time, even when millis wraps around.
  if (lightOn && millis() - lastMotionTime >= STAY_ON_MS) {
    lightOn = false;
    digitalWrite(LIGHT_PIN, LOW);
    Serial.println("No motion for a while, light off");
  }
}

const int PIR_PIN = 2;
int lastState = LOW;
unsigned long count = 0;

void setup() {
  pinMode(PIR_PIN, INPUT);
  Serial.begin(9600);
  Serial.println("Counting visitors...");
}

void loop() {
  int state = digitalRead(PIR_PIN);

  // Count only the moment it changes from LOW to HIGH (a "rising edge").
  if (state == HIGH && lastState == LOW) {
    count++;
    Serial.print("Visitor number ");
    Serial.print(count);
    Serial.print(" at ");
    Serial.print(millis() / 1000);
    Serial.println(" seconds");
  }
  lastState = state;
  delay(20);
}

#include <Wire.h>

const int MPU_ADDRESS = 0x68;

void setup() {
  Serial.begin(9600);
  Wire.begin();
  // Wake the chip up: write 0 to the power register (0x6B).
  Wire.beginTransmission(MPU_ADDRESS);
  Wire.write(0x6B);
  Wire.write(0);
  Wire.endTransmission();
}

// Reads two bytes and joins them into one signed number.
int16_t read16() {
  uint16_t high = Wire.read();  // unsigned, so shifting it left is safe
  uint16_t low = Wire.read();
  return (int16_t)((high << 8) | low);
}

void loop() {
  // Start reading at the accelerometer register (0x3B): 6 bytes for X, Y, Z.
  Wire.beginTransmission(MPU_ADDRESS);
  Wire.write(0x3B);
  Wire.endTransmission(false);
  Wire.requestFrom(MPU_ADDRESS, 6);
  if (Wire.available() < 6) {
    Serial.println("MPU6050 not found, check wires");
    delay(500);
    return;
  }

  float ax = read16() / 16384.0;  // 16384 = 1 g on the default setting
  float ay = read16() / 16384.0;
  float az = read16() / 16384.0;

  // Gravity always points down, so its direction tells us the tilt.
  float pitch = atan2(ax, sqrt(ay * ay + az * az)) * RAD_TO_DEG;
  float roll = atan2(ay, az) * RAD_TO_DEG;

  Serial.print("Pitch: ");
  Serial.print(pitch, 1);
  Serial.print("  Roll: ");
  Serial.println(roll, 1);
  delay(100);
}

const int GAS_PIN = A0;
