  delay(60000);

  // Average 20 readings to learn what clean air looks like.
  long total = 0;
  for (int i = 0; i < 20; i++) {
    total += analogRead(GAS_PIN);
    delay(100);
  }
  cleanAir = total / 20;
  Serial.print("Clean air level: ");
  Serial.println(cleanAir);
}

void loop() {
