  int lit = map(analogRead(A0), 0, 1023, 0, NUM_LEDS);

  for (int i = 0; i < NUM_LEDS; i++) {
    if (i >= lit) {
      strip.setPixelColor(i, 0);  // off
    } else if (i < NUM_LEDS * 6 / 10) {
      strip.setPixelColor(i, 0, 255, 0);    // first 60%: green
