const int SENSOR_PIN = A0;
const int LED_PIN = 9;  // a ~PWM pin so we can dim it

// Change these after watching the Serial Monitor in your room.
const int DARK_READING = 200;    // reading when it's dark
const int BRIGHT_READING = 800;  // reading when it's bright

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int light = analogRead(SENSOR_PIN);  // 0 (dark) to 1023 (bright)

  // Dark room -> bright LED. Bright room -> LED off.
  int brightness = map(light, DARK_READING, BRIGHT_READING, 255, 0);
  brightness = constrain(brightness, 0, 255);
  analogWrite(LED_PIN, brightness);

  Serial.print("Light: ");
  Serial.print(light);
  Serial.print("  LED: ");
  Serial.println(brightness);

  delay(100);
}

const int THERM_PIN = A0;
const float SERIES_RESISTOR = 10000.0;  // the fixed 10k resistor
const float NOMINAL_RESISTANCE = 10000.0;  // thermistor is 10k at 25 C
const float NOMINAL_TEMP = 25.0;
const float BETA = 3950.0;  // from the thermistor's data sheet

void setup() {
  Serial.begin(9600);
}

void loop() {
  int reading = analogRead(THERM_PIN);
  if (reading <= 0 || reading >= 1023) {
    Serial.println("Check the wiring!");
    delay(1000);
    return;
  }

  // Thermistor on top, resistor on the bottom: work out the thermistor's resistance.
  float resistance = SERIES_RESISTOR * (1023.0 / reading - 1.0);

  // Beta equation: 1/T = 1/T0 + (1/B) * ln(R/R0), with T in Kelvin.
  float kelvin = 1.0 / (1.0 / (NOMINAL_TEMP + 273.15) + log(resistance / NOMINAL_RESISTANCE) / BETA);
  float tempC = kelvin - 273.15;

  Serial.print("Resistance: ");
  Serial.print(resistance, 0);
  Serial.print(" ohms   Temperature: ");
  Serial.print(tempC, 1);
  Serial.println(" C");
  delay(1000);
}

const int ENA = 5, IN1 = 7, IN2 = 8, ENB = 6, IN3 = 9, IN4 = 10;
const int TRIG = A2, ECHO = A3;
const int STOP_DISTANCE = 25;  // cm

void motors(int left, int right) {
  digitalWrite(IN1, left > 0);
  digitalWrite(IN2, left < 0);
  analogWrite(ENA, abs(left));
  digitalWrite(IN3, right > 0);
  digitalWrite(IN4, right < 0);
  analogWrite(ENB, abs(right));
}

long distanceCm() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  unsigned long d = pulseIn(ECHO, HIGH, 30000UL);
  return d == 0 ? 400 : d / 58;  // no echo = nothing close
}

void setup() {
  int pins[] = {ENA, IN1, IN2, ENB, IN3, IN4, TRIG};
  for (int i = 0; i < 7; i++) pinMode(pins[i], OUTPUT);
  pinMode(ECHO, INPUT);
  randomSeed(analogRead(A0));
  delay(2000);
}

void loop() {
  if (distanceCm() > STOP_DISTANCE) {
    motors(170, 170);  // all clear
  } else {
    motors(0, 0);
    delay(200);
    motors(-150, -150);  // back up
    delay(400);
    if (random(2) == 0) motors(-160, 160);  // spin left
    else motors(160, -160);                 // or right
    delay(random(300, 700));
    motors(0, 0);
    delay(100);
  }
  delay(30);
}

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

Adafruit_SSD1306 display(128, 64, &Wire, -1);
const int RADIUS = 4;
float x = 20, y = 10;     // position
float vx = 2.2, vy = 0;   // speed
const float GRAVITY = 0.25;
const float BOUNCE = 0.85;  // keeps 85% of the speed on each bounce

void setup() {
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
}

void loop() {
  vy += GRAVITY;  // gravity pulls down every frame
  x += vx;
  y += vy;

  // Floor and ceiling.
  if (y > 63 - RADIUS) { y = 63 - RADIUS; vy = -vy * BOUNCE; }
  if (y < RADIUS) { y = RADIUS; vy = -vy; }
  // Walls.
  if (x > 127 - RADIUS) { x = 127 - RADIUS; vx = -vx; }
  if (x < RADIUS) { x = RADIUS; vx = -vx; }

  // When it is almost stopped, throw it up again.
  if (fabs(vy) < 0.6 && y >= 63 - RADIUS - 1) vy = -6;

  display.clearDisplay();
  display.drawRect(0, 0, 128, 64, SSD1306_WHITE);
  display.fillCircle((int)x, (int)y, RADIUS, SSD1306_WHITE);
  display.display();
  delay(16);  // about 60 frames a second (the screen may be a bit slower)
}

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

Adafruit_SSD1306 display(128, 64, &Wire, -1);
const int BUTTON = 2;
const int GAP = 24;
const int PIPE_W = 10;

float birdY, birdSpeed;
int pipeX, gapY, score;
bool lastButton = HIGH;

void newGame() {
  birdY = 32;
  birdSpeed = 0;
  pipeX = 128;
  gapY = random(8, 64 - GAP - 8);
  score = 0;
}

void setup() {
  pinMode(BUTTON, INPUT_PULLUP);
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  display.setTextColor(SSD1306_WHITE);
  randomSeed(analogRead(A0));
  newGame();
}

void loop() {
  bool button = digitalRead(BUTTON);
  if (button == LOW && lastButton == HIGH) birdSpeed = -3.2;  // flap!
  lastButton = button;

  birdSpeed += 0.35;  // gravity
  birdY += birdSpeed;
  pipeX -= 2;
  if (pipeX < -PIPE_W) {  // pipe left the screen: make a new one
    pipeX = 128;
    gapY = random(8, 64 - GAP - 8);
    score++;
  }

  // Crash check: hit the floor, the ceiling or a pipe (the bird sits at x = 20).
  bool inPipeColumn = pipeX < 24 && pipeX + PIPE_W > 16;
  bool outsideGap = birdY - 3 < gapY || birdY + 3 > gapY + GAP;
  if (birdY > 63 || birdY < 0 || (inPipeColumn && outsideGap)) {
    display.clearDisplay();
    display.setTextSize(2);
    display.setCursor(10, 10);
    display.print("GAME OVER");
    display.setTextSize(1);
    display.setCursor(34, 40);
    display.print("Score: ");
    display.print(score);
    display.display();
    delay(1500);
    while (digitalRead(BUTTON) == HIGH) {}
    newGame();
    return;
  }

  display.clearDisplay();
  display.fillRect(pipeX, 0, PIPE_W, gapY, SSD1306_WHITE);
  display.fillRect(pipeX, gapY + GAP, PIPE_W, 64 - gapY - GAP, SSD1306_WHITE);
  display.fillCircle(20, (int)birdY, 3, SSD1306_WHITE);
  display.setTextSize(1);
  display.setCursor(110, 0);
  display.print(score);
  display.display();
  delay(20);
}

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

Adafruit_SSD1306 display(128, 64, &Wire, -1);
const int GRAPH_TOP = 12;
const int GRAPH_HEIGHT = 52;
byte history[128];  // one height for each column of the screen

void setup() {
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  for (int i = 0; i < 128; i++) history[i] = 0;
}

void loop() {
  int value = analogRead(A0);

  // Slide everything one step left and add the new point on the right.
  for (int i = 0; i < 127; i++) history[i] = history[i + 1];
  history[127] = map(value, 0, 1023, 0, GRAPH_HEIGHT - 1);

  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.print("A0: ");
  display.print(value);

  for (int i = 1; i < 128; i++) {
    int y1 = 63 - history[i - 1];
    int y2 = 63 - history[i];
    display.drawLine(i - 1, y1, i, y2, SSD1306_WHITE);
  }
  display.drawFastHLine(0, GRAPH_TOP - 1, 128, SSD1306_WHITE);
  display.display();
  delay(50);
}

#include <Wire.h>
