}

const int FOCUS_LED = 9, BREAK_LED = 10, BUZZER = 8, BUTTON = 2;
const unsigned long FOCUS_MS = 25UL * 60UL * 1000UL;  // UL = unsigned long, so the number fits
const unsigned long BREAK_MS = 5UL * 60UL * 1000UL;

void chime(int times) {
  for (int i = 0; i < times; i++) {
    tone(BUZZER, 1200, 150);
    delay(300);
  }
}

// Runs one block of time with a slowly pulsing LED.
void runBlock(int ledPin, unsigned long length, const char *name) {
  Serial.print(name);
  Serial.println(" started!");
  unsigned long start = millis();
  unsigned long lastReport = 0;
  while (millis() - start < length) {
    unsigned long passed = millis() - start;
    // Gentle pulse so you can tell it is running.
    analogWrite(ledPin, 40 + (passed / 8) % 200);
    if (passed - lastReport >= 60000UL) {
      lastReport = passed;
      Serial.print((length - passed) / 60000UL);
      Serial.println(" minutes left");
    }
  }
  analogWrite(ledPin, 0);
}

void setup() {
  pinMode(FOCUS_LED, OUTPUT);
  pinMode(BREAK_LED, OUTPUT);
  pinMode(BUZZER, OUTPUT);
  pinMode(BUTTON, INPUT_PULLUP);
  Serial.begin(9600);
  Serial.println("Press the button to start studying!");
}

void loop() {
  if (digitalRead(BUTTON) == HIGH) return;
  chime(1);
  runBlock(FOCUS_LED, FOCUS_MS, "Focus time");
  chime(3);
  runBlock(BREAK_LED, BREAK_MS, "Break time");
  chime(2);
  Serial.println("Press the button for another round.");
}

#include <EEPROM.h>

const int LED = 9, BUTTON = 2;
const int RECORD_ADDRESS = 0;
unsigned long record;

void setup() {
  pinMode(LED, OUTPUT);
  pinMode(BUTTON, INPUT_PULLUP);
  Serial.begin(9600);
  randomSeed(analogRead(A0));

  EEPROM.get(RECORD_ADDRESS, record);
  // Empty EEPROM, or the button held at startup: clear the record.
  if (record == 0xFFFFFFFFUL || record == 0 || digitalRead(BUTTON) == LOW) {
    record = 99999;
    EEPROM.put(RECORD_ADDRESS, record);
    Serial.println("Record cleared.");
  }
  Serial.print("Record to beat: ");
  Serial.print(record);
  Serial.println(" ms");
}

void loop() {
  while (digitalRead(BUTTON) == LOW) delay(10);
  delay(random(1500, 4000));
  if (digitalRead(BUTTON) == LOW) return;  // no holding the button down!

  digitalWrite(LED, HIGH);
  unsigned long start = millis();
  while (digitalRead(BUTTON) == HIGH) {}
  unsigned long reaction = millis() - start;
  digitalWrite(LED, LOW);

  Serial.print("You: ");
  Serial.print(reaction);
  Serial.println(" ms");
  if (reaction < record) {
    record = reaction;
    EEPROM.put(RECORD_ADDRESS, record);
    Serial.println("NEW RECORD! Saved forever (well, until someone beats it).");
  }
  delay(1000);
}

const int LED_PIN = 9;
const int BUTTON_PIN = 2;
unsigned long best = 0;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  Serial.begin(9600);
  randomSeed(analogRead(A0));
  Serial.println("Press the button as soon as the light comes on!");
}

void loop() {
  Serial.println("Get ready...");
  delay(1000);

  // Wait 1 to 4 seconds. Pressing early is cheating!
  unsigned long waitTime = random(1000, 4000);
  unsigned long waitStart = millis();
  while (millis() - waitStart < waitTime) {
    if (digitalRead(BUTTON_PIN) == LOW) {
      Serial.println("Too early! Wait for the light.");
      while (digitalRead(BUTTON_PIN) == LOW) delay(10);
      return;  // start the round again
    }
  }

  digitalWrite(LED_PIN, HIGH);
  unsigned long start = millis();
  while (digitalRead(BUTTON_PIN) == HIGH) {}  // wait for the press
  unsigned long reaction = millis() - start;
  digitalWrite(LED_PIN, LOW);

  Serial.print("Your time: ");
  Serial.print(reaction);
  Serial.println(" ms");
  if (best == 0 || reaction < best) {
    best = reaction;
    Serial.println("NEW BEST!");
  }
  Serial.print("Best so far: ");
  Serial.print(best);
  Serial.println(" ms\n");

  while (digitalRead(BUTTON_PIN) == LOW) delay(10);
  delay(1500);
}

