#include <Servo.h>

Servo joints[4];
const int SERVO_PINS[4] = {3, 5, 6, 9};
const int KNOB_PINS[4] = {A0, A1, A2, A3};
const int RECORD_BUTTON = 2, PLAY_BUTTON = 4;
const int MAX_POSES = 20;

byte poses[MAX_POSES][4];  // byte is enough: angles are 0 to 180
int poseCount = 0;

void moveTo(const byte target[4]) {
  // Move all joints together in 30 small steps.
  int start[4];
  for (int i = 0; i < 4; i++) start[i] = joints[i].read();
  for (int step = 1; step <= 30; step++) {
    for (int i = 0; i < 4; i++) {
      joints[i].write(start[i] + (target[i] - start[i]) * step / 30);
    }
    delay(20);
  }
}

void setup() {
  for (int i = 0; i < 4; i++) joints[i].attach(SERVO_PINS[i]);
  pinMode(RECORD_BUTTON, INPUT_PULLUP);
  pinMode(PLAY_BUTTON, INPUT_PULLUP);
  Serial.begin(9600);
}

void loop() {
  // Live mode: the knobs move the arm.
  byte live[4];
  for (int i = 0; i < 4; i++) {
    live[i] = map(analogRead(KNOB_PINS[i]), 0, 1023, 0, 180);
    joints[i].write(live[i]);
  }

  if (digitalRead(RECORD_BUTTON) == LOW && poseCount < MAX_POSES) {
    for (int i = 0; i < 4; i++) poses[poseCount][i] = live[i];
    poseCount++;
    Serial.print("Saved pose ");
    Serial.println(poseCount);
    while (digitalRead(RECORD_BUTTON) == LOW) delay(10);
  }

  if (digitalRead(PLAY_BUTTON) == LOW && poseCount > 0) {
    Serial.println("Playing back...");
    for (int p = 0; p < poseCount; p++) {
      moveTo(poses[p]);
      delay(300);
    }
    Serial.println("Done! Hold play while it finishes to clear the poses.");
    if (digitalRead(PLAY_BUTTON) == LOW) poseCount = 0;
    while (digitalRead(PLAY_BUTTON) == LOW) delay(10);
  }
  delay(20);
}

#include <Servo.h>

Servo joints[4];
const int SERVO_PINS[4] = {3, 5, 6, 9};
const int KNOB_PINS[4] = {A0, A1, A2, A3};
// Safe limits for each joint so the arm can't crash into itself.
const int MIN_ANGLE[4] = {0, 30, 20, 60};
const int MAX_ANGLE[4] = {180, 150, 160, 120};
float current[4] = {90, 90, 90, 90};

void setup() {
  for (int i = 0; i < 4; i++) {
    joints[i].attach(SERVO_PINS[i]);
    joints[i].write(90);
  }
}

void loop() {
  for (int i = 0; i < 4; i++) {
    int target = map(analogRead(KNOB_PINS[i]), 0, 1023, MIN_ANGLE[i], MAX_ANGLE[i]);
    // Move 20% of the way there each time: smooth, no sudden jerks.
    current[i] += (target - current[i]) * 0.2;
    joints[i].write((int)current[i]);
  }
  delay(20);
}

const int ENA = 5, IN1 = 7, IN2 = 8, ENB = 6, IN3 = 9, IN4 = 10;
int leftTrim = 0;   // added to the left motor speed
int rightTrim = 0;
const int BASE = 180;

void motors(int left, int right) {
  left = constrain(left, -255, 255);
  right = constrain(right, -255, 255);
  digitalWrite(IN1, left > 0);
  digitalWrite(IN2, left < 0);
  analogWrite(ENA, abs(left));
  digitalWrite(IN3, right > 0);
  digitalWrite(IN4, right < 0);
  analogWrite(ENB, abs(right));
}

void printTrims() {
  Serial.print("Left speed: ");
  Serial.print(BASE + leftTrim);
  Serial.print("   Right speed: ");
  Serial.println(BASE + rightTrim);
}

void setup() {
  int pins[] = {ENA, IN1, IN2, ENB, IN3, IN4};
  for (int i = 0; i < 6; i++) pinMode(pins[i], OUTPUT);
  Serial.begin(9600);
  Serial.println("If it veers LEFT, type r (slow the right motor). If it veers RIGHT, type l.");
  Serial.println("Type g to drive for 2 seconds. Copy the final numbers into your robot code!");
  printTrims();
}

void loop() {
  if (!Serial.available()) return;
  char c = Serial.read();
  if (c == 'l') { leftTrim -= 5; printTrims(); }
  if (c == 'r') { rightTrim -= 5; printTrims(); }
  if (c == 'g') {
    Serial.println("Driving...");
    motors(BASE + leftTrim, BASE + rightTrim);
    delay(2000);
    motors(0, 0);
  }
}

const int ENA = 5, IN1 = 7, IN2 = 8, ENB = 6, IN3 = 9, IN4 = 10;
const int LEFT_EDGE = A0, RIGHT_EDGE = A1;

void motors(int left, int right) {
  digitalWrite(IN1, left > 0);
  digitalWrite(IN2, left < 0);
  analogWrite(ENA, abs(left));
  digitalWrite(IN3, right > 0);
  digitalWrite(IN4, right < 0);
  analogWrite(ENB, abs(right));
}

void setup() {
  int pins[] = {ENA, IN1, IN2, ENB, IN3, IN4};
  for (int i = 0; i < 6; i++) pinMode(pins[i], OUTPUT);
  delay(2000);
}

void loop() {
  // IR obstacle modules output LOW when they see the table (light bounces back),
  // and HIGH over the edge where nothing bounces back.
  bool leftEdge = digitalRead(LEFT_EDGE) == HIGH;
  bool rightEdge = digitalRead(RIGHT_EDGE) == HIGH;

  if (leftEdge || rightEdge) {
    motors(0, 0);
    delay(100);
    motors(-150, -150);  // back away from the edge
    delay(400);
    // Turn away from the side that saw the edge.
    if (leftEdge) motors(150, -150);
    else motors(-150, 150);
    delay(400);
  } else {
    motors(130, 130);  // slow and careful
  }
}

const int WIN_LED = 4, LOSE_LED = 5;
int youWins = 0, arduinoWins = 0;
const char *NAMES[3] = {"Rock", "Paper", "Scissors"};

void setup() {
  pinMode(WIN_LED, OUTPUT);
  pinMode(LOSE_LED, OUTPUT);
  Serial.begin(9600);
  randomSeed(analogRead(A0));
  Serial.println("Type r (rock), p (paper) or s (scissors):");
}

void loop() {
  if (!Serial.available()) return;
  char c = Serial.read();
  int you;
  if (c == 'r') you = 0;
  else if (c == 'p') you = 1;
  else if (c == 's') you = 2;
  else return;  // ignore Enter and other keys

  int arduino = random(3);
  Serial.print("You: ");
  Serial.print(NAMES[you]);
  Serial.print("  Arduino: ");
  Serial.print(NAMES[arduino]);
  Serial.print("  -> ");

  digitalWrite(WIN_LED, LOW);
  digitalWrite(LOSE_LED, LOW);
  // Trick: paper(1) beats rock(0), scissors(2) beats paper(1), rock(0) beats scissors(2).
  if (you == arduino) {
    Serial.print("Tie!");
  } else if ((you - arduino + 3) % 3 == 1) {
    Serial.print("You win!");
    youWins++;
    digitalWrite(WIN_LED, HIGH);
  } else {
    Serial.print("Arduino wins!");
    arduinoWins++;
    digitalWrite(LOSE_LED, HIGH);
  }
  Serial.print("   Score ");
  Serial.print(youWins);
  Serial.print(" - ");
  Serial.println(arduinoWins);
}

const int CLK_PIN = 2;  // interrupt pin
const int DT_PIN = 3;
const int SW_PIN = 4;

volatile long position = 0;  // volatile: changed inside an interrupt
long lastPrinted = -1;

// Runs by itself every time CLK falls.
void onTurn() {
  // If DT is different from CLK, we turned clockwise.
  if (digitalRead(DT_PIN) != digitalRead(CLK_PIN)) {
    position++;
  } else {
    position--;
  }
}

void setup() {
  pinMode(CLK_PIN, INPUT_PULLUP);
  pinMode(DT_PIN, INPUT_PULLUP);
  pinMode(SW_PIN, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(CLK_PIN), onTurn, FALLING);
  Serial.begin(9600);
}

void loop() {
  // Copy the number with interrupts paused so it does not change halfway.
  noInterrupts();
  long now = position;
  interrupts();

  if (now != lastPrinted) {
    Serial.print("Position: ");
    Serial.println(now);
    lastPrinted = now;
  }

  if (digitalRead(SW_PIN) == LOW) {
    noInterrupts();
    position = 0;
    interrupts();
    delay(250);
  }
}

const int SENSOR = 2;
volatile unsigned long pulses = 0;

void onMagnet() {
  pulses++;
}

void setup() {
  pinMode(SENSOR, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(SENSOR), onMagnet, FALLING);
  Serial.begin(9600);
}

void loop() {
  delay(1000);  // count for one second

  noInterrupts();
  unsigned long count = pulses;
  pulses = 0;
  interrupts();

  // One magnet = one pulse per turn. Turns per second x 60 = turns per minute.
  unsigned long rpm = count * 60;
  Serial.print("Turns this second: ");
  Serial.print(count);
  Serial.print("   RPM: ");
  Serial.println(rpm);
}

#include <EEPROM.h>

// The "magic" number tells us the EEPROM really holds our settings and not junk.
const uint16_t MAGIC = 0xBEEF;

struct Settings {
  uint16_t magic;
  byte volume;
  byte brightness;
  char robotName[12];
};

Settings settings;

void resetSettings() {
  settings.magic = MAGIC;
  settings.volume = 5;
  settings.brightness = 128;
  strcpy(settings.robotName, "Robo");
  EEPROM.put(0, settings);
}

void show() {
  Serial.print("Name: ");
  Serial.print(settings.robotName);
  Serial.print("  Volume: ");
  Serial.print(settings.volume);
  Serial.print("  Brightness: ");
  Serial.println(settings.brightness);
}

void setup() {
  Serial.begin(9600);
  EEPROM.get(0, settings);  // load the whole struct in one go
  if (settings.magic != MAGIC) resetSettings();
  show();
  Serial.println("Commands: volume N, brightness N, name X, show, reset");
}

void loop() {
  if (!Serial.available()) return;
  String line = Serial.readStringUntil('\n');
  line.trim();

  if (line.startsWith("volume ")) {
    settings.volume = constrain(line.substring(7).toInt(), 0, 10);
  } else if (line.startsWith("brightness ")) {
    settings.brightness = constrain(line.substring(11).toInt(), 0, 255);
  } else if (line.startsWith("name ")) {
    // Copy at most 11 letters, leaving room for the end marker.
    strncpy(settings.robotName, line.substring(5).c_str(), sizeof(settings.robotName) - 1);
    settings.robotName[sizeof(settings.robotName) - 1] = '\0';
  } else if (line == "reset") {
    resetSettings();
  } else if (line != "show") {
    Serial.println("Unknown command");
    return;
  }
  EEPROM.put(0, settings);  // save after every change
  show();
}

const int PIEZO_PIN = A0;
const int LED_PIN = 13;
const int KNOCK_THRESHOLD = 60;     // raise this if it triggers by itself
const unsigned long WINDOW_MS = 2000;

int knocks = 0;
unsigned long firstKnock = 0;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int level = analogRead(PIEZO_PIN);
  if (level > KNOCK_THRESHOLD) {
    if (knocks == 0) firstKnock = millis();
    knocks++;
    Serial.print("Knock ");
    Serial.print(knocks);
    Serial.print(" (strength ");
    Serial.print(level);
    Serial.println(")");
    delay(120);  // skip the wobble of the same knock
  }

  if (knocks >= 3) {
    Serial.println("Secret knock accepted!");
    digitalWrite(LED_PIN, HIGH);
    delay(2000);
    digitalWrite(LED_PIN, LOW);
    knocks = 0;
  }

  // Too slow: start over.
  if (knocks > 0 && millis() - firstKnock > WINDOW_MS) {
    knocks = 0;
    Serial.println("Too slow, try again.");
  }
}

const unsigned long EVERY_MS = 5000;
unsigned long lastLog = 0;

void setup() {
  Serial.begin(9600);
  // The header row names each column.
  Serial.println("seconds,light,temperature_c");
}

void loop() {
  if (millis() - lastLog < EVERY_MS) return;
  lastLog = millis();

  int light = analogRead(A0);
  float volts = analogRead(A1) * 5.0 / 1024.0;
  float tempC = (volts - 0.5) * 100.0;  // TMP36 formula

  Serial.print(millis() / 1000);
  Serial.print(',');
  Serial.print(light);
  Serial.print(',');
  Serial.println(tempC, 1);
}

float t = 0;

void setup() {
  Serial.begin(9600);
}

void loop() {
  float sine = sin(t) * 100;
  float square = (sin(t) >= 0) ? 80 : -80;
  // fmod gives the remainder, so the sawtooth climbs and then drops back.
  float saw = fmod(t, TWO_PI) / TWO_PI * 200 - 100;

  // Name:value pairs separated by commas = one line per name.
  Serial.print("sine:");
  Serial.print(sine);
  Serial.print(",square:");
  Serial.print(square);
  Serial.print(",sawtooth:");
  Serial.println(saw);

  t += 0.1;
  if (t > 1000) t = 0;  // keep the number from growing forever
  delay(20);
}

#include <Servo.h>

Servo door;
