void flash(int length) {
  digitalWrite(LED_PIN, HIGH);
  delay(length);
  digitalWrite(LED_PIN, LOW);
  delay(DOT);  // gap between flashes in the same letter
}

void letterS() {
  for (int i = 0; i < 3; i++) flash(DOT);      // . . .
}

void letterO() {
  for (int i = 0; i < 3; i++) flash(DOT * 3);  // - - -
}

