const int FIRST_LED = 3;
const int LED_COUNT = 7;
const int TARGET = 3;  // the 4th LED (pin 6) is the jackpot
const int BUTTON = 2;
const int BUZZER = 11;
int level = 1;

void setup() {
  for (int i = 0; i < LED_COUNT; i++) pinMode(FIRST_LED + i, OUTPUT);
  pinMode(BUTTON, INPUT_PULLUP);
  Serial.begin(9600);
}

void loop() {
  int wait = max(30, 150 - level * 15);  // faster every level
  int pos = 0, dir = 1;

  while (true) {
    for (int i = 0; i < LED_COUNT; i++) digitalWrite(FIRST_LED + i, i == pos);
    // Check the button many times while this LED is lit.
    unsigned long start = millis();
    while (millis() - start < (unsigned long)wait) {
      if (digitalRead(BUTTON) == LOW) {
        if (pos == TARGET) {
          Serial.print("JACKPOT! Level ");
          Serial.println(++level);
          tone(BUZZER, 2000, 300);
        } else {
          Serial.println("Missed! Back to level 1.");
          level = 1;
          tone(BUZZER, 200, 500);
        }
        delay(800);
        while (digitalRead(BUTTON) == LOW) delay(10);
        return;
      }
    }
    pos += dir;
    if (pos == LED_COUNT - 1 || pos == 0) dir = -dir;  // bounce at the ends
  }
}

#include <DHT.h>

DHT dht(2, DHT11);
const int RELAY_PIN = 7;
const float TURN_ON_AT = 27.0;   // degrees C
const float TURN_OFF_AT = 25.0;  // a gap stops the fan clicking on and off

bool fanOn = false;

void setup() {
  Serial.begin(9600);
  dht.begin();
  pinMode(RELAY_PIN, OUTPUT);
  digitalWrite(RELAY_PIN, LOW);  // most relay modules: HIGH = on (some are the other way round)
}

void loop() {
  float tempC = dht.readTemperature();
  if (isnan(tempC)) {
    Serial.println("Sensor error");
    delay(2000);
    return;
  }

  // Only change when we pass a limit. This is called "hysteresis".
  if (!fanOn && tempC >= TURN_ON_AT) {
    fanOn = true;
  } else if (fanOn && tempC <= TURN_OFF_AT) {
    fanOn = false;
  }
  digitalWrite(RELAY_PIN, fanOn ? HIGH : LOW);

  Serial.print("Temp: ");
  Serial.print(tempC, 1);
  Serial.print(" C   Fan: ");
  Serial.println(fanOn ? "ON" : "off");
  delay(2000);
}

