const int CAR_RED = 4, CAR_YELLOW = 5, CAR_GREEN = 6, WALK_RED = 7, WALK_GREEN = 8;
const int BUTTON = 2, BUZZER = 9;

enum State { CARS_GO, CARS_SLOW, WALKERS_GO, WALKERS_HURRY };
State state = CARS_GO;
unsigned long stateStart = 0;
bool someoneWaiting = false;

void lights(int carR, int carY, int carG, int walkR, int walkG) {
  digitalWrite(CAR_RED, carR);
  digitalWrite(CAR_YELLOW, carY);
  digitalWrite(CAR_GREEN, carG);
  digitalWrite(WALK_RED, walkR);
  digitalWrite(WALK_GREEN, walkG);
}

void goTo(State next) {
  state = next;
  stateStart = millis();
}

void setup() {
  int pins[] = {CAR_RED, CAR_YELLOW, CAR_GREEN, WALK_RED, WALK_GREEN, BUZZER};
  for (int i = 0; i < 6; i++) pinMode(pins[i], OUTPUT);
  pinMode(BUTTON, INPUT_PULLUP);
}

void loop() {
  unsigned long inState = millis() - stateStart;  // how long we've been in this state
  if (digitalRead(BUTTON) == LOW) someoneWaiting = true;

  switch (state) {
    case CARS_GO:
      lights(LOW, LOW, HIGH, HIGH, LOW);
      // Cars get at least 5 seconds of green before walkers can cross.
      if (someoneWaiting && inState > 5000) goTo(CARS_SLOW);
      break;
    case CARS_SLOW:
      lights(LOW, HIGH, LOW, HIGH, LOW);
      if (inState > 2000) goTo(WALKERS_GO);
      break;
    case WALKERS_GO:
      lights(HIGH, LOW, LOW, LOW, HIGH);
      // Beep-beep while it's safe to walk.
      if ((inState / 300) % 2 == 0) tone(BUZZER, 1800); else noTone(BUZZER);
      someoneWaiting = false;
      if (inState > 6000) { noTone(BUZZER); goTo(WALKERS_HURRY); }
      break;
    case WALKERS_HURRY:
      // Flash the walking man: hurry up!
      lights(HIGH, LOW, LOW, LOW, (inState / 250) % 2 == 0);
      if (inState > 3000) goTo(CARS_GO);
      break;
  }
}

#include <IRremote.hpp>

const int ENA = 5, IN1 = 7, IN2 = 8, ENB = 6, IN3 = 9, IN4 = 10;
const uint16_t KEY_2 = 0x18, KEY_4 = 0x08, KEY_5 = 0x1C, KEY_6 = 0x5A, KEY_8 = 0x52;
unsigned long lastSignal = 0;

void motors(int left, int right) {
  digitalWrite(IN1, left > 0);
  digitalWrite(IN2, left < 0);
  analogWrite(ENA, abs(left));
  digitalWrite(IN3, right > 0);
  digitalWrite(IN4, right < 0);
  analogWrite(ENB, abs(right));
}

void setup() {
  int pins[] = {ENA, IN1, IN2, ENB, IN3, IN4};
  for (int i = 0; i < 6; i++) pinMode(pins[i], OUTPUT);
  IrReceiver.begin(12);
}

void loop() {
  if (IrReceiver.decode()) {
    uint16_t key = IrReceiver.decodedIRData.command;
    IrReceiver.resume();
    lastSignal = millis();  // holding a key keeps sending repeats, which keeps us moving

    if (key == KEY_2) motors(200, 200);
    else if (key == KEY_8) motors(-200, -200);
    else if (key == KEY_4) motors(-170, 170);
    else if (key == KEY_6) motors(170, -170);
    else if (key == KEY_5) motors(0, 0);
  }

  // Let go of the button for 250 ms and the car stops by itself.
  if (millis() - lastSignal > 250) motors(0, 0);
}

const int BUZZER_PIN = 8;
// Notes C D E F G A, each has its own LED on pins 2..7.
const int FREQ[] = {262, 294, 330, 349, 392, 440};
const char SONG[] = "CCGGAAG FFEEDDC GGFFEED GGFFEED CCGGAAG FFEEDDC";

void setup() {
  pinMode(BUZZER_PIN, OUTPUT);
  for (int pin = 2; pin <= 7; pin++) pinMode(pin, OUTPUT);
}

void loop() {
  for (int i = 0; SONG[i] != '\0'; i++) {
    char letter = SONG[i];
    if (letter == ' ') {  // a space is a rest
      delay(400);
      continue;
    }
    int n = letter - 'C';  // C->0, D->1, E->2, F->3, G->4
    if (letter == 'A') n = 5;  // A comes before C in the alphabet, so set it by hand
    // Is it the last note before a space or the end? Hold it longer.
    bool longNote = SONG[i + 1] == ' ' || SONG[i + 1] == '\0';
    int length = longNote ? 700 : 350;

    digitalWrite(2 + n, HIGH);
    tone(BUZZER_PIN, FREQ[n], length);
    delay(length + 50);
    digitalWrite(2 + n, LOW);
  }
  delay(2000);
}

#include <Wire.h>

const int MY_ADDRESS = 8;
const int LED = 9;
volatile byte brightness = 0;
volatile bool gotNew = false;

// Runs by itself whenever the sender sends bytes. Keep it short!
void onData(int howMany) {
  while (howMany-- > 0 && Wire.available()) {
    brightness = Wire.read();
  }
  gotNew = true;
}

void setup() {
  pinMode(LED, OUTPUT);
  Wire.begin(MY_ADDRESS);  // giving an address makes this board a helper (slave)
  Wire.onReceive(onData);
  Serial.begin(9600);
}

void loop() {
  if (gotNew) {
    gotNew = false;
    byte level = brightness;
    analogWrite(LED, level);
    Serial.print("Got ");
    Serial.println(level);
  }
}

