const int LEDS[4] = {8, 9, 10, 11};
const int BUTTONS[4] = {2, 3, 4, 5};
const int BUZZER = 12;
int score = 0;
int misses = 0;
unsigned long moleTime = 1000;  // how long a mole stays up

void setup() {
  for (int i = 0; i < 4; i++) {
    pinMode(LEDS[i], OUTPUT);
    pinMode(BUTTONS[i], INPUT_PULLUP);
  }
  Serial.begin(9600);
  randomSeed(analogRead(A0));
  Serial.println("Whack the moles! 3 misses and you're out.");
}

int buttonPressed() {
  for (int i = 0; i < 4; i++) {
    if (digitalRead(BUTTONS[i]) == LOW) return i;
  }
  return -1;
}

void loop() {
  int mole = random(4);
  digitalWrite(LEDS[mole], HIGH);
  unsigned long start = millis();
  int hit = -1;

  while (millis() - start < moleTime && hit == -1) {
    hit = buttonPressed();
  }
  digitalWrite(LEDS[mole], LOW);

  if (hit == mole) {
    score++;
    tone(BUZZER, 1500, 80);
    if (moleTime > 300) moleTime -= 40;  // faster each hit!
  } else {
    misses++;
    tone(BUZZER, 200, 300);
  }
  Serial.print("Score: ");
  Serial.print(score);
  Serial.print("  Misses: ");
  Serial.println(misses);

  while (buttonPressed() != -1) delay(5);  // wait for all buttons to be let go
  delay(random(200, 700));

  if (misses >= 3) {
    Serial.print("GAME OVER! Final score: ");
    Serial.println(score);
    score = 0;
    misses = 0;
    moleTime = 1000;
    delay(3000);
    Serial.println("New game!");
  }
}

#include <iostream>

const int ROWS = 6;
const int COLS = 10;

void printMap(const char map[ROWS][COLS + 1]) {
  for (int r = 0; r < ROWS; r++) {
    for (int c = 0; c < COLS; c++) std::cout << map[r][c];
    std::cout << "\n";
  }
}

int main() {
  // Each row is a string of 10 characters (+1 hidden end marker).
  char map[ROWS][COLS + 1] = {
    "##########",
    "#P...$...#",
    "#.##.##..#",
    "#..$...#$#",
    "#....$...#",
    "##########",
  };

  printMap(map);

  // Count the coins ($) by visiting every row and every column.
  int coins = 0;
  int playerRow = 0, playerCol = 0;
  for (int r = 0; r < ROWS; r++) {
    for (int c = 0; c < COLS; c++) {
      if (map[r][c] == '$') coins++;
      if (map[r][c] == 'P') { playerRow = r; playerCol = c; }
    }
  }
  std::cout << "\nCoins on the map: " << coins << "\n";
  std::cout << "Player is at row " << playerRow << ", column " << playerCol << "\n";

  // Try to move the player right 4 times, but never through a wall.
  int collected = 0;
  for (int step = 0; step < 4; step++) {
    int nextCol = playerCol + 1;
    if (map[playerRow][nextCol] == '#') break;  // wall: stop
    if (map[playerRow][nextCol] == '$') collected++;
    map[playerRow][playerCol] = '.';
    playerCol = nextCol;
    map[playerRow][playerCol] = 'P';
  }
  std::cout << "\nAfter walking right (collected " << collected << " coins):\n";
  printMap(map);
  return 0;
}

#include <iostream>
#include <memory>
#include <string>
#include <vector>

// An interface: it only says WHAT a device can do. "= 0" means "no body here, children must write it".
class Device {
public:
  virtual ~Device() = default;
  virtual std::string name() const = 0;
  virtual void turnOn() = 0;
  virtual void turnOff() = 0;
};
// You can't write "Device d;" because Device is abstract (it has = 0 functions).

class Lamp : public Device {
public:
  std::string name() const override { return "Lamp"; }
  void turnOn() override { std::cout << "The lamp glows warm yellow.\n"; }
  void turnOff() override { std::cout << "The lamp clicks off.\n"; }
};

class Fan : public Device {
public:
  std::string name() const override { return "Fan"; }
  void turnOn() override {
    speed_ = 3;
    std::cout << "The fan spins at speed " << speed_ << ". Whoosh!\n";
  }
  void turnOff() override {
    speed_ = 0;
    std::cout << "The fan slows down and stops.\n";
  }
private:
  int speed_ = 0;
};

class Robot : public Device {
public:
  std::string name() const override { return "Robot"; }
  void turnOn() override { std::cout << "BEEP BOOP. Robot online. Hello, human.\n"; }
  void turnOff() override { std::cout << "Robot powering down... goodnight.\n"; }
};

// This function works with ANY device, even ones invented later.
void runRoutine(Device &d) {
  std::cout << "[" << d.name() << "]\n";
  d.turnOn();
  d.turnOff();
}

int main() {
  std::vector<std::unique_ptr<Device>> room;
  room.push_back(std::make_unique<Lamp>());
  room.push_back(std::make_unique<Fan>());
  room.push_back(std::make_unique<Robot>());

  for (auto &device : room) runRoutine(*device);
  return 0;
}

#include <array>
#include <iostream>
#include <string>

int main() {
  // A plain C-style array: 7 numbers in a row. Positions go from 0 to 6.
  int temps[7] = {18, 21, 25, 19, 23, 27, 22};
  const std::string days[7] = {"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"};

  int total = 0;
  int hottest = 0;  // the POSITION of the hottest day
  int coldest = 0;
  for (int i = 0; i < 7; i++) {
    total += temps[i];
    if (temps[i] > temps[hottest]) hottest = i;
    if (temps[i] < temps[coldest]) coldest = i;
  }

  std::cout << "Day  Temp\n";
  for (int i = 0; i < 7; i++) {
    std::cout << days[i] << "  " << temps[i] << " C ";
    for (int b = 0; b < temps[i] / 2; b++) std::cout << '|';  // a little bar chart
    std::cout << "\n";
  }
  std::cout << "\nAverage: " << total / 7.0 << " C\n";
  std::cout << "Hottest: " << days[hottest] << " (" << temps[hottest] << " C)\n";
  std::cout << "Coldest: " << days[coldest] << " (" << temps[coldest] << " C)\n";

  // std::array is the modern version: it knows its own size and works with range-for.
  std::array<int, 5> lottery = {7, 13, 21, 34, 42};
  std::cout << "\nLottery numbers (" << lottery.size() << " of them):";
  for (int n : lottery) std::cout << " " << n;
  std::cout << "\n";

  // .at() checks the position for you, so a mistake gives an error instead of garbage.
  std::cout << "lottery.at(2) = " << lottery.at(2) << "\n";
  return 0;
}

