  auto hero = std::string("Nova");  // std::string
  std::cout << hero << " is on level " << level << " with gravity " << gravity << "\n\n";

  std::vector<std::string> party = {"knight", "archer", "healer"};

  // Read each item (a copy).
  for (auto member : party) std::cout << "Party member: " << member << "\n";

  // auto& lets us CHANGE the real items.
  for (auto &member : party) member = "super " + member;

  // const auto& is the best way to just look: no copy, no changes.
  for (const auto &member : party) std::cout << "Upgraded: " << member << "\n";

  // Range-for over a map. Structured bindings [name, score] split each pair into two names.
  std::map<std::string, int> scores = {{"Ava", 120}, {"Leo", 95}, {"Kai", 150}};
  std::cout << "\nScores (maps keep keys in order):\n";
  for (const auto &[name, score] : scores) {
    std::cout << "  " << name << ": " << score << "\n";
  }

  // Loop over a list written right in the loop.
  std::cout << "\nCountdown:";
  for (int n : {5, 4, 3, 2, 1}) std::cout << " " << n;
  std::cout << " Liftoff!\n";
  return 0;
}

#include <iomanip>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

class BankAccount {
public:
  explicit BankAccount(const std::string &owner) : owner_(owner) {}

  bool deposit(double amount) {
    if (amount <= 0) return false;  // the class protects itself from bad values
    balance_ += amount;
    history_.push_back("deposit  +" + money(amount));
    return true;
  }

  bool withdraw(double amount) {
    if (amount <= 0 || amount > balance_) return false;
    balance_ -= amount;
    history_.push_back("withdraw -" + money(amount));
    return true;
  }

  // A "getter": lets others READ the balance, but not change it.
  double balance() const { return balance_; }
  const std::string &owner() const { return owner_; }

  void printStatement() const {
    std::cout << "Statement for " << owner_ << ":\n";
    for (const auto &line : history_) std::cout << "  " << line << "\n";
    std::cout << "  Balance: " << money(balance_) << "\n";
  }

private:
  std::string owner_;
  double balance_ = 0.0;  // private: nobody outside can do account.balance_ = 1000000
  std::vector<std::string> history_;

  static std::string money(double amount) {
    std::ostringstream out;
    out << "$" << std::fixed << std::setprecision(2) << amount;
    return out.str();
  }
};

int main() {
  BankAccount account("Storm");
  std::cout << "Commands: d AMOUNT (deposit), w AMOUNT (withdraw), b (balance), q (quit)\n";
  char cmd;
  while (std::cout << "> " && std::cin >> cmd && cmd != 'q') {
    if (cmd == 'b') {
      std::cout << "Balance: $" << std::fixed << std::setprecision(2) << account.balance() << "\n";
      continue;
    }
    if (cmd != 'd' && cmd != 'w') {
      std::cout << "Unknown command. Use d, w, b or q.\n";
      continue;
    }
    double amount;
    if (!(std::cin >> amount)) {
      std::cin.clear();
      std::cin.ignore(1000, '\n');
      std::cout << "Please give an amount, like: d 20\n";
      continue;
    }
    bool ok = (cmd == 'd') ? account.deposit(amount) : account.withdraw(amount);
    std::cout << (ok ? "Done.\n" : "Not allowed.\n");
  }
  std::cout << "\n";
  account.printStatement();
  return 0;
}

#include <bitset>
#include <cstdint>
#include <iostream>

// Each power-up gets its own bit. 1 << n means "a 1 moved n places left".
const std::uint8_t SPEED = 1 << 0;   // 00000001
const std::uint8_t SHIELD = 1 << 1;  // 00000010
const std::uint8_t JUMP = 1 << 2;    // 00000100
const std::uint8_t MAGNET = 1 << 3;  // 00001000

void show(const char *label, std::uint8_t flags) {
  std::cout << label << std::bitset<8>(flags) << "  ";
  if (flags & SPEED) std::cout << "[speed] ";
  if (flags & SHIELD) std::cout << "[shield] ";
  if (flags & JUMP) std::cout << "[jump] ";
  if (flags & MAGNET) std::cout << "[magnet] ";
  std::cout << "\n";
}

int main() {
  std::uint8_t powers = 0;
  show("start:          ", powers);

  powers |= SPEED;   // OR turns a bit ON
  powers |= MAGNET;
  show("got speed+mag:  ", powers);

  powers ^= SHIELD;  // XOR flips a bit
  show("flip shield:    ", powers);

  powers &= static_cast<std::uint8_t>(~SPEED);  // AND with NOT turns a bit OFF
  show("speed ran out:  ", powers);

  bool hasMagnet = (powers & MAGNET) != 0;  // AND checks a bit
  std::cout << "Has magnet? " << (hasMagnet ? "yes" : "no") << "\n\n";

  // Shifting left doubles a number, shifting right halves it.
  int n = 5;
  std::cout << n << " << 1 = " << (n << 1) << ",  " << n << " << 3 = " << (n << 3) << "\n";
  std::cout << "40 >> 2 = " << (40 >> 2) << "\n";

  // Count how many bits are on.
  int onBits = 0;
  for (int bit = 0; bit < 8; bit++) {
    if (powers & (1 << bit)) onBits++;
  }
  std::cout << "Power-ups active: " << onBits << "\n";
  return 0;
}

#include <functional>
#include <iostream>
#include <map>
#include <string>
#include <vector>

// An event bus: you "subscribe" functions to event names, then "emit" an event to call them all.
class EventBus {
public:
  using Handler = std::function<void(int)>;  // any function that takes an int and returns nothing

  void subscribe(const std::string &event, Handler handler) {
    handlers_[event].push_back(handler);
  }

  void emit(const std::string &event, int value) {
    std::cout << "> " << event << "(" << value << ")\n";
    for (Handler &h : handlers_[event]) h(value);
  }

private:
  std::map<std::string, std::vector<Handler>> handlers_;
};

// A normal function can be a handler too.
void playSound(int value) {
  std::cout << "  *ding* (sound for " << value << ")\n";
}

int main() {
  EventBus bus;
  int score = 0;
  int coinsCollected = 0;

  bus.subscribe("coin", playSound);
  bus.subscribe("coin", [&score](int value) { score += value; std::cout << "  score is now " << score << "\n"; });
  bus.subscribe("coin", [&coinsCollected](int) { coinsCollected++; });
  bus.subscribe("damage", [](int amount) { std::cout << "  ouch! lost " << amount << " HP\n"; });

  bus.emit("coin", 10);
  bus.emit("damage", 3);
  bus.emit("coin", 50);
  bus.emit("jump", 1);  // nobody listens to this one, and that's fine

  std::cout << "Coins: " << coinsCollected << ", final score: " << score << "\n";

  // std::function can also hold a choice of math operations.
  std::map<char, std::function<double(double, double)>> ops = {
    {'+', [](double a, double b) { return a + b; }},
    {'*', [](double a, double b) { return a * b; }},
  };
  std::cout << "3 + 4 = " << ops['+'](3, 4) << ", 3 * 4 = " << ops['*'](3, 4) << "\n";
  return 0;
}

