int main() {
  std::cout << "Type a made-up password to test (not a real one!): ";
  std::string pw;
  if (!std::getline(std::cin, pw)) pw = "";

  int upper = 0, lower = 0, digits = 0, symbols = 0, spaces = 0;
  for (char ch : pw) {
    // cctype functions want an unsigned char, so we convert first.
    unsigned char c = static_cast<unsigned char>(ch);
    if (std::isupper(c)) upper++;
    else if (std::islower(c)) lower++;
    else if (std::isdigit(c)) digits++;
    else if (std::isspace(c)) spaces++;
    else if (std::ispunct(c)) symbols++;
  }

  std::cout << "Length: " << pw.size() << "\n"
            << "Uppercase: " << upper << ", lowercase: " << lower
            << ", digits: " << digits << ", symbols: " << symbols << "\n";

  int points = 0;
  if (pw.size() >= 8) points++;
  if (pw.size() >= 12) points++;
  if (upper > 0) points++;
  if (lower > 0) points++;
  if (digits > 0) points++;
  if (symbols > 0) points++;

  std::cout << "Strength: ";
  for (int i = 0; i < 6; i++) std::cout << (i < points ? '#' : '-');
  if (points <= 2) std::cout << "  weak\n";
  else if (points <= 4) std::cout << "  ok\n";
  else std::cout << "  strong!\n";

  if (spaces > 0) std::cout << "Tip: some websites don't allow spaces.\n";
  if (digits == 0) std::cout << "Tip: add a number.\n";
  if (symbols == 0) std::cout << "Tip: add a symbol like ! or #.\n";
  return 0;
}

#include <array>
#include <iostream>
#include <string>

// T is the item type, CAPACITY is how many slots. Both are chosen when you make a Bag.
template <typename T, int CAPACITY>
class Bag {
public:
  bool add(const T &item) {
    if (count_ >= CAPACITY) {
      std::cout << "  Bag is full! Can't add " << item << "\n";
      return false;
    }
    slots_[count_++] = item;
    return true;
  }

  bool removeLast() {
    if (count_ == 0) return false;
    count_--;
    return true;
  }

  bool contains(const T &item) const {
    for (int i = 0; i < count_; i++) {
      if (slots_[i] == item) return true;
    }
    return false;
  }

  void print() const {
    std::cout << "  Bag (" << count_ << "/" << CAPACITY << "):";
    for (int i = 0; i < count_; i++) std::cout << " [" << slots_[i] << "]";
    std::cout << "\n";
  }

private:
  std::array<T, CAPACITY> slots_{};
  int count_ = 0;
};

int main() {
  std::cout << "Adventurer's bag (holds 3 strings):\n";
  Bag<std::string, 3> backpack;
  backpack.add("sword");
  backpack.add("map");
  backpack.add("apple");
  backpack.add("dragon egg");  // too many!
  backpack.print();
  std::cout << "  Has a map? " << (backpack.contains("map") ? "yes" : "no") << "\n";
  backpack.removeLast();
  backpack.print();

  std::cout << "\nDice bag (holds 5 ints):\n";
  Bag<int, 5> dice;
  for (int i = 1; i <= 6; i++) dice.add(i * 2);
  dice.print();
  return 0;
}

#include <iostream>
#include <string>

// A class is a blueprint. Each Pet we make from it is an "object".
class Pet {
public:
  // The constructor runs when a new Pet is made.
  Pet(const std::string &name, const std::string &species)
      : name_(name), species_(species) {}

  void feed() {
    hunger_ = clamp(hunger_ - 30);
    std::cout << name_ << " munches some food. Yum!\n";
  }

  void play() {
    happiness_ = clamp(happiness_ + 20);
    hunger_ = clamp(hunger_ + 10);  // playing makes you hungry
    std::cout << name_ << " plays fetch!\n";
  }

  void showStatus() const {
    std::cout << name_ << " the " << species_ << " - hunger: " << hunger_
              << "/100, happiness: " << happiness_ << "/100";
    if (hunger_ > 70) std::cout << " (very hungry!)";
    std::cout << "\n";
  }

  const std::string &getName() const { return name_; }

private:
  // Private data: only the Pet's own functions can change it.
  std::string name_;
  std::string species_;
  int hunger_ = 50;
  int happiness_ = 50;

  // Keep a value between 0 and 100.
  static int clamp(int value) {
    if (value < 0) return 0;
    if (value > 100) return 100;
    return value;
  }
};

int main() {
  // Two different objects made from the same class.
  Pet dog("Biscuit", "dog");
  Pet cat("Pixel", "cat");

  dog.showStatus();
  cat.showStatus();
  std::cout << "\n";

  dog.play();
  dog.play();
  cat.feed();
  std::cout << "\n";

  dog.showStatus();
  cat.showStatus();

  std::cout << "\nRemember to feed " << dog.getName() << " soon!\n";
  return 0;
}

#include <cctype>
