int main(int argc, char *argv[]) {
  // argc = how many words, argv = the words. argv[0] is the program's own name.
  std::cout << "You gave me " << argc - 1 << " argument(s).\n";
  for (int i = 0; i < argc; i++) std::cout << "  argv[" << i << "] = " << argv[i] << "\n";

  std::string name = "friend";
  bool shout = false;
  int times = 1;

  for (int i = 1; i < argc; i++) {
    std::string arg = argv[i];
    if (arg == "--shout") {
      shout = true;
    } else if (arg == "--times" && i + 1 < argc) {
      try {
        times = std::stoi(argv[++i]);  // use the NEXT word as the number
      } catch (const std::exception &) {
        std::cout << "--times needs a number\n";
      }
      if (times < 1 || times > 10) times = 1;
    } else if (arg == "--help") {
      std::cout << "Usage: greet NAME [--shout] [--times N]\n";
      return 0;
    } else {
      name = arg;
    }
  }

  std::string message = "Hello, " + name + "!";
  if (shout) {
    for (char &c : message) c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
  }
  for (int i = 0; i < times; i++) std::cout << message << "\n";
  return 0;
}

#include <array>
#include <iostream>

// constexpr: the compiler can work this out BEFORE the program even runs.
constexpr int factorial(int n) {
  return n <= 1 ? 1 : n * factorial(n - 1);
}

constexpr int SCREEN_WIDTH = 128;
constexpr int SCREEN_HEIGHT = 64;
constexpr int PIXELS = SCREEN_WIDTH * SCREEN_HEIGHT;  // worked out at compile time

// static_assert checks something at compile time. If it's false, the code won't compile.
static_assert(factorial(5) == 120, "factorial is broken!");
static_assert(PIXELS == 8192, "screen size changed!");

class Thermometer {
public:
  explicit Thermometer(double c) : celsius_(c) {}
  // const after the () promises: this function will not change the object.
  double fahrenheit() const { return celsius_ * 9.0 / 5.0 + 32.0; }
  void heat(double amount) { celsius_ += amount; }  // not const: it changes things
private:
  double celsius_;
};

int main() {
  const int maxLives = 3;  // const: set once, can't change
  // maxLives = 4;  // <- this line would be a compile error. Try it!

  // A constexpr value can be used as an array size.
  std::array<int, factorial(4)> slots{};  // 24 slots
  std::cout << "Lives: " << maxLives << "\n";
  std::cout << "Slots in the array: " << slots.size() << "\n";
  std::cout << "Pixels on the OLED: " << PIXELS << "\n";
  std::cout << "10! = " << factorial(10) << "\n";

  const Thermometer outside(20.0);
  std::cout << "Outside: " << outside.fahrenheit() << " F\n";  // ok: fahrenheit() is const
  // outside.heat(5);  // <- not allowed: outside is const and heat() changes it

  Thermometer oven(150.0);
  oven.heat(30);
  std::cout << "Oven: " << oven.fahrenheit() << " F\n";
  return 0;
}

#include <iostream>
#include <string>

class Torch {
public:
  // Default constructor: runs when you make a Torch with no info.
  Torch() : Torch("plain torch", 10) {}

  // Constructor with values. The part after : is the "initializer list".
  Torch(const std::string &name, int fuel) : name_(name), fuel_(fuel) {
    std::cout << "  [+] " << name_ << " is lit (" << fuel_ << " fuel)\n";
  }

  // Destructor: runs automatically when the object goes away.
  ~Torch() {
    std::cout << "  [-] " << name_ << " goes out\n";
  }

  void burn(int amount) {
    fuel_ = fuel_ > amount ? fuel_ - amount : 0;
    std::cout << "  " << name_ << " burns, fuel left: " << fuel_ << "\n";
  }

private:
  std::string name_;
  int fuel_;
};

int main() {
  std::cout << "Entering the cave...\n";
  Torch main("main torch", 50);

  {  // curly braces make a new "scope"
    std::cout << "Entering a side tunnel...\n";
    Torch small("tiny torch", 5);
    small.burn(3);
    std::cout << "Leaving the side tunnel...\n";
  }  // small is destroyed right here, automatically!

  Torch spare;  // uses the default constructor
  main.burn(20);

  std::cout << "Leaving the cave...\n";
  return 0;
  // main and spare are destroyed now, in the opposite order they were made.
}

#include <iostream>
#include <string>
#include <utility>
#include <vector>

class Level {
public:
  explicit Level(const std::string &name) : name_(name), tiles_(100000, 1) {
    std::cout << "  made " << name_ << "\n";
  }
  // Copy constructor: makes a full duplicate (slow for big data).
  Level(const Level &other) : name_(other.name_ + " copy"), tiles_(other.tiles_) {
    std::cout << "  COPIED " << other.name_ << " (" << tiles_.size() << " tiles duplicated)\n";
  }
  // Move constructor: steals the insides (fast!). The old object is left empty.
  Level(Level &&other) noexcept : name_(std::move(other.name_)), tiles_(std::move(other.tiles_)) {
    std::cout << "  MOVED " << name_ << " (no tiles duplicated)\n";
  }
  Level &operator=(const Level &) = default;
  Level &operator=(Level &&) = default;

  std::size_t tileCount() const { return tiles_.size(); }
  const std::string &name() const { return name_; }

private:
  std::string name_;
  std::vector<int> tiles_;
};

int main() {
  std::cout << "Making a level:\n";
  Level forest("forest");

  std::cout << "\nCopying it:\n";
  Level forestCopy = forest;  // both now have 100000 tiles

  std::cout << "\nMoving it:\n";
  Level moved = std::move(forest);  // std::move says "I'm done with forest, take its stuff"
  std::cout << "  forest now has " << forest.tileCount() << " tiles (it was emptied)\n";
  std::cout << "  moved has " << moved.tileCount() << " tiles\n";

  std::cout << "\nPutting levels in a vector:\n";
  std::vector<Level> world;
  world.reserve(2);  // room for 2 so the vector doesn't have to shuffle things around
  world.push_back(Level("cave"));      // a temporary is moved in automatically
  world.push_back(std::move(moved));   // moved in on purpose
  for (const Level &l : world) std::cout << "  world has: " << l.name() << "\n";
  return 0;
}

#include <chrono>
#include <iostream>
#include <sstream>
#include <string>
#include <thread>

int main() {
  int seconds = 0;
  std::string line;

  // Keep asking until we get a number from 1 to 3600.
  while (true) {
    std::cout << "Count down from how many seconds? (1-3600): ";
    if (!std::getline(std::cin, line)) return 0;  // input closed
    std::istringstream in(line);
    char extra;
    if (in >> seconds && !(in >> extra) && seconds >= 1 && seconds <= 3600) break;
    std::cout << "Please type a whole number from 1 to 3600.\n";
  }

  // Remember when we started.
  auto start = std::chrono::steady_clock::now();

  for (int left = seconds; left > 0; left--) {
    int minutes = left / 60;
    int secs = left % 60;
    // \r jumps back to the start of the line so the number updates in place.
    std::cout << "\r" << minutes << ":" << (secs < 10 ? "0" : "") << secs << "   " << std::flush;
    std::this_thread::sleep_for(std::chrono::seconds(1));
  }

  auto end = std::chrono::steady_clock::now();
  auto tookMs = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();

  std::cout << "\r0:00   \nTime's up! Beep beep beep!\n";
  std::cout << "That really took " << tookMs / 1000.0 << " seconds.\n";
  return 0;
}

