#include <iostream>
#include <string>

// An enum class is a list of named choices. Much clearer than using 0, 1, 2, 3!
enum class Direction { North, East, South, West };
enum class Weather { Sunny, Rainy, Snowy, Stormy };

std::string toString(Direction d) {
  switch (d) {
    case Direction::North: return "North";
    case Direction::East: return "East";
    case Direction::South: return "South";
    case Direction::West: return "West";
  }
  return "?";
}

// Turning right: North -> East -> South -> West -> North.
Direction turnRight(Direction d) {
  int next = (static_cast<int>(d) + 1) % 4;
  return static_cast<Direction>(next);
}

std::string advice(Weather w) {
  switch (w) {
    case Weather::Sunny: return "Wear sunscreen.";
    case Weather::Rainy: return "Bring an umbrella.";
    case Weather::Snowy: return "Build a snowman!";
    case Weather::Stormy: return "Stay inside and code.";
  }
  return "";
}

int main() {
  Direction facing = Direction::North;
  for (int i = 0; i < 5; i++) {
    std::cout << "Facing " << toString(facing) << "\n";
    facing = turnRight(facing);
  }

  std::cout << "\n";
  Weather days[] = {Weather::Sunny, Weather::Rainy, Weather::Stormy, Weather::Snowy};
  for (Weather w : days) std::cout << advice(w) << "\n";

  // Enum class values don't mix with ints by accident. This would NOT compile:
  //   int x = Direction::East;
  // You must say what you mean:
  int x = static_cast<int>(Direction::East);
  std::cout << "\nDirection::East is number " << x << "\n";
  return 0;
}

#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

// Throws an error if you try to withdraw too much.
double withdraw(double balance, double amount) {
  if (amount <= 0) throw std::invalid_argument("amount must be more than zero");
  if (amount > balance) throw std::runtime_error("not enough money");
  return balance - amount;
}

int main() {
  double balance = 50.0;
  std::vector<double> tries = {20.0, -5.0, 100.0, 10.0};

  for (double amount : tries) {
    try {
      balance = withdraw(balance, amount);
      std::cout << "Took out $" << amount << ", left: $" << balance << "\n";
    } catch (const std::invalid_argument &e) {
      // Catches only invalid_argument errors.
      std::cout << "Bad request: " << e.what() << "\n";
    } catch (const std::runtime_error &e) {
      std::cout << "Can't take $" << amount << ": " << e.what() << "\n";
    }
  }

  // Library functions throw too. .at() throws out_of_range if the position is wrong.
  std::vector<int> levels = {1, 2, 3};
  try {
    std::cout << "Level 10 is " << levels.at(10) << "\n";
  } catch (const std::out_of_range &) {
    std::cout << "There is no level 10!\n";
  }

  // stoi throws if the text isn't a number.
  try {
    int n = std::stoi("banana");
    std::cout << n << "\n";
  } catch (const std::exception &e) {  // std::exception catches all standard errors
    std::cout << "\"banana\" is not a number (" << e.what() << ")\n";
  }

  std::cout << "The program kept running. Final balance: $" << balance << "\n";
  return 0;
}

