// "template <typename T>" means: T can be any type. The compiler makes a copy for each type you use.
template <typename T>
T biggest(const T &a, const T &b) {
  return (a > b) ? a : b;
}

template <typename T>
void printList(const std::vector<T> &items) {
  std::cout << "[ ";
  for (const T &item : items) std::cout << item << " ";
  std::cout << "]\n";
}

template <typename T>
T sum(const std::vector<T> &items) {
  T total{};  // {} makes a "zero" of any type: 0 for int, "" for string
  for (const T &item : items) total += item;
  return total;
}

// Two different template types.
template <typename A, typename B>
void showPair(const A &first, const B &second) {
  std::cout << "(" << first << ", " << second << ")\n";
}

int main() {
  std::cout << "biggest(3, 9) = " << biggest(3, 9) << "\n";
  std::cout << "biggest(2.5, 1.5) = " << biggest(2.5, 1.5) << "\n";
  std::cout << "biggest(\"apple\", \"pear\") = " << biggest(std::string("apple"), std::string("pear")) << "\n\n";

  std::vector<int> scores = {10, 20, 30};
  std::vector<double> prices = {1.25, 3.5, 0.75};
  std::vector<std::string> words = {"tem", "pla", "tes"};

  printList(scores);
  printList(prices);
  printList(words);

  std::cout << "sum of scores = " << sum(scores) << "\n";
  std::cout << "sum of prices = " << sum(prices) << "\n";
  std::cout << "sum of words = " << sum(words) << "  (strings add by joining!)\n\n";

  showPair("level", 7);
  showPair(3.14, 'x');
  return 0;
}

#include <iostream>

char letterGrade(int score) {
  if (score >= 90) return 'A';
  else if (score >= 80) return 'B';
  else if (score >= 70) return 'C';
  else if (score >= 60) return 'D';
  else return 'F';
}

int main() {
  std::cout << "Type test scores (0 to 100). Type -1 to stop.\n";
  int score;
  int count = 0;
  int total = 0;

  while (std::cin >> score && score != -1) {
    // || means OR: if either part is true, the whole thing is true.
    if (score < 0 || score > 100) {
      std::cout << "  That's not a real score.\n";
      continue;
    }
    char grade = letterGrade(score);
    std::cout << "  " << score << " is a " << grade;

    // && means AND: both parts must be true.
    if (score >= 95 && score <= 100) std::cout << " (amazing!)";
    else if (grade == 'F') std::cout << " (time to study)";
    std::cout << "\n";

    count++;
    total += score;
  }

  if (count > 0) {
    double average = static_cast<double>(total) / count;
    std::cout << "Average: " << average << " which is a " << letterGrade(static_cast<int>(average)) << "\n";
    // The ternary operator: condition ? valueIfTrue : valueIfFalse
    std::cout << (average >= 60 ? "Passing overall." : "Not passing yet.") << "\n";
  } else {
    std::cout << "No scores entered.\n";
  }
  return 0;
}

