// A struct groups related data together.
struct Score {
  std::string name;
  int points;
};

void printTop(const std::vector<Score> &scores, std::size_t howMany) {
  std::cout << "\n=== HIGH SCORES ===\n";
  for (std::size_t i = 0; i < scores.size() && i < howMany; i++) {
    std::cout << (i + 1) << ". " << scores[i].name << " - " << scores[i].points << "\n";
  }
}

int main() {
  std::vector<Score> scores = {
      {"Ava", 1200}, {"Leo", 950}, {"Mia", 1500}, {"Sam", 700}, {"Zoe", 1100}};

  // Ask for the player's name.
  std::cout << "Your name: ";
  std::string name;
  if (!std::getline(std::cin, name)) return 0;
  if (name.empty()) name = "Player";

  // Ask for a score until it's a real number.
  int points = 0;
  while (true) {
    std::cout << "Your score: ";
    std::string line;
    if (!std::getline(std::cin, line)) return 0;
    std::istringstream in(line);
    char extra;
    if (in >> points && !(in >> extra) && points >= 0) break;
    std::cout << "Please type a whole number (0 or more).\n";
  }
  scores.push_back({name, points});

  // Sort biggest first. The little function says how to compare two scores.
  std::sort(scores.begin(), scores.end(), [](const Score &a, const Score &b) {
    return a.points > b.points;
  });

  printTop(scores, 5);

  // Find where the player ended up.
  for (std::size_t i = 0; i < scores.size(); i++) {
    if (scores[i].name == name && scores[i].points == points) {
      std::cout << "\nYou placed #" << (i + 1) << "!";
      if (i < 5) std::cout << " You made the top 5!";
      std::cout << "\n";
      break;
    }
  }
  return 0;
}

#include <iostream>
#include <string>

// The base class has what EVERY character has.
class Character {
public:
  Character(const std::string &name, int health) : name_(name), health_(health) {}

  void takeDamage(int amount) {
    health_ -= amount;
    if (health_ < 0) health_ = 0;
    std::cout << name_ << " takes " << amount << " damage (" << health_ << " HP left)\n";
  }

  bool isAlive() const { return health_ > 0; }
  const std::string &name() const { return name_; }

protected:
  // protected: hidden from outside code, but child classes can use it.
  std::string name_;
  int health_;
};

// A Warrior IS a Character, plus armor and a sword.
class Warrior : public Character {
public:
  Warrior(const std::string &name) : Character(name, 120) {}

  void swingSword(Character &target) {
    std::cout << name_ << " swings a sword!\n";
    target.takeDamage(25);
  }
};

// A Wizard IS a Character, plus mana for spells.
class Wizard : public Character {
public:
  Wizard(const std::string &name) : Character(name, 80) {}

  void castFireball(Character &target) {
    if (mana_ < 30) {
      std::cout << name_ << " is out of mana!\n";
      return;
    }
    mana_ -= 30;
    std::cout << name_ << " casts FIREBALL! (mana " << mana_ << ")\n";
    target.takeDamage(40);
  }

private:
  int mana_ = 100;
};

int main() {
  Warrior hero("Brick");
  Wizard rival("Zappo");

  int round = 1;
  while (hero.isAlive() && rival.isAlive()) {
    std::cout << "\n-- Round " << round++ << " --\n";
    hero.swingSword(rival);
    if (rival.isAlive()) rival.castFireball(hero);
  }
  std::cout << "\n" << (hero.isAlive() ? hero.name() : rival.name()) << " wins!\n";
  return 0;
}

#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

int main() {
  // A lambda is a function without a name: [capture](inputs) { body }
  auto square = [](int n) { return n * n; };
  std::cout << "square(7) = " << square(7) << "\n";

  std::vector<int> nums = {5, 12, 3, 18, 7, 9, 21, 4};

  // Pass a lambda to count_if: how many are even?
  int evens = static_cast<int>(std::count_if(nums.begin(), nums.end(), [](int n) { return n % 2 == 0; }));
  std::cout << "Even numbers: " << evens << "\n";

  // Capture by value [limit]: the lambda gets its own copy of limit.
  int limit = 10;
  auto isBig = [limit](int n) { return n > limit; };
  std::cout << "Numbers bigger than " << limit << ":";
  for (int n : nums) {
    if (isBig(n)) std::cout << " " << n;
  }
  std::cout << "\n";

  // Capture by reference [&total]: the lambda can change total.
  int total = 0;
  std::for_each(nums.begin(), nums.end(), [&total](int n) { total += n; });
  std::cout << "Total: " << total << "\n";

  // Sort biggest first with a custom rule.
  std::sort(nums.begin(), nums.end(), [](int a, int b) { return a > b; });
  std::cout << "Biggest first:";
  for (int n : nums) std::cout << " " << n;
  std::cout << "\n";

  // Sort words by length.
  std::vector<std::string> words = {"robot", "AI", "arduino", "cpp", "lambda"};
  std::sort(words.begin(), words.end(),
            [](const std::string &a, const std::string &b) { return a.size() < b.size(); });
  std::cout << "Shortest word first:";
  for (const auto &w : words) std::cout << " " << w;
  std::cout << "\n";

  // A counter that remembers its value between calls (mutable lets it change its own copy).
  auto nextId = [id = 100]() mutable { return id++; };
  std::cout << "IDs: " << nextId() << ", " << nextId() << ", " << nextId() << "\n";
  return 0;
}

#include <iostream>

int main() {
  // The classic first program.
  std::cout << "Hello, world!\n\n";

  // A for loop: start at 1, keep going while i <= 5, add 1 each time.
  std::cout << "Counting up: ";
  for (int i = 1; i <= 5; i++) {
    std::cout << i << " ";
  }
  std::cout << "\n";

  // A while loop: keep going while the condition is true.
  std::cout << "Doubling: ";
  int number = 1;
  while (number < 200) {
    std::cout << number << " ";
    number *= 2;
  }
  std::cout << "\n\n";

  // If / else if / else with FizzBuzz:
  // multiples of 3 say Fizz, of 5 say Buzz, of both say FizzBuzz.
  for (int i = 1; i <= 20; i++) {
    if (i % 15 == 0) {
      std::cout << "FizzBuzz\n";
    } else if (i % 3 == 0) {
      std::cout << "Fizz\n";
    } else if (i % 5 == 0) {
      std::cout << "Buzz\n";
    } else {
      std::cout << i << "\n";
    }
  }

  // A loop inside a loop makes a times table.
  std::cout << "\nTimes table:\n";
  for (int row = 1; row <= 5; row++) {
    for (int col = 1; col <= 5; col++) {
      int value = row * col;
      if (value < 10) std::cout << " ";  // line up the columns
      std::cout << value << " ";
    }
    std::cout << "\n";
  }
  return 0;
}

