// A pair holds exactly two values.
std::pair<int, int> minAndMax(const std::vector<int> &nums) {
  int lo = nums[0], hi = nums[0];
  for (int n : nums) {
    if (n < lo) lo = n;
    if (n > hi) hi = n;
  }
  return {lo, hi};
}

// A tuple can hold any number of values of different types.
std::tuple<std::string, int, double> bestStudent() {
  return {"Mia", 7, 98.5};
}

int main() {
  std::vector<int> temps = {12, -3, 25, 8, 31, 0};
  std::pair<int, int> range = minAndMax(temps);
  std::cout << "Coldest: " << range.first << ", hottest: " << range.second << "\n";

  // C++17 structured bindings: name both parts in one go.
  auto [coldest, hottest] = minAndMax(temps);
  std::cout << "Range: " << hottest - coldest << " degrees\n\n";

  auto [name, grade, score] = bestStudent();
  std::cout << "Best student: " << name << " in grade " << grade << " with " << score << "%\n";

  // std::get<number> also works on tuples.
  auto student = bestStudent();
  std::cout << "Name via std::get<0>: " << std::get<0>(student) << "\n\n";

  // A vector of pairs is a handy mini table.
  std::vector<std::pair<std::string, int>> inventory = {{"arrows", 30}, {"potions", 2}, {"keys", 1}};
  for (const auto &[item, count] : inventory) std::cout << item << " x" << count << "\n";
  return 0;
}

#include <iostream>
#include <string>
#include <vector>

// Gets a COPY. Changing it does nothing to the original.
void addBonusCopy(int score) {
  score += 100;
  std::cout << "  inside addBonusCopy: " << score << "\n";
}

// Gets the REAL variable (a reference). Changes stick!
void addBonusRef(int &score) {
  score += 100;
  std::cout << "  inside addBonusRef: " << score << "\n";
}

// The classic: swap two variables.
void swapValues(int &a, int &b) {
  int temp = a;
  a = b;
  b = temp;
}

// const & = "look but don't touch". Fast (no copy) and safe (can't change it).
int totalLength(const std::vector<std::string> &words) {
  int total = 0;
  for (const std::string &w : words) total += static_cast<int>(w.size());
  return total;
}

int main() {
  int score = 50;
  std::cout << "Start: " << score << "\n";

  addBonusCopy(score);
  std::cout << "After addBonusCopy: " << score << "  (unchanged!)\n";

  addBonusRef(score);
  std::cout << "After addBonusRef: " << score << "  (changed!)\n\n";

  int x = 1, y = 2;
  swapValues(x, y);
  std::cout << "After swap: x = " << x << ", y = " << y << "\n";

  std::vector<std::string> words = {"sword", "shield", "potion"};
  std::cout << "Total letters: " << totalLength(words) << "\n";
  return 0;
}

