// Keep only letters and digits, all lowercase.
std::string cleanUp(const std::string &text) {
  std::string out;
  for (char ch : text) {
    unsigned char c = static_cast<unsigned char>(ch);
    if (std::isalnum(c)) out += static_cast<char>(std::tolower(c));
  }
  return out;
}

// Two "fingers": one at the start, one at the end, walking toward the middle.
bool isPalindrome(const std::string &s) {
  if (s.empty()) return false;
  std::size_t left = 0, right = s.size() - 1;
  while (left < right) {
    if (s[left] != s[right]) return false;
    left++;
    right--;
  }
  return true;
}

int main() {
  std::cout << "Type words or sentences (empty line or Ctrl+D to quit).\n";
  std::cout << "Try: racecar, Never odd or even, A man a plan a canal Panama\n\n";
  std::string line;
  while (std::cout << "> " && std::getline(std::cin, line) && !line.empty()) {
    std::string reversed(line.rbegin(), line.rend());  // build a string from back to front
    std::cout << "Backwards: " << reversed << "\n";

    std::string clean = cleanUp(line);
    std::cout << (isPalindrome(clean) ? "Yes! It's a palindrome.\n" : "Not a palindrome.\n");

    // Another way to reverse: std::reverse changes a string in place.
    std::string copy = clean;
    std::reverse(copy.begin(), copy.end());
    std::cout << "(cleaned: " << clean << " / " << copy << ")\n\n";
  }
  std::cout << "\nBye!\n";
  return 0;
}

#include <cmath>
#include <iostream>
#include <sstream>
#include <string>

int main() {
  std::cout << "Calculator! Type things like 7 + 5 or 9 / 2. Use + - * / % ^\n"
            << "Type q to quit.\n";

  std::string line;
  while (true) {
    std::cout << "\n> ";
    if (!std::getline(std::cin, line)) break;  // input closed
    if (line == "q" || line == "quit") break;

    // Split the line into: number, operator, number.
    std::istringstream in(line);
    double a = 0, b = 0;
    char op = 0, extra = 0;
    if (!(in >> a >> op >> b) || (in >> extra)) {
      std::cout << "I didn't get that. Try: 3 + 4\n";
      continue;
    }

    double answer = 0;
    bool ok = true;
    switch (op) {
      case '+': answer = a + b; break;
      case '-': answer = a - b; break;
      case '*': case 'x': answer = a * b; break;
      case '/':
        if (b == 0) { std::cout << "You can't divide by zero!\n"; ok = false; }
        else answer = a / b;
        break;
      case '%':
        if (b == 0) { std::cout << "You can't divide by zero!\n"; ok = false; }
        else answer = std::fmod(a, b);
        break;
      case '^': answer = std::pow(a, b); break;
      default:
        std::cout << "I don't know the '" << op << "' sign. Use + - * / % ^\n";
        ok = false;
    }

    if (ok) std::cout << "= " << answer << "\n";
  }

  std::cout << "Bye!\n";
  return 0;
}

#include <iostream>
#include <memory>
#include <string>
#include <vector>

class Spaceship {
public:
  explicit Spaceship(const std::string &name) : name_(name) {
    std::cout << "  Spaceship " << name_ << " built\n";
  }
  ~Spaceship() { std::cout << "  Spaceship " << name_ << " scrapped\n"; }
  void fly() const { std::cout << "  " << name_ << " zooms through space!\n"; }
private:
  std::string name_;
};

int main() {
  std::cout << "1. unique_ptr: only ONE owner at a time\n";
  {
    std::unique_ptr<Spaceship> ship = std::make_unique<Spaceship>("Falcon");
    ship->fly();
    // You can't copy a unique_ptr, but you can MOVE it to a new owner.
    std::unique_ptr<Spaceship> newOwner = std::move(ship);
    std::cout << "  old pointer is now " << (ship ? "full" : "empty") << "\n";
    newOwner->fly();
  }  // newOwner goes away here, so the ship is deleted automatically.

  std::cout << "\n2. shared_ptr: MANY owners, deleted when the last one is gone\n";
  std::shared_ptr<Spaceship> mothership = std::make_shared<Spaceship>("Mothership");
  std::cout << "  owners: " << mothership.use_count() << "\n";
  {
    std::vector<std::shared_ptr<Spaceship>> fleet;
    fleet.push_back(mothership);  // another owner
    fleet.push_back(mothership);  // and another
    std::cout << "  owners while in the fleet: " << mothership.use_count() << "\n";
  }
  std::cout << "  owners after the fleet is gone: " << mothership.use_count() << "\n";
  mothership.reset();  // let go of the last owner
  std::cout << "  (no delete needed anywhere!)\n";

  std::cout << "\n3. A list of unique_ptrs\n";
  std::vector<std::unique_ptr<Spaceship>> hangar;
  hangar.push_back(std::make_unique<Spaceship>("Scout"));
  hangar.push_back(std::make_unique<Spaceship>("Cargo"));
  for (const auto &s : hangar) s->fly();
  std::cout << "End of main:\n";
  return 0;
}

#include <iostream>
