// Split text at every comma.
std::vector<std::string> split(const std::string &text, char separator) {
  std::vector<std::string> parts;
  std::istringstream in(text);
  std::string piece;
  while (std::getline(in, piece, separator)) parts.push_back(piece);
  return parts;
}

int main() {
  // 1. Words: >> skips spaces, so each read gets one word.
  std::istringstream sentence("the quick brown fox jumps");
  std::string word;
  int count = 0;
  while (sentence >> word) {
    std::cout << "word " << ++count << ": " << word << "\n";
  }

  // 2. Numbers mixed in text.
  std::istringstream data("10 20 30 40");
  int n, sum = 0;
  while (data >> n) sum += n;
  std::cout << "\nSum of \"10 20 30 40\" = " << sum << "\n";

  // 3. Comma separated values.
  std::vector<std::string> fields = split("Storm,12,robots,C++", ',');
  std::cout << "\nFields:\n";
  for (const auto &f : fields) std::cout << "  [" << f << "]\n";

  // 4. Read a command like "move 3 4".
  std::istringstream command("move 3 4");
  std::string action;
  int x = 0, y = 0;
  command >> action >> x >> y;
  std::cout << "\nAction: " << action << " to (" << x << ", " << y << ")\n";

  // 5. ostringstream builds a string the same way cout prints.
  std::ostringstream out;
  out << "Player at (" << x << "," << y << ") with " << sum << " points";
  std::string message = out.str();
  std::cout << "Built string: " << message << " (" << message.size() << " chars)\n";
  return 0;
}

#include <iostream>

int main() {
  int size = 5;
  std::cout << "How big (1 to 15)? ";
  if (!(std::cin >> size) || size < 1 || size > 15) size = 5;

  std::cout << "\nRight triangle:\n";
  for (int row = 1; row <= size; row++) {
    for (int star = 0; star < row; star++) std::cout << '*';
    std::cout << '\n';
  }

  std::cout << "\nPyramid:\n";
  for (int row = 1; row <= size; row++) {
    for (int s = 0; s < size - row; s++) std::cout << ' ';   // spaces push it to the middle
    for (int s = 0; s < row * 2 - 1; s++) std::cout << '*';  // 1, 3, 5, 7 stars...
    std::cout << '\n';
  }

  std::cout << "\nDiamond:\n";
  for (int row = -size + 1; row < size; row++) {
    int width = size - (row < 0 ? -row : row);  // grows, then shrinks
    for (int s = 0; s < size - width; s++) std::cout << ' ';
    for (int s = 0; s < width * 2 - 1; s++) std::cout << '#';
    std::cout << '\n';
  }

  std::cout << "\nCheckerboard:\n";
  for (int row = 0; row < size; row++) {
    for (int col = 0; col < size * 2; col++) {
      std::cout << ((row + col) % 2 == 0 ? '#' : '.');
    }
    std::cout << '\n';
  }
  return 0;
}

#include <iostream>
#include <string>

class Enemy {
public:
  explicit Enemy(const std::string &type) : type_(type), id_(nextId_++) {
    alive_++;
    std::cout << "Spawned " << type_ << " #" << id_ << " (alive: " << alive_ << ")\n";
  }
  ~Enemy() {
    alive_--;
    std::cout << type_ << " #" << id_ << " defeated (alive: " << alive_ << ")\n";
  }

  // A static function belongs to the class, not to one object.
  static int aliveCount() { return alive_; }

private:
  std::string type_;
  int id_;
  // "static" = ONE copy shared by every Enemy. "inline" lets us set it right here (C++17).
  inline static int alive_ = 0;
  inline static int nextId_ = 1;
};

// A static variable inside a function remembers its value between calls.
int callCounter() {
  static int calls = 0;
  return ++calls;
}

int main() {
  std::cout << "Enemies at start: " << Enemy::aliveCount() << "\n";
  Enemy goblin("goblin");
  {
    Enemy bat("bat");
    Enemy slime("slime");
    std::cout << "Enemies in the cave: " << Enemy::aliveCount() << "\n";
  }
  Enemy troll("troll");
  std::cout << "Enemies now: " << Enemy::aliveCount() << "\n\n";

  for (int i = 0; i < 3; i++) std::cout << "callCounter() = " << callCounter() << "\n";
  return 0;
}

#include <iostream>
#include <optional>
#include <string>
#include <vector>

struct Player {
  std::string name;
  int level;
};

// Returns a Player if found, or nothing (std::nullopt) if not.
std::optional<Player> findPlayer(const std::vector<Player> &players, const std::string &name) {
  for (const Player &p : players) {
    if (p.name == name) return p;
  }
  return std::nullopt;
}

// Dividing by zero has no answer, so we say so instead of crashing.
std::optional<double> safeDivide(double a, double b) {
  if (b == 0) return std::nullopt;
  return a / b;
}

int main() {
  std::vector<Player> players = {{"Ava", 12}, {"Leo", 7}, {"Kai", 20}};

  for (const std::string name : {"Leo", "Zed"}) {
    std::optional<Player> found = findPlayer(players, name);
    if (found.has_value()) {
      std::cout << name << " found at level " << found->level << "\n";
    } else {
      std::cout << name << " is not in the game\n";
    }
  }

  auto good = safeDivide(10, 4);
  auto bad = safeDivide(10, 0);
  std::cout << "\n10 / 4 = " << good.value_or(-1) << "\n";
  // value_or gives a backup value when there is no answer.
  std::cout << "10 / 0 = " << (bad ? std::to_string(*bad) : std::string("no answer!")) << "\n";
  return 0;
}

#include <iostream>
#include <string>
#include <type_traits>
#include <variant>
#include <vector>

// Loot can be ONE of these three types at a time.
using Loot = std::variant<int, std::string, double>;

int main() {
  std::vector<Loot> chest = {50, std::string("Flame Sword"), 0.75, 120, std::string("Ice Bow")};

  int gold = 0;
  for (const Loot &item : chest) {
    // holds_alternative checks which type is inside.
    if (std::holds_alternative<int>(item)) {
      gold += std::get<int>(item);
      std::cout << "Gold coins: " << std::get<int>(item) << "\n";
    } else if (std::holds_alternative<std::string>(item)) {
      std::cout << "Weapon: " << std::get<std::string>(item) << "\n";
    } else {
      std::cout << "Potion that heals " << std::get<double>(item) * 100 << "%\n";
    }
  }
  std::cout << "Total gold: " << gold << "\n\n";

  // std::visit runs code for whatever type is inside. "auto" lets one lambda handle all three.
  for (const Loot &item : chest) {
    std::visit([](const auto &value) {
      using T = std::decay_t<decltype(value)>;
      if constexpr (std::is_same_v<T, int>) std::cout << "[int] ";
      else if constexpr (std::is_same_v<T, std::string>) std::cout << "[string] ";
      else std::cout << "[double] ";
      std::cout << value << "\n";
    }, item);
  }

  // Changing the type inside is fine. It just becomes the new type.
  Loot surprise = 10;
  surprise = std::string("Mystery Box");
  std::cout << "\nThe surprise is now a string? " << std::boolalpha
            << std::holds_alternative<std::string>(surprise) << "\n";
  return 0;
}

#include <algorithm>
