  // Add to the end.
  inventory.push_back("potion");
  inventory.push_back("map");
  std::cout << "After adding: ";
  printAll(inventory);

  // Read and change an item by its position (starts at 0!).
  std::cout << "First item: " << inventory[0] << "\n";
  inventory[1] = "golden shield";
  std::cout << "After upgrade: ";
  printAll(inventory);

  // Find an item.
  auto spot = std::find(inventory.begin(), inventory.end(), "potion");
  if (spot != inventory.end()) {
    std::cout << "Found potion at position " << (spot - inventory.begin()) << "\n";
    inventory.erase(spot);  // use it up
  }
  std::cout << "After using potion: ";
  printAll(inventory);

  // Remove the last item.
  inventory.pop_back();
  std::cout << "After dropping last item: ";
  printAll(inventory);

  // A vector of numbers, plus a "for each" loop to add them up.
  std::vector<int> scores = {40, 75, 90, 15};
  int total = 0;
  for (int score : scores) total += score;
  std::cout << "Total score: " << total << "\n";

  // Sort the numbers from small to big.
  std::sort(scores.begin(), scores.end());
  std::cout << "Sorted scores:";
  for (int score : scores) std::cout << " " << score;
  std::cout << "\n";

  // Empty it out.
  inventory.clear();
  std::cout << "Inventory empty? " << (inventory.empty() ? "yes" : "no") << "\n";
  return 0;
}

#include <iomanip>
#include <iostream>
#include <string>
#include <vector>

// A struct bundles related values into one new type.
struct Book {
  std::string title;
  std::string author;
  int pages;
  bool finished;
};

void printBook(const Book &b) {
  std::cout << std::left << std::setw(24) << b.title << std::setw(18) << b.author
            << std::right << std::setw(5) << b.pages << "  " << (b.finished ? "read" : "to read") << "\n";
}

int main() {
  std::vector<Book> shelf = {
    {"The Hobbit", "J.R.R. Tolkien", 310, true},
    {"Wings of Fire", "Tui T. Sutherland", 336, true},
    {"Hatchet", "Gary Paulsen", 195, false},
    {"Percy Jackson", "Rick Riordan", 377, false},
  };

  // Add one more. You can set fields one at a time too.
  Book newBook;
  newBook.title = "Holes";
  newBook.author = "Louis Sachar";
  newBook.pages = 233;
  newBook.finished = false;
  shelf.push_back(newBook);

  std::cout << "My bookshelf:\n";
  for (const Book &b : shelf) printBook(b);

  int pagesRead = 0, pagesLeft = 0;
  const Book *longest = &shelf[0];
  for (const Book &b : shelf) {
    if (b.finished) pagesRead += b.pages;
    else pagesLeft += b.pages;
    if (b.pages > longest->pages) longest = &b;
  }
  std::cout << "\nPages read: " << pagesRead << ", pages to go: " << pagesLeft << "\n";
  std::cout << "Longest book: " << longest->title << "\n";

  // Finish a book by changing its field.
  shelf[2].finished = true;
  std::cout << "Just finished " << shelf[2].title << "!\n";
  return 0;
}

#include <chrono>
#include <iostream>
#include <vector>

int main() {
  using Clock = std::chrono::steady_clock;  // a clock that never jumps backwards

  const int N = 5000000;
  std::vector<int> numbers(N, 1);

  // Way 1: a normal loop.
  auto start = Clock::now();
  long long total1 = 0;
  for (int i = 0; i < N; i++) total1 += numbers[i];
  auto end = Clock::now();
  auto loopUs = std::chrono::duration_cast<std::chrono::microseconds>(end - start).count();

  // Way 2: the formula 1 + 2 + ... + N = N * (N + 1) / 2 (no loop at all!).
  start = Clock::now();
  long long total2 = static_cast<long long>(N) * (N + 1) / 2;
  end = Clock::now();
  auto formulaNs = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();

  std::cout << "Adding " << N << " ones with a loop: " << total1 << " in " << loopUs << " microseconds\n";
  std::cout << "1 + 2 + ... + " << N << " with a formula: " << total2 << " in " << formulaNs << " nanoseconds\n";
  std::cout << "(1 second = 1,000,000 microseconds = 1,000,000,000 nanoseconds)\n\n";

  // Time how fast YOU are.
  std::cout << "Type anything and press Enter as fast as you can: ";
  start = Clock::now();
  std::string line;
  std::getline(std::cin, line);
  std::chrono::duration<double> seconds = Clock::now() - start;
  std::cout << "You took " << seconds.count() << " seconds.\n";
  return 0;
}

