  std::cout << "'A' as a number is " << static_cast<int>(grade) << "\n";

  // const means the value can never change.
  const double PI = 3.14159;
  std::cout << "Area of a circle with radius 2: " << PI * 2 * 2 << "\n";
  return 0;
}

#include <cctype>
