#include <iostream>
#include <map>
#include <memory>
#include <string>
#include <vector>

struct TrieNode {
  std::map<char, std::unique_ptr<TrieNode>> children;  // one child per next letter
  bool endsWord = false;
};

class Trie {
public:
  void insert(const std::string &word) {
    TrieNode *node = &root_;
    for (char c : word) {
      auto &child = node->children[c];
      if (!child) child = std::make_unique<TrieNode>();
      node = child.get();
    }
    node->endsWord = true;
  }

  std::vector<std::string> startingWith(const std::string &prefix) const {
    const TrieNode *node = &root_;
    for (char c : prefix) {  // walk down the letters of the prefix
      auto it = node->children.find(c);
      if (it == node->children.end()) return {};
      node = it->second.get();
    }
    std::vector<std::string> found;
    collect(node, prefix, found);
    return found;
  }

private:
  TrieNode root_;

  // Visit every branch below this node and gather complete words.
  static void collect(const TrieNode *node, const std::string &sofar, std::vector<std::string> &out) {
    if (node->endsWord) out.push_back(sofar);
    for (const auto &[letter, child] : node->children) collect(child.get(), sofar + letter, out);
  }
};

int main() {
  Trie words;
  for (const char *w : {"arduino", "array", "arrow", "robot", "rocket", "rock", "roblox", "router",
                        "sensor", "servo", "server", "serial", "stepper", "steam"}) {
    words.insert(w);
  }

  std::cout << "Type the start of a word (Ctrl+D to quit). Try: ro, ser, ar, st\n";
  std::string prefix;
  while (std::cout << "> " && std::cin >> prefix) {
    auto matches = words.startingWith(prefix);
    if (matches.empty()) std::cout << "  no words start with \"" << prefix << "\"\n";
    for (const auto &m : matches) std::cout << "  " << m << "\n";
  }
  std::cout << "\n";
  return 0;
}

#include <iostream>
#include <stack>
#include <string>

// Returns -1 if balanced, otherwise the position of the problem.
int findProblem(const std::string &text) {
  std::stack<std::pair<char, int>> open;  // the bracket and where it was
  for (int i = 0; i < static_cast<int>(text.size()); i++) {
    char c = text[i];
    if (c == '(' || c == '[' || c == '{') {
      open.push({c, i});
    } else if (c == ')' || c == ']' || c == '}') {
      if (open.empty()) return i;  // closing with nothing open
      char want = c == ')' ? '(' : (c == ']' ? '[' : '{');
      if (open.top().first != want) return i;  // wrong kind, like ( ]
      open.pop();
    }
  }
  if (!open.empty()) return open.top().second;  // something never got closed
  return -1;
}

int main() {
  std::string tests[] = {"if (x[0] == y) { go(); }", "((2 + 3) * 4", "{ [ ( ] ) }", "print(\"hi\"))"};
  for (const auto &t : tests) {
    int bad = findProblem(t);
    std::cout << t << "\n";
    if (bad < 0) std::cout << "  balanced!\n";
    else std::cout << "  " << std::string(bad, ' ') << "^ problem here\n";
  }

  std::cout << "\nNow type your own lines (Ctrl+D to stop):\n";
  std::string line;
  while (std::getline(std::cin, line)) {
    int bad = findProblem(line);
    if (bad < 0) std::cout << "  balanced!\n";
    else std::cout << line << "\n" << std::string(bad, ' ') << "^ problem here\n";
  }
  return 0;
}

#include <iostream>
#include <memory>

struct TreeNode {
  int value;
  std::unique_ptr<TreeNode> left;   // smaller numbers go left
  std::unique_ptr<TreeNode> right;  // bigger numbers go right
  explicit TreeNode(int v) : value(v) {}
};

class BST {
public:
  void insert(int v) { insert(root_, v); }
  bool contains(int v) const {
    const TreeNode *cur = root_.get();
    while (cur) {
      if (v == cur->value) return true;
      cur = v < cur->value ? cur->left.get() : cur->right.get();  // go left or right
    }
    return false;
  }
  void printSorted() const { inOrder(root_.get()); std::cout << "\n"; }
  int height() const { return height(root_.get()); }
  void draw() const { draw(root_.get(), 0); }

private:
  std::unique_ptr<TreeNode> root_;

  static void insert(std::unique_ptr<TreeNode> &node, int v) {
    if (!node) { node = std::make_unique<TreeNode>(v); return; }
    if (v < node->value) insert(node->left, v);
    else if (v > node->value) insert(node->right, v);
    // equal: already in the tree, do nothing
  }
  // In-order (left, me, right) visits the numbers smallest to biggest.
  static void inOrder(const TreeNode *n) {
    if (!n) return;
    inOrder(n->left.get());
    std::cout << n->value << " ";
    inOrder(n->right.get());
  }
  static int height(const TreeNode *n) {
    if (!n) return 0;
    int l = height(n->left.get()), r = height(n->right.get());
    return 1 + (l > r ? l : r);
  }
  // Draw sideways: right side on top, root on the left edge.
  static void draw(const TreeNode *n, int depth) {
    if (!n) return;
    draw(n->right.get(), depth + 1);
    std::cout << std::string(depth * 4, ' ') << n->value << "\n";
    draw(n->left.get(), depth + 1);
  }
};

int main() {
  BST tree;
  for (int v : {50, 30, 70, 20, 40, 60, 80, 35, 65}) tree.insert(v);

  std::cout << "Sorted: ";
  tree.printSorted();
  std::cout << "Height: " << tree.height() << "\n";
  std::cout << "Tree (turn your head left!):\n";
  tree.draw();

  std::cout << "\nType numbers to search for (Ctrl+D to stop):\n";
  int n;
  while (std::cin >> n) {
    std::cout << n << (tree.contains(n) ? " is in the tree\n" : " is not in the tree\n");
  }
  return 0;
}

#include <algorithm>
#include <iostream>
#include <vector>

int linearSearch(const std::vector<int> &v, int target, int &looks) {
  for (std::size_t i = 0; i < v.size(); i++) {
    looks++;
    if (v[i] == target) return static_cast<int>(i);
  }
  return -1;
}

// Only works on SORTED lists: look in the middle and throw away the half it can't be in.
int binarySearch(const std::vector<int> &v, int target, int &looks) {
  int low = 0, high = static_cast<int>(v.size()) - 1;
  while (low <= high) {
    int mid = low + (high - low) / 2;
    looks++;
    if (v[mid] == target) return mid;
    if (v[mid] < target) low = mid + 1;  // it's in the right half
    else high = mid - 1;                 // it's in the left half
  }
  return -1;
}

int main() {
  std::vector<int> evens;
  for (int i = 0; i < 1000000; i++) evens.push_back(i * 2);  // 0, 2, 4, ... sorted

  std::cout << "A sorted list of " << evens.size() << " even numbers. Type numbers to find (Ctrl+D to stop):\n";
  int target;
  std::vector<int> tries = {1999998, 777776, 13};
  bool typed = false;
  while (true) {
    if (std::cin >> target) typed = true;
    else if (!typed && !tries.empty()) { target = tries.back(); tries.pop_back(); }
    else break;

    int linLooks = 0, binLooks = 0;
    int at = linearSearch(evens, target, linLooks);
    binarySearch(evens, target, binLooks);
    std::cout << target << (at >= 0 ? " found at position " + std::to_string(at) : std::string(" not found"))
              << "\n  linear search looked " << linLooks << " times\n  binary search looked " << binLooks << " times\n";
  }

  // The standard library has binary search built in.
  bool has = std::binary_search(evens.begin(), evens.end(), 4242);
  std::cout << "std::binary_search for 4242: " << (has ? "found" : "not found") << "\n";
  return 0;
}

#include <iostream>
#include <utility>
#include <vector>

void print(const std::vector<int> &v) {
  for (int x : v) std::cout << x << " ";
  std::cout << "\n";
}

int main() {
  std::vector<int> nums = {29, 10, 14, 37, 13, 5, 42, 1};
  std::cout << "Start:   ";
  print(nums);

  int swaps = 0, compares = 0;
  for (std::size_t pass = 0; pass + 1 < nums.size(); pass++) {
    bool swapped = false;
    // After each pass, the biggest unsorted number has "bubbled" to the end, so check one less.
    for (std::size_t i = 0; i + 1 < nums.size() - pass; i++) {
      compares++;
      if (nums[i] > nums[i + 1]) {
        std::swap(nums[i], nums[i + 1]);
        swaps++;
        swapped = true;
      }
    }
    std::cout << "Pass " << pass + 1 << ":  ";
    print(nums);
    if (!swapped) {  // no swaps means it's already sorted: stop early
      std::cout << "No swaps, so we're done early!\n";
      break;
    }
  }
  std::cout << "Sorted with " << compares << " comparisons and " << swaps << " swaps.\n";
  std::cout << "Bubble sort is easy but slow for big lists (it does about n x n steps).\n";
  return 0;
}

#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

template <typename T>
class Stack {
public:
  void push(const T &item) { items_.push_back(item); }  // put on top

  T pop() {  // take off the top
    if (empty()) throw std::runtime_error("pop on an empty stack");
    T top = items_.back();
    items_.pop_back();
    return top;
  }

  const T &peek() const {  // look at the top without taking it
    if (empty()) throw std::runtime_error("peek on an empty stack");
    return items_.back();
  }

  bool empty() const { return items_.empty(); }
  std::size_t size() const { return items_.size(); }

private:
  std::vector<T> items_;
};

int main() {
  std::string text;
  Stack<std::string> undo;  // remembers what the text looked like before each change

  std::cout << "Mini editor. Type a word to add it, 'undo' to undo, 'quit' to stop.\n";
  std::string word;
  while (std::cout << "text: \"" << text << "\"\n> " && std::cin >> word && word != "quit") {
    if (word == "undo") {
      if (undo.empty()) {
        std::cout << "Nothing to undo!\n";
      } else {
        text = undo.pop();
        std::cout << "Undone. (" << undo.size() << " undo steps left)\n";
      }
    } else {
      undo.push(text);  // save the old version first
      text += (text.empty() ? "" : " ") + word;
    }
  }

  // A stack reverses things: push 1,2,3 and pop gives 3,2,1.
  Stack<int> nums;
  for (int i = 1; i <= 5; i++) nums.push(i);
  std::cout << "\nPopping 1..5 gives:";
  while (!nums.empty()) std::cout << " " << nums.pop();
  std::cout << "\n";
  return 0;
}

#include <iostream>
#include <stdexcept>

class IntVector {
public:
  IntVector() = default;
  ~IntVector() { delete[] data_; }
  // Copying needs its own memory, or two vectors would share (and double-delete) one array.
  IntVector(const IntVector &other) : data_(new int[other.capacity_]), size_(other.size_), capacity_(other.capacity_) {
    for (std::size_t i = 0; i < size_; i++) data_[i] = other.data_[i];
  }
  IntVector &operator=(IntVector other) {  // copy-and-swap: simple and safe
    std::swap(data_, other.data_);
    std::swap(size_, other.size_);
    std::swap(capacity_, other.capacity_);
    return *this;
  }

  void push_back(int v) {
    if (size_ == capacity_) grow();
    data_[size_++] = v;
  }

  int &operator[](std::size_t i) {
    if (i >= size_) throw std::out_of_range("index too big");
    return data_[i];
  }

  std::size_t size() const { return size_; }
  std::size_t capacity() const { return capacity_; }

private:
  int *data_ = nullptr;
  std::size_t size_ = 0;      // how many are used
  std::size_t capacity_ = 0;  // how many fit before we need more room

  void grow() {
    std::size_t newCap = capacity_ == 0 ? 1 : capacity_ * 2;  // double it
    int *bigger = new int[newCap];
    for (std::size_t i = 0; i < size_; i++) bigger[i] = data_[i];  // copy the old items
    delete[] data_;
    data_ = bigger;
    std::cout << "  grew from " << capacity_ << " to " << newCap << " slots\n";
    capacity_ = newCap;
  }
};

int main() {
  IntVector v;
  for (int i = 1; i <= 10; i++) {
    v.push_back(i * i);
    std::cout << "added " << i * i << " (size " << v.size() << ", capacity " << v.capacity() << ")\n";
  }

  IntVector copy = v;
  copy[0] = 999;
  std::cout << "\nv[0] = " << v[0] << ", copy[0] = " << copy[0] << " (separate memory)\n";

  try {
    std::cout << v[50] << "\n";
  } catch (const std::out_of_range &e) {
    std::cout << "v[50] -> error: " << e.what() << "\n";
  }
  return 0;
}

#include <array>
#include <iostream>

template <typename T, std::size_t N>
class RingQueue {
public:
  bool enqueue(const T &item) {
    if (full()) return false;
    data_[tail_] = item;
    tail_ = (tail_ + 1) % N;  // % N wraps back to 0 at the end
    count_++;
    return true;
  }

  bool dequeue(T &out) {
    if (empty()) return false;
    out = data_[head_];
    head_ = (head_ + 1) % N;
    count_--;
    return true;
  }

  bool empty() const { return count_ == 0; }
  bool full() const { return count_ == N; }

  void draw() const {
    std::cout << "  slots: ";
    for (std::size_t i = 0; i < N; i++) {
      bool used = (i - head_ + N) % N < count_;  // is slot i between head and tail?
      std::cout << "[" << (used ? std::to_string(data_[i]) : std::string(" ")) << "]";
    }
    std::cout << "  head=" << head_ << " tail=" << tail_ << " count=" << count_ << "\n";
  }

private:
  std::array<T, N> data_{};
  std::size_t head_ = 0;  // where we take from
  std::size_t tail_ = 0;  // where we add to
  std::size_t count_ = 0;
};

int main() {
  RingQueue<int, 5> q;
  std::cout << "Add 1..4:\n";
  for (int i = 1; i <= 4; i++) q.enqueue(i);
  q.draw();

  int x;
  std::cout << "Take two out:\n";
  q.dequeue(x); std::cout << "  got " << x << "\n";
  q.dequeue(x); std::cout << "  got " << x << "\n";
  q.draw();

  std::cout << "Add 5, 6, 7 (watch them wrap around to the start):\n";
  for (int i = 5; i <= 7; i++) q.enqueue(i);
  q.draw();
  std::cout << "Try to add 8 when full: " << (q.enqueue(8) ? "added" : "queue is full!") << "\n";

  std::cout << "Empty it out in order:";
  while (q.dequeue(x)) std::cout << " " << x;
  std::cout << "\n";
  return 0;
}

#include <algorithm>
#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>

int main() {
  // unordered_map finds things super fast but keeps them in no particular order.
  std::unordered_map<std::string, std::string> book = {
    {"mom", "555-0101"}, {"grandpa", "555-0199"}, {"pizza", "555-0123"},
  };

  std::cout << "Commands: add NAME NUMBER, find NAME, remove NAME, list, quit\n";
  std::string cmd;
  while (std::cout << "> " && std::cin >> cmd && cmd != "quit") {
    if (cmd == "add") {
      std::string name, number;
      if (!(std::cin >> name >> number)) break;
      bool isNew = book.count(name) == 0;
      book[name] = number;  // adds a new one or replaces the old number
      std::cout << (isNew ? "Added " : "Updated ") << name << "\n";
    } else if (cmd == "find") {
      std::string name;
      if (!(std::cin >> name)) break;
      auto it = book.find(name);  // find returns end() if it's not there
      if (it != book.end()) std::cout << name << ": " << it->second << "\n";
      else std::cout << "No contact called " << name << "\n";
    } else if (cmd == "remove") {
      std::string name;
      if (!(std::cin >> name)) break;
      std::cout << (book.erase(name) ? "Removed " : "Couldn't find ") << name << "\n";
    } else if (cmd == "list") {
      // Copy the names out and sort them so the list looks tidy.
      std::vector<std::string> names;
      for (const auto &entry : book) names.push_back(entry.first);
      std::sort(names.begin(), names.end());
      for (const auto &n : names) std::cout << "  " << n << ": " << book[n] << "\n";
      std::cout << "  (" << book.size() << " contacts)\n";
    } else {
      std::cout << "Unknown command\n";
    }
  }
  return 0;
}

#include <iostream>
#include <string>
#include <vector>

std::vector<std::string> world = {
  "~~##~~~~~~~#~",
  "~###~~~##~~##",
  "~~#~~~~##~~~~",
  "~~~~#~~~~~~~~",
  "~~~###~~~##~~",
  "#~~~#~~~~###~",
  "##~~~~~~~~#~~",
};

// Visit a land square, mark it, then visit its land neighbours. Returns the island's size.
int explore(int r, int c, char label) {
  if (r < 0 || c < 0 || r >= static_cast<int>(world.size()) || c >= static_cast<int>(world[r].size())) return 0;
  if (world[r][c] != '#') return 0;  // water or already labeled
  world[r][c] = label;
  return 1 + explore(r - 1, c, label) + explore(r + 1, c, label) + explore(r, c - 1, label) + explore(r, c + 1, label);
}

int main() {
  std::cout << "Map (# = land, ~ = water):\n";
  for (const auto &row : world) std::cout << row << "\n";

  int islands = 0, biggest = 0;
  char biggestLabel = '?';
  for (int r = 0; r < static_cast<int>(world.size()); r++) {
    for (int c = 0; c < static_cast<int>(world[r].size()); c++) {
      if (world[r][c] == '#') {
        char label = static_cast<char>('A' + islands);
        int size = explore(r, c, label);
        islands++;
        if (size > biggest) { biggest = size; biggestLabel = label; }
      }
    }
  }

  std::cout << "\nLabeled islands:\n";
  for (const auto &row : world) std::cout << row << "\n";
  std::cout << "\nIslands found: " << islands << "\n";
  std::cout << "Biggest is island " << biggestLabel << " with " << biggest << " squares\n";
  return 0;
}

#include <iostream>
#include <random>
#include <vector>

int main() {
  std::mt19937 rng(2026);
  std::normal_distribution<double> bell(7.0, 1.8);  // most scores near 7
  std::vector<int> scores;
  for (int i = 0; i < 30; i++) {
    int s = static_cast<int>(bell(rng) + 0.5);
    if (s < 0) s = 0;
    if (s > 10) s = 10;
    scores.push_back(s);
  }

  std::cout << "Scores:";
  for (int s : scores) std::cout << " " << s;
  std::cout << "\n\n";

  // Step 1: count how many times each score appears. No comparing at all!
  int counts[11] = {0};
  for (int s : scores) counts[s]++;

  std::cout << "Tally chart:\n";
  for (int s = 0; s <= 10; s++) {
    std::cout << (s < 10 ? " " : "") << s << " | ";
    for (int k = 0; k < counts[s]; k++) std::cout << "#";
    std::cout << " " << counts[s] << "\n";
  }

  // Step 2: write each score out as many times as it was counted.
  std::vector<int> sorted;
  for (int s = 0; s <= 10; s++)
    for (int k = 0; k < counts[s]; k++) sorted.push_back(s);

  std::cout << "\nSorted:";
  for (int s : sorted) std::cout << " " << s;
  std::cout << "\nMedian (middle) score: " << sorted[sorted.size() / 2] << "\n";
  return 0;
}

#include <iostream>
#include <string>

struct Song {
  std::string title;
  Song *prev = nullptr;
  Song *next = nullptr;
};

class Playlist {
public:
  Playlist() = default;
  Playlist(const Playlist &) = delete;
  Playlist &operator=(const Playlist &) = delete;
  ~Playlist() {
    while (head_) {
      Song *next = head_->next;
      delete head_;
      head_ = next;
    }
  }

  void add(const std::string &title) {
    Song *s = new Song{title};
    if (!tail_) {
      head_ = tail_ = current_ = s;
    } else {
      tail_->next = s;  // old last song points forward to the new one
      s->prev = tail_;  // and the new one points back
      tail_ = s;
    }
  }

  void next() {
    if (current_ && current_->next) current_ = current_->next;
    else std::cout << "(end of playlist)\n";
  }

  void previous() {
    if (current_ && current_->prev) current_ = current_->prev;
    else std::cout << "(already at the first song)\n";
  }

  void show() const {
    for (Song *s = head_; s; s = s->next) {
      std::cout << (s == current_ ? " >> " : "    ") << s->title << "\n";
    }
  }

  void showBackwards() const {
    std::cout << "Backwards:";
    for (Song *s = tail_; s; s = s->prev) std::cout << " " << s->title << " |";
    std::cout << "\n";
  }

private:
  Song *head_ = nullptr;
  Song *tail_ = nullptr;
  Song *current_ = nullptr;
};

int main() {
  Playlist list;
  for (const char *t : {"Eye of the Tiger", "Thunderstruck", "Believer", "Radioactive", "Levels"}) list.add(t);

  std::cout << "Commands: n (next), p (previous), b (backwards), q (quit)\n";
  list.show();
  char c;
  while (std::cin >> c && c != 'q') {
    if (c == 'n') list.next();
    else if (c == 'p') list.previous();
    else if (c == 'b') { list.showBackwards(); continue; }
    list.show();
  }
  return 0;
}

#include <iostream>
#include <map>
#include <numeric>
#include <string>
#include <vector>

class UnionFind {
public:
  explicit UnionFind(int n) : parent_(n), size_(n, 1) {
    std::iota(parent_.begin(), parent_.end(), 0);  // everyone starts as their own group leader
  }

  // Find the group leader. Path compression makes later finds super fast.
  int find(int x) {
    if (parent_[x] != x) parent_[x] = find(parent_[x]);
    return parent_[x];
  }

  void unite(int a, int b) {
    int ra = find(a), rb = find(b);
    if (ra == rb) return;
    if (size_[ra] < size_[rb]) std::swap(ra, rb);  // small group joins the big group
    parent_[rb] = ra;
    size_[ra] += size_[rb];
  }

private:
  std::vector<int> parent_, size_;
};

int main() {
  std::vector<std::string> kids = {"Ava", "Ben", "Cai", "Dee", "Eli", "Fay", "Gus", "Hana"};
  UnionFind groups(static_cast<int>(kids.size()));

  // Pairs who are friends.
  std::vector<std::pair<int, int>> friendships = {{0, 1}, {1, 4}, {2, 3}, {5, 6}, {6, 2}};
  for (auto [a, b] : friendships) {
    std::cout << kids[a] << " and " << kids[b] << " are friends\n";
    groups.unite(a, b);
  }

  std::cout << "\nAre Ava and Eli in the same group? "
            << (groups.find(0) == groups.find(4) ? "yes (through Ben)" : "no") << "\n";
  std::cout << "Are Ava and Dee in the same group? " << (groups.find(0) == groups.find(3) ? "yes" : "no") << "\n";

  std::map<int, std::vector<std::string>> byLeader;
  for (int i = 0; i < static_cast<int>(kids.size()); i++) byLeader[groups.find(i)].push_back(kids[i]);
  std::cout << "\nFriend groups:\n";
  for (const auto &[leader, members] : byLeader) {
    std::cout << " -";
    for (const auto &m : members) std::cout << " " << m;
    std::cout << "\n";
  }
  return 0;
}

#include <iomanip>
#include <iostream>
#include <map>
#include <string>

struct ItemInfo {
  double weight;
  int maxStack;
};

const std::map<std::string, ItemInfo> ITEMS = {
  {"wood", {1.0, 64}}, {"stone", {2.0, 64}}, {"stick", {0.5, 64}},
  {"pickaxe", {3.0, 1}}, {"apple", {0.3, 16}},
};

class Inventory {
public:
  bool add(const std::string &item, int count) {
    auto info = ITEMS.find(item);
    if (info == ITEMS.end()) { std::cout << "  Unknown item: " << item << "\n"; return false; }
    auto have = counts_.find(item);
    int already = have == counts_.end() ? 0 : have->second;  // find() doesn't add empty entries like [] does
    if (already + count > info->second.maxStack) { std::cout << "  Stack of " << item << " is full!\n"; return false; }
    if (weight() + info->second.weight * count > MAX_WEIGHT) { std::cout << "  Too heavy!\n"; return false; }
    counts_[item] += count;
    return true;
  }

  bool remove(const std::string &item, int count) {
    auto it = counts_.find(item);
    if (it == counts_.end() || it->second < count) return false;
    it->second -= count;
    if (it->second == 0) counts_.erase(it);
    return true;
  }

  bool has(const std::string &item, int count) const {
    auto it = counts_.find(item);
    return it != counts_.end() && it->second >= count;
  }

  double weight() const {
    double total = 0;
    for (const auto &[item, n] : counts_) total += ITEMS.at(item).weight * n;
    return total;
  }

  void show() const {
    std::cout << "  Inventory (" << std::fixed << std::setprecision(1) << weight() << "/" << MAX_WEIGHT << " kg):";
    if (counts_.empty()) std::cout << " empty";
    for (const auto &[item, n] : counts_) std::cout << " " << item << " x" << n << ";";
    std::cout << "\n";
  }

private:
  static constexpr double MAX_WEIGHT = 50.0;
  std::map<std::string, int> counts_;
};

// Recipe: 3 stone + 2 sticks = 1 pickaxe.
bool craftPickaxe(Inventory &inv) {
  if (!inv.has("stone", 3) || !inv.has("stick", 2)) return false;
  inv.remove("stone", 3);
  inv.remove("stick", 2);
  return inv.add("pickaxe", 1);
}

int main() {
  Inventory inv;
  std::cout << "Commands: add ITEM N, drop ITEM N, craft, show, quit\nItems: wood stone stick pickaxe apple\n";
  std::string cmd;
  while (std::cout << "> " && std::cin >> cmd && cmd != "quit") {
    if (cmd == "add" || cmd == "drop") {
      std::string item;
      int n;
      if (!(std::cin >> item >> n) || n <= 0) break;
      bool ok = cmd == "add" ? inv.add(item, n) : inv.remove(item, n);
      if (!ok && cmd == "drop") std::cout << "  You don't have that many.\n";
    } else if (cmd == "craft") {
      std::cout << (craftPickaxe(inv) ? "  Crafted a pickaxe!\n" : "  Need 3 stone and 2 sticks (and a free slot).\n");
    } else if (cmd != "show") {
      std::cout << "  Unknown command\n";
      continue;
    }
    inv.show();
  }
  return 0;
}

#include <iostream>
#include <list>
#include <string>
#include <utility>
#include <vector>

class HashTable {
public:
  explicit HashTable(std::size_t buckets) : buckets_(buckets) {}

  void put(const std::string &key, int value) {
    auto &bucket = buckets_[indexFor(key)];
    for (auto &pair : bucket) {
      if (pair.first == key) { pair.second = value; return; }  // update
    }
    bucket.push_back({key, value});  // new key goes on the bucket's chain
  }

  bool get(const std::string &key, int &out) const {
    for (const auto &pair : buckets_[indexFor(key)]) {
      if (pair.first == key) { out = pair.second; return true; }
    }
    return false;
  }

  void draw() const {
    for (std::size_t i = 0; i < buckets_.size(); i++) {
      std::cout << "  bucket " << i << ":";
      for (const auto &pair : buckets_[i]) std::cout << " [" << pair.first << "=" << pair.second << "]";
      std::cout << "\n";
    }
  }

private:
  std::vector<std::list<std::pair<std::string, int>>> buckets_;

  // A hash function turns a key into a number. Same key = same number, every time.
  std::size_t indexFor(const std::string &key) const {
    std::size_t hash = 5381;
    for (char c : key) hash = hash * 33 + static_cast<unsigned char>(c);  // the "djb2" hash
    return hash % buckets_.size();
  }
};

int main() {
  HashTable ages(5);  // only 5 buckets, so some keys will share (a "collision")
  ages.put("Ava", 12);
  ages.put("Leo", 13);
  ages.put("Kai", 11);
  ages.put("Mia", 12);
  ages.put("Zoe", 14);
  ages.put("Sam", 10);
  ages.put("Leo", 14);  // happy birthday Leo: updates the old value

  std::cout << "Inside the hash table:\n";
  ages.draw();

  for (const std::string name : {"Leo", "Sam", "Bob"}) {
    int age;
    if (ages.get(name, age)) std::cout << name << " is " << age << "\n";
    else std::cout << name << " is not in the table\n";
  }
  return 0;
}

#include <iostream>
#include <queue>
#include <string>
#include <vector>

struct Task {
  std::string name;
  int daysUntilDue;
  int priority;  // 1 = low, 3 = high
};

// Decides which task is "less urgent". The priority_queue puts the MOST urgent on top.
struct LessUrgent {
  bool operator()(const Task &a, const Task &b) const {
    if (a.daysUntilDue != b.daysUntilDue) return a.daysUntilDue > b.daysUntilDue;  // sooner = more urgent
    return a.priority < b.priority;  // same day: higher priority first
  }
};

int main() {
  std::priority_queue<Task, std::vector<Task>, LessUrgent> todo;
  todo.push({"Science poster", 5, 2});
  todo.push({"Math worksheet", 1, 2});
  todo.push({"Read chapter 4", 3, 1});
  todo.push({"Spelling test study", 1, 3});
  todo.push({"Arduino project", 7, 3});

  std::cout << "Add a task as: name_without_spaces days priority  (or 'done')\n";
  std::string name;
  int days, prio;
  while (std::cin >> name && name != "done" && std::cin >> days >> prio) {
    todo.push({name, days, prio});
    std::cout << "Added " << name << "\n";
  }

  std::cout << "\nDo your homework in this order:\n";
  int step = 1;
  while (!todo.empty()) {
    const Task &t = todo.top();  // the most urgent one
    std::cout << step++ << ". " << t.name << " (due in " << t.daysUntilDue << " days, priority " << t.priority << ")\n";
    todo.pop();
  }
  return 0;
}

#include <iostream>
#include <list>
#include <string>
#include <unordered_map>

class LRUCache {
public:
  explicit LRUCache(std::size_t capacity) : capacity_(capacity) {}

  // Returns true and fills value if the key is in the cache.
  bool get(const std::string &key, std::string &value) {
    auto it = where_.find(key);
    if (it == where_.end()) return false;
    order_.splice(order_.begin(), order_, it->second);  // move to the front: just used!
    value = it->second->second;
    return true;
  }

  void put(const std::string &key, const std::string &value) {
    auto it = where_.find(key);
    if (it != where_.end()) {
      it->second->second = value;
      order_.splice(order_.begin(), order_, it->second);
      return;
    }
    if (order_.size() == capacity_) {  // full: throw out the least recently used (the back)
      std::cout << "  (cache full, forgetting " << order_.back().first << ")\n";
      where_.erase(order_.back().first);
      order_.pop_back();
    }
    order_.push_front({key, value});
    where_[key] = order_.begin();
  }

  void show() const {
    std::cout << "  cache (newest first):";
    for (const auto &kv : order_) std::cout << " " << kv.first;
    std::cout << "\n";
  }

private:
  std::size_t capacity_;
  std::list<std::pair<std::string, std::string>> order_;  // front = most recently used
  std::unordered_map<std::string, std::list<std::pair<std::string, std::string>>::iterator> where_;
};

int main() {
  LRUCache cache(3);
  cache.put("cat.png", "picture of a cat");
  cache.put("dog.png", "picture of a dog");
  cache.put("map.png", "picture of a map");
  cache.show();

  std::string v;
  std::cout << "Look up cat.png: " << (cache.get("cat.png", v) ? v : "miss") << "\n";
  cache.show();

  cache.put("sun.png", "picture of the sun");  // dog.png is now the oldest, so it goes
  cache.show();
  std::cout << "Look up dog.png: " << (cache.get("dog.png", v) ? v : "miss (it was forgotten)") << "\n";
  return 0;
}

#include <cctype>
#include <iostream>
#include <stack>
#include <string>
#include <vector>

int precedence(char op) { return (op == '+' || op == '-') ? 1 : (op == '*' || op == '/') ? 2 : 0; }

// Step 1: turn "2+3*4" into the postfix list "2 3 4 * +". Returns false on a mistake.
bool toPostfix(const std::string &s, std::vector<std::string> &out) {
  std::stack<char> ops;
  for (std::size_t i = 0; i < s.size(); i++) {
    char c = s[i];
    if (std::isspace(static_cast<unsigned char>(c))) continue;
    if (std::isdigit(static_cast<unsigned char>(c)) || c == '.') {
      std::size_t j = i;
      while (j < s.size() && (std::isdigit(static_cast<unsigned char>(s[j])) || s[j] == '.')) j++;
      out.push_back(s.substr(i, j - i));
      i = j - 1;
    } else if (c == '(') {
      ops.push(c);
    } else if (c == ')') {
      while (!ops.empty() && ops.top() != '(') { out.push_back(std::string(1, ops.top())); ops.pop(); }
      if (ops.empty()) return false;  // a ) with no (
      ops.pop();
    } else if (precedence(c) > 0) {
      // Signs that bind tighter (or equal, left to right) leave the stack first.
      while (!ops.empty() && precedence(ops.top()) >= precedence(c)) { out.push_back(std::string(1, ops.top())); ops.pop(); }
      ops.push(c);
    } else {
      return false;  // unknown character
    }
  }
  while (!ops.empty()) {
    if (ops.top() == '(') return false;
    out.push_back(std::string(1, ops.top()));
    ops.pop();
  }
  return true;
}

// Step 2: work out the postfix list with a stack of numbers.
bool evaluate(const std::vector<std::string> &postfix, double &result) {
  std::stack<double> st;
  for (const auto &t : postfix) {
    if (precedence(t[0]) > 0 && t.size() == 1) {
      if (st.size() < 2) return false;
      double b = st.top(); st.pop();
      double a = st.top(); st.pop();
      if (t == "/" && b == 0) return false;
      st.push(t == "+" ? a + b : t == "-" ? a - b : t == "*" ? a * b : a / b);
    } else {
      try { st.push(std::stod(t)); } catch (const std::exception &) { return false; }
    }
  }
  if (st.size() != 1) return false;
  result = st.top();
  return true;
}

int main() {
  std::cout << "Type math like 2 + 3 * (4 - 1)  (Ctrl+D to quit)\n";
  std::string line;
  while (std::cout << "> " && std::getline(std::cin, line)) {
    if (line.empty()) continue;
    std::vector<std::string> postfix;
    double result;
    if (!toPostfix(line, postfix) || !evaluate(postfix, result)) {
      std::cout << "Sorry, I can't work that out.\n";
      continue;
    }
    std::cout << "postfix:";
    for (const auto &t : postfix) std::cout << " " << t;
    std::cout << "\n= " << result << "\n";
  }
  std::cout << "\n";
  return 0;
}

#include <cmath>
#include <iomanip>
#include <iostream>
#include <stdexcept>
#include <vector>

class Matrix {
public:
  Matrix(int rows, int cols) : rows_(rows), cols_(cols), data_(rows * cols, 0.0) {}
  Matrix(int rows, int cols, std::vector<double> values) : rows_(rows), cols_(cols), data_(std::move(values)) {
    if (static_cast<int>(data_.size()) != rows * cols) throw std::invalid_argument("wrong number of values");
  }

  // One long vector: row r, column c lives at r * cols + c.
  double &at(int r, int c) { return data_[r * cols_ + c]; }
  double at(int r, int c) const { return data_[r * cols_ + c]; }

  Matrix operator+(const Matrix &o) const {
    if (rows_ != o.rows_ || cols_ != o.cols_) throw std::invalid_argument("sizes must match to add");
    Matrix out(rows_, cols_);
    for (std::size_t i = 0; i < data_.size(); i++) out.data_[i] = data_[i] + o.data_[i];
    return out;
  }

  Matrix operator*(const Matrix &o) const {
    if (cols_ != o.rows_) throw std::invalid_argument("columns of A must equal rows of B");
    Matrix out(rows_, o.cols_);
    for (int r = 0; r < rows_; r++)
      for (int c = 0; c < o.cols_; c++)
        for (int k = 0; k < cols_; k++) out.at(r, c) += at(r, k) * o.at(k, c);  // row times column
    return out;
  }

  Matrix transposed() const {
    Matrix out(cols_, rows_);
    for (int r = 0; r < rows_; r++)
      for (int c = 0; c < cols_; c++) out.at(c, r) = at(r, c);
    return out;
  }

  void print(const char *name) const {
    std::cout << name << " (" << rows_ << "x" << cols_ << "):\n";
    for (int r = 0; r < rows_; r++) {
      std::cout << "  [";
      for (int c = 0; c < cols_; c++) std::cout << std::setw(7) << std::fixed << std::setprecision(2) << at(r, c);
      std::cout << " ]\n";
    }
  }

private:
  int rows_, cols_;
  std::vector<double> data_;
};

int main() {
  Matrix a(2, 3, {1, 2, 3, 4, 5, 6});
  Matrix b(3, 2, {7, 8, 9, 10, 11, 12});
  a.print("A");
  b.print("B");
  (a * b).print("A x B");
  a.transposed().print("A transposed");
  (a + a).print("A + A");

  // A rotation matrix turns a point around (0,0). Here: 90 degrees.
  double angle = 90 * 3.14159265358979 / 180;
  Matrix rotate(2, 2, {std::cos(angle), -std::sin(angle), std::sin(angle), std::cos(angle)});
  Matrix point(2, 1, {3, 1});
  (rotate * point).print("Point (3,1) turned 90 degrees");

  try {
    (a * a).print("A x A");
  } catch (const std::invalid_argument &e) {
    std::cout << "A x A failed: " << e.what() << "\n";
  }
  return 0;
}

#include <iostream>
#include <queue>
#include <string>
#include <utility>
#include <vector>

int main() {
  std::vector<std::string> maze = {
    "##########",
    "#S   #   #",
    "# ## # # #",
    "#  #   # #",
    "## ##### #",
    "#      # #",
    "# #### #E#",
    "##########",
  };
  const int rows = static_cast<int>(maze.size()), cols = static_cast<int>(maze[0].size());

  std::pair<int, int> start{}, end{};
  for (int r = 0; r < rows; r++)
    for (int c = 0; c < cols; c++) {
      if (maze[r][c] == 'S') start = {r, c};
      if (maze[r][c] == 'E') end = {r, c};
    }

  // came[r][c] remembers which square we came from, so we can trace the path back.
  std::vector<std::vector<std::pair<int, int>>> came(rows, std::vector<std::pair<int, int>>(cols, {-1, -1}));
  std::queue<std::pair<int, int>> frontier;
  frontier.push(start);
  came[start.first][start.second] = start;

  const int dr[4] = {-1, 1, 0, 0}, dc[4] = {0, 0, -1, 1};
  // BFS explores in rings: all squares 1 step away, then 2 steps, then 3...
  while (!frontier.empty()) {
    auto [r, c] = frontier.front();
    frontier.pop();
    if (std::make_pair(r, c) == end) break;
    for (int d = 0; d < 4; d++) {
      int nr = r + dr[d], nc = c + dc[d];
      if (maze[nr][nc] == '#' || came[nr][nc].first != -1) continue;  // wall or already seen
      came[nr][nc] = {r, c};
      frontier.push({nr, nc});
    }
  }

  if (came[end.first][end.second].first == -1) {
    std::cout << "No way out!\n";
    return 0;
  }

  // Walk back from the end to the start, marking the path.
  int steps = 0;
  for (auto p = came[end.first][end.second]; p != start; p = came[p.first][p.second]) {
    maze[p.first][p.second] = '.';
    steps++;
  }
  for (const auto &row : maze) std::cout << row << "\n";
  std::cout << "Shortest path: " << steps + 1 << " steps\n";
  return 0;
}

#include <iostream>
