void print(const std::vector<int> &v, std::size_t from, std::size_t to) {
  std::cout << "[";
  for (std::size_t i = from; i < to; i++) std::cout << (i > from ? " " : "") << v[i];
  std::cout << "]";
}

// Sorts v[from..to) (from is included, to is not).
void mergeSort(std::vector<int> &v, std::size_t from, std::size_t to, int depth) {
  if (to - from <= 1) return;  // one number is already sorted
  std::size_t mid = from + (to - from) / 2;
  mergeSort(v, from, mid, depth + 1);  // sort the left half
  mergeSort(v, mid, to, depth + 1);    // sort the right half

  // Merge: keep taking the smaller front item of the two halves.
  std::vector<int> merged;
  std::size_t i = from, j = mid;
  while (i < mid && j < to) merged.push_back(v[i] <= v[j] ? v[i++] : v[j++]);
  while (i < mid) merged.push_back(v[i++]);
  while (j < to) merged.push_back(v[j++]);

  std::cout << std::string(depth * 2, ' ') << "merge ";
  print(v, from, mid);
  std::cout << " + ";
  print(v, mid, to);
  for (std::size_t k = 0; k < merged.size(); k++) v[from + k] = merged[k];
  std::cout << " -> ";
  print(v, from, to);
  std::cout << "\n";
}

int main() {
  std::vector<int> nums = {38, 27, 43, 3, 9, 82, 10, 15};
  std::cout << "Start: ";
  print(nums, 0, nums.size());
  std::cout << "\n\n";
  mergeSort(nums, 0, nums.size(), 0);
  std::cout << "\nSorted: ";
  print(nums, 0, nums.size());
  std::cout << "\n";
  return 0;
}

#include <iostream>
#include <stdexcept>
#include <utility>
#include <vector>

class MinHeap {
public:
  void push(int v) {
    data_.push_back(v);
    siftUp(data_.size() - 1);  // bubble the new number up to its place
  }

  int pop() {
    if (data_.empty()) throw std::runtime_error("heap is empty");
    int smallest = data_[0];
    data_[0] = data_.back();  // move the last number to the top...
    data_.pop_back();
    if (!data_.empty()) siftDown(0);  // ...and sink it down to its place
    return smallest;
  }

  bool empty() const { return data_.empty(); }
  const std::vector<int> &raw() const { return data_; }

private:
  // In an array heap: children of i are 2i+1 and 2i+2, parent of i is (i-1)/2.
  std::vector<int> data_;

  void siftUp(std::size_t i) {
    while (i > 0) {
      std::size_t parent = (i - 1) / 2;
      if (data_[parent] <= data_[i]) break;
      std::swap(data_[parent], data_[i]);
      i = parent;
    }
  }

  void siftDown(std::size_t i) {
    while (true) {
      std::size_t left = 2 * i + 1, right = 2 * i + 2, smallest = i;
      if (left < data_.size() && data_[left] < data_[smallest]) smallest = left;
      if (right < data_.size() && data_[right] < data_[smallest]) smallest = right;
      if (smallest == i) break;
      std::swap(data_[i], data_[smallest]);
      i = smallest;
    }
  }
};

int main() {
  MinHeap heap;
  for (int v : {42, 7, 19, 3, 88, 25, 1, 60}) {
    heap.push(v);
    std::cout << "push " << v << " -> array:";
    for (int x : heap.raw()) std::cout << " " << x;
    std::cout << "\n";
  }

  // Popping gives the numbers smallest first. That's "heapsort"!
  std::cout << "\nPopping:";
  while (!heap.empty()) std::cout << " " << heap.pop();
  std::cout << "\n";
  return 0;
}

