void draw(const std::vector<std::string> &pic) {
  std::cout << "   0123456789012345\n";
  for (std::size_t r = 0; r < pic.size(); r++) std::cout << (r < 10 ? " " : "") << r << " " << pic[r] << "\n";
}

// Uses our own stack instead of recursion, so huge areas can't overflow the call stack.
int fill(std::vector<std::string> &pic, int row, int col, char paint) {
  char old = pic[row][col];
  if (old == paint) return 0;
  int painted = 0;
  std::stack<std::pair<int, int>> todo;
  todo.push({row, col});
  while (!todo.empty()) {
    auto [r, c] = todo.top();
    todo.pop();
    if (r < 0 || c < 0 || r >= static_cast<int>(pic.size()) || c >= static_cast<int>(pic[r].size())) continue;
    if (pic[r][c] != old) continue;
    pic[r][c] = paint;
    painted++;
    todo.push({r + 1, c});
    todo.push({r - 1, c});
    todo.push({r, c + 1});
    todo.push({r, c - 1});
  }
  return painted;
}

int main() {
  std::vector<std::string> pic = {
    "................",
    "...######.......",
    "...#....#..###..",
    "...#....#..#.#..",
    "...######..###..",
    "................",
    "..#########.....",
    "..#.......#.....",
    "..#########.....",
  };
  const std::string paints = "*o+@%";
  int nextPaint = 0;

  draw(pic);
  std::cout << "Type: row column (Ctrl+D to stop)\n";
  int r, c;
  while (std::cin >> r >> c) {
    if (r < 0 || c < 0 || r >= static_cast<int>(pic.size()) || c >= static_cast<int>(pic[0].size())) {
      std::cout << "That's off the picture.\n";
      continue;
    }
    char paint = paints[nextPaint++ % paints.size()];
    int n = fill(pic, r, c, paint);
    std::cout << "Painted " << n << " squares with '" << paint << "'\n";
    draw(pic);
  }
  return 0;
}

#include <iostream>
#include <stack>
#include <stdexcept>

class TwoStackQueue {
public:
  void push(int v) { inbox_.push(v); }

  int pop() {
    if (outbox_.empty()) {
      // Pour the inbox into the outbox. That flips the order, so the oldest is on top!
      while (!inbox_.empty()) {
        outbox_.push(inbox_.top());
        inbox_.pop();
      }
    }
    if (outbox_.empty()) throw std::runtime_error("queue is empty");
    int v = outbox_.top();
    outbox_.pop();
    return v;
  }

  bool empty() const { return inbox_.empty() && outbox_.empty(); }
  std::size_t inboxSize() const { return inbox_.size(); }
  std::size_t outboxSize() const { return outbox_.size(); }

private:
  std::stack<int> inbox_, outbox_;
};

int main() {
  TwoStackQueue q;
  for (int i = 1; i <= 4; i++) q.push(i);
  std::cout << "Pushed 1 2 3 4. inbox=" << q.inboxSize() << " outbox=" << q.outboxSize() << "\n";

  std::cout << "pop -> " << q.pop() << "  (inbox=" << q.inboxSize() << " outbox=" << q.outboxSize() << ")\n";
  q.push(5);
  q.push(6);
  std::cout << "Pushed 5 6.\n";
  std::cout << "Popping the rest:";
  while (!q.empty()) std::cout << " " << q.pop();
  std::cout << "\nSame order they went in: first in, first out!\n";
  return 0;
}

