int steps = 0;

void print(const std::vector<int> &v) {
  for (int x : v) std::cout << x << " ";
  std::cout << "\n";
}

// Lomuto partition: uses the last number as the pivot and returns where the pivot ends up.
int partition(std::vector<int> &v, int low, int high) {
  int pivot = v[high];
  int wall = low;  // everything left of the wall is smaller than the pivot
  for (int i = low; i < high; i++) {
    if (v[i] < pivot) std::swap(v[i], v[wall++]);
  }
  std::swap(v[wall], v[high]);  // put the pivot right after the small numbers
  return wall;
}

void quickSort(std::vector<int> &v, int low, int high) {
  if (low >= high) return;
  int p = partition(v, low, high);
  std::cout << "Step " << ++steps << ", pivot " << v[p] << ": ";
  print(v);
  quickSort(v, low, p - 1);   // sort the small side
  quickSort(v, p + 1, high);  // sort the big side
}

int main() {
  std::vector<int> nums = {10, 80, 30, 90, 40, 50, 70, 25, 5};
  std::cout << "Start:              ";
  print(nums);
  quickSort(nums, 0, static_cast<int>(nums.size()) - 1);
  std::cout << "Sorted:             ";
  print(nums);
  std::cout << "Quick sort is usually very fast, which is why std::sort uses a version of it.\n";
  return 0;
}

#include <cmath>
#include <iostream>
#include <sstream>
#include <stack>
#include <string>

// Returns true and sets result if the line is a valid RPN expression.
bool evaluate(const std::string &line, double &result, std::string &error) {
  std::stack<double> st;
  std::istringstream in(line);
  std::string token;
  while (in >> token) {
    if (token == "+" || token == "-" || token == "*" || token == "/" || token == "^") {
      if (st.size() < 2) { error = "not enough numbers for " + token; return false; }
      double b = st.top(); st.pop();  // careful: the top is the SECOND number
      double a = st.top(); st.pop();
      if (token == "+") st.push(a + b);
      else if (token == "-") st.push(a - b);
      else if (token == "*") st.push(a * b);
      else if (token == "^") st.push(std::pow(a, b));
      else {
        if (b == 0) { error = "can't divide by zero"; return false; }
        st.push(a / b);
      }
    } else {
      try {
        std::size_t used = 0;
        double v = std::stod(token, &used);
        if (used != token.size()) throw std::invalid_argument("junk");
        st.push(v);
      } catch (const std::exception &) {
        error = "\"" + token + "\" is not a number or a sign";
        return false;
      }
    }
  }
  if (st.size() != 1) { error = "should end with exactly one number"; return false; }
  result = st.top();
  return true;
}

int main() {
  std::cout << "RPN calculator. Examples:\n  3 4 +        (means 3 + 4)\n  5 1 2 + 4 * + 3 -   (means 5 + (1 + 2) * 4 - 3)\n"
            << "Type an expression (Ctrl+D to quit):\n";
  std::string line;
  while (std::cout << "> " && std::getline(std::cin, line)) {
    if (line.empty()) continue;
    double result;
    std::string error;
    if (evaluate(line, result, error)) std::cout << "= " << result << "\n";
    else std::cout << "Error: " << error << "\n";
  }
  std::cout << "\n";
  return 0;
}

