int main() {
  // A set throws away duplicates and keeps everything sorted.
  std::vector<int> rolls = {4, 2, 6, 2, 4, 4, 1, 6, 3};
  std::set<int> different(rolls.begin(), rolls.end());
  std::cout << "Dice rolls had " << rolls.size() << " numbers but only " << different.size() << " different ones:";
  for (int r : different) std::cout << " " << r;
  std::cout << "\n\n";

  std::set<std::string> mine = {"Minecraft", "Roblox", "Terraria", "Rocket League", "Fortnite"};
  std::set<std::string> yours = {"Fortnite", "Minecraft", "Among Us", "Fall Guys"};
  print("My games", mine);
  print("Your games", yours);

  std::set<std::string> both, either, onlyMine;
  // Games we both have.
  std::set_intersection(mine.begin(), mine.end(), yours.begin(), yours.end(), std::inserter(both, both.begin()));
  // Every game either of us has.
  std::set_union(mine.begin(), mine.end(), yours.begin(), yours.end(), std::inserter(either, either.begin()));
  // Games only I have.
  std::set_difference(mine.begin(), mine.end(), yours.begin(), yours.end(), std::inserter(onlyMine, onlyMine.begin()));

  print("We both have", both);
  print("Between us we have", either);
  print("Only I have", onlyMine);

  // insert tells you whether the item was new.
  auto result = mine.insert("Roblox");
  std::cout << "\nAdding Roblox again: " << (result.second ? "added" : "already there") << "\n";
  std::cout << "Do I have Terraria? " << (mine.count("Terraria") ? "yes" : "no") << "\n";
  return 0;
}

#include <climits>
#include <functional>
#include <iostream>
#include <queue>
#include <string>
#include <utility>
#include <vector>

int main() {
  std::vector<std::string> towns = {"Home", "School", "Park", "Mall", "Library", "Beach"};
  // Roads: each town has a list of (neighbor, minutes). This is an "adjacency list".
  std::vector<std::vector<std::pair<int, int>>> roads(towns.size());
  auto road = [&roads](int a, int b, int minutes) {
    roads[a].push_back({b, minutes});
    roads[b].push_back({a, minutes});  // two-way road
  };
  road(0, 1, 7); road(0, 2, 9); road(0, 5, 14); road(1, 2, 10);
  road(1, 3, 15); road(2, 3, 11); road(2, 5, 2); road(3, 4, 6); road(4, 5, 9);

  std::cout << "Towns:";
  for (std::size_t i = 0; i < towns.size(); i++) std::cout << " " << i << "=" << towns[i];
  std::cout << "\nFrom which town number? ";
  int from = 0;
  if (!(std::cin >> from) || from < 0 || from >= static_cast<int>(towns.size())) from = 0;

  std::vector<int> best(towns.size(), INT_MAX), cameFrom(towns.size(), -1);
  // A min priority queue of (minutes so far, town): always explore the closest town next.
  std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<>> next;
  best[from] = 0;
  next.push({0, from});
  while (!next.empty()) {
    auto [time, town] = next.top();
    next.pop();
    if (time > best[town]) continue;  // an old, slower entry: skip it
    for (auto [neighbor, minutes] : roads[town]) {
      if (time + minutes < best[neighbor]) {  // found a faster way!
        best[neighbor] = time + minutes;
        cameFrom[neighbor] = town;
        next.push({best[neighbor], neighbor});
      }
    }
  }

  std::cout << "\nFastest routes from " << towns[from] << ":\n";
  for (std::size_t t = 0; t < towns.size(); t++) {
    std::string route = towns[t];
    for (int at = cameFrom[t]; at != -1; at = cameFrom[at]) route = towns[at] + " > " + route;
    std::cout << "  " << towns[t] << ": " << best[t] << " min  (" << route << ")\n";
  }
  return 0;
}

#include <iostream>
#include <string>

// Each Node holds one value and a pointer to the next node.
struct Node {
  std::string value;
  Node *next;
};

class LinkedList {
public:
  ~LinkedList() {  // delete every node so no memory leaks
    while (head_) {
      Node *old = head_;
      head_ = head_->next;
      delete old;
    }
  }
  LinkedList() = default;
  LinkedList(const LinkedList &) = delete;             // copying would delete nodes twice,
  LinkedList &operator=(const LinkedList &) = delete;  // so we turn it off

  void pushFront(const std::string &v) { head_ = new Node{v, head_}; size_++; }

  void pushBack(const std::string &v) {
    Node *n = new Node{v, nullptr};
    if (!head_) { head_ = n; }
    else {
      Node *cur = head_;
      while (cur->next) cur = cur->next;  // walk to the last node
      cur->next = n;
    }
    size_++;
  }

  bool remove(const std::string &v) {
    Node **link = &head_;  // the pointer that points at the current node
    while (*link) {
      if ((*link)->value == v) {
        Node *doomed = *link;
        *link = doomed->next;  // skip over it
        delete doomed;
        size_--;
        return true;
      }
      link = &(*link)->next;
    }
    return false;
  }

  bool contains(const std::string &v) const {
    for (Node *cur = head_; cur; cur = cur->next) if (cur->value == v) return true;
    return false;
  }

  void reverse() {
    Node *prev = nullptr, *cur = head_;
    while (cur) {
      Node *next = cur->next;
      cur->next = prev;  // flip the arrow
      prev = cur;
      cur = next;
    }
    head_ = prev;
  }

  void print() const {
    std::cout << "[engine]";
    for (Node *cur = head_; cur; cur = cur->next) std::cout << "->[" << cur->value << "]";
    std::cout << "  (" << size_ << " cars)\n";
  }

private:
  Node *head_ = nullptr;
  int size_ = 0;
};

int main() {
  LinkedList train;
  train.pushBack("coal");
  train.pushBack("passengers");
  train.pushBack("mail");
  train.pushFront("dining");
  train.print();

  std::cout << "Has mail car? " << (train.contains("mail") ? "yes" : "no") << "\n";
  train.remove("passengers");
  std::cout << "After removing passengers: ";
  train.print();

  train.reverse();
  std::cout << "Reversed: ";
  train.print();
  return 0;
}

#include <algorithm>
#include <iomanip>
#include <iostream>
#include <string>
#include <tuple>
#include <vector>

struct Player {
  std::string name;
  int points;
  int deaths;
};

void print(const std::vector<Player> &players) {
  int rank = 1;
  for (const auto &p : players) {
    std::cout << "  " << rank++ << ". " << std::left << std::setw(8) << p.name << std::right << std::setw(5)
              << p.points << " pts " << std::setw(3) << p.deaths << " deaths\n";
  }
}

int main() {
  std::vector<Player> players = {
    {"Nova", 1500, 4}, {"Ace", 1800, 7}, {"Zed", 1500, 2}, {"Blaze", 1800, 7}, {"Kit", 900, 0}, {"Moss", 1500, 4},
  };

  // Rule: more points first. Tie? Fewer deaths first. Still tied? Alphabetical.
  std::sort(players.begin(), players.end(), [](const Player &a, const Player &b) {
    if (a.points != b.points) return a.points > b.points;
    if (a.deaths != b.deaths) return a.deaths < b.deaths;
    return a.name < b.name;
  });
  std::cout << "Leaderboard:\n";
  print(players);

  // std::tie compares several fields at once, in order: deaths first, then name.
  std::sort(players.begin(), players.end(), [](const Player &a, const Player &b) {
    return std::tie(a.deaths, a.name) < std::tie(b.deaths, b.name);
  });
  std::cout << "\nSafest players (fewest deaths):\n";
  print(players);

  // stable_sort keeps players with equal points in their current order.
  std::stable_sort(players.begin(), players.end(), [](const Player &a, const Player &b) { return a.points > b.points; });
  std::cout << "\nBy points, ties stay in 'safest' order (stable_sort):\n";
  print(players);
  return 0;
}

#include <bitset>
