#include <deque>
#include <iostream>
#include <vector>

int main() {
  std::vector<int> readings = {12, 15, 11, 30, 28, 9, 14, 40, 13, 12, 11, 18};
  const std::size_t WINDOW = 5;

  std::deque<int> window;       // the last 5 readings
  std::deque<std::size_t> maxQ; // positions that could still be the biggest, biggest at the front
  int sum = 0;

  for (std::size_t i = 0; i < readings.size(); i++) {
    int r = readings[i];

    // Add the new reading at the back, drop the oldest from the front.
    window.push_back(r);
    sum += r;
    if (window.size() > WINDOW) {
      sum -= window.front();
      window.pop_front();
    }

    // Rolling max trick: smaller readings behind a new big one can never be the max again.
    while (!maxQ.empty() && readings[maxQ.back()] <= r) maxQ.pop_back();
    maxQ.push_back(i);
    if (maxQ.front() + WINDOW <= i) maxQ.pop_front();  // too old, out of the window

    std::cout << "reading " << r << "\twindow [";
    for (std::size_t k = 0; k < window.size(); k++) std::cout << (k ? " " : "") << window[k];
    std::cout << "]\tavg " << static_cast<double>(sum) / window.size() << "\tmax " << readings[maxQ.front()] << "\n";
  }

  // A deque can grow at BOTH ends.
  std::deque<char> word = {'o', 'b', 'o'};
  word.push_front('r');
  word.push_back('t');
  std::cout << "\nBuilt from both ends: ";
  for (char c : word) std::cout << c;
  std::cout << "\n";
  return 0;
}

#include <algorithm>
#include <iostream>
#include <iterator>
#include <list>
#include <string>

void show(const std::list<std::string> &race) {
  int place = 1;
  for (const auto &car : race) std::cout << "  " << place++ << ". " << car << "\n";
}

int main() {
  std::list<std::string> race = {"Red", "Blue", "Green", "Yellow", "Purple"};
  std::cout << "Starting order:\n";
  show(race);

  // Green overtakes Blue: find Green, take it out, put it before Blue.
  auto blue = std::find(race.begin(), race.end(), "Blue");
  auto green = std::find(race.begin(), race.end(), "Green");
  race.splice(blue, race, green);  // moves the node, no copying
  std::cout << "\nGreen overtakes Blue:\n";
  show(race);

  // A new car joins in 3rd place.
  auto third = std::next(race.begin(), 2);
  race.insert(third, "Orange");
  std::cout << "\nOrange joins in 3rd:\n";
  show(race);

  // Erase while looping: erase() gives back the next position, so use that.
  for (auto it = race.begin(); it != race.end();) {
    if (*it == "Yellow" || *it == "Red") {
      std::cout << "\n" << *it << " crashed out!";
      it = race.erase(it);
    } else {
      ++it;
    }
  }
  std::cout << "\n\nFinal order:\n";
  show(race);
  return 0;
}

#include <iostream>
#include <queue>
#include <random>
#include <string>

struct Person {
  std::string name;
  int arrivedAt;
};

int main() {
  const std::string NAMES[] = {"Ava", "Ben", "Cai", "Dee", "Eli", "Fay", "Gus", "Hana", "Ivo", "Jun"};
  std::mt19937 rng(7);
  std::uniform_int_distribution<int> coin(0, 2);

  std::queue<Person> line;
  int nextName = 0;
  int served = 0;
  int totalWait = 0;

  for (int minute = 1; minute <= 12; minute++) {
    // Sometimes 0, 1 or 2 people arrive.
    int arrivals = coin(rng);
    for (int a = 0; a < arrivals && nextName < 10; a++) {
      line.push({NAMES[nextName++], minute});  // join at the BACK
      std::cout << "Minute " << minute << ": " << line.back().name << " joins the line\n";
    }

    // The ticket booth serves one person per minute, from the FRONT.
    if (!line.empty()) {
      Person p = line.front();
      line.pop();
      int waited = minute - p.arrivedAt;
      totalWait += waited;
      served++;
      std::cout << "Minute " << minute << ": served " << p.name << " (waited " << waited << " min)\n";
    }
    std::cout << "           people waiting: " << line.size() << "\n";
  }

  std::cout << "\nServed " << served << " people";
  if (served > 0) std::cout << ", average wait " << static_cast<double>(totalWait) / served << " min";
  std::cout << ". Still in line: " << line.size() << "\n";
  return 0;
}

#include <fstream>
#include <iostream>
#include <string>
#include <vector>

struct Task {
  bool done;
  std::string text;
};

const std::string FILE_NAME = "todo.txt";

std::vector<Task> load() {
  std::vector<Task> tasks;
  std::ifstream in(FILE_NAME);
  std::string line;
  while (std::getline(in, line)) {
    if (line.size() < 2) continue;
    tasks.push_back({line[0] == 'x', line.substr(2)});  // saved as "x text" or "- text"
  }
  return tasks;
}

void save(const std::vector<Task> &tasks) {
  std::ofstream out(FILE_NAME);
  for (const auto &t : tasks) out << (t.done ? 'x' : '-') << ' ' << t.text << '\n';
}

void list(const std::vector<Task> &tasks) {
  if (tasks.empty()) std::cout << "  (nothing to do!)\n";
  for (std::size_t i = 0; i < tasks.size(); i++) {
    std::cout << "  " << i + 1 << ". [" << (tasks[i].done ? 'x' : ' ') << "] " << tasks[i].text << "\n";
  }
}

int main() {
  std::vector<Task> tasks = load();
  std::cout << "Commands: add TEXT, done N, del N, clear (removes done ones), list, quit\n";
  list(tasks);

  std::string cmd;
  while (std::cout << "> " && std::cin >> cmd && cmd != "quit") {
    if (cmd == "add") {
      std::string text;
      std::getline(std::cin, text);
      if (!text.empty() && text[0] == ' ') text.erase(0, 1);
      if (text.empty()) { std::cout << "Add what?\n"; continue; }
      tasks.push_back({false, text});
    } else if (cmd == "done" || cmd == "del") {
      std::size_t n = 0;
      if (!(std::cin >> n) || n < 1 || n > tasks.size()) {
        std::cin.clear();
        std::cin.ignore(1000, '\n');
        std::cout << "No task with that number.\n";
        continue;
      }
      if (cmd == "done") tasks[n - 1].done = true;
      else tasks.erase(tasks.begin() + static_cast<long>(n - 1));
    } else if (cmd == "clear") {
      std::vector<Task> left;
      for (const auto &t : tasks) if (!t.done) left.push_back(t);
      tasks = left;
    } else if (cmd != "list") {
      std::cout << "Unknown command\n";
      continue;
    }
    save(tasks);  // save after every change
    list(tasks);
  }
  return 0;
}

#include <algorithm>
#include <iostream>
#include <numeric>
#include <string>
