  int current = deck.back();
  deck.pop_back();
  std::cout << "Higher or Lower! Aces are high. Ties count as a loss.\n";

  while (!deck.empty()) {
    // Count how many higher and lower cards are left, so you can play smart.
    int higher = 0, lower = 0;
    for (int v : deck) { if (v > current) higher++; else if (v < current) lower++; }
    std::cout << "\nCard: " << cardName(current) << "   (cards left: " << higher << " higher, " << lower << " lower)\n";
    std::cout << "Streak " << streak << ". (h)igher or (l)ower? ";
    char guess;
    if (!(std::cin >> guess)) break;
    if (guess != 'h' && guess != 'l') { std::cout << "Type h or l.\n"; continue; }

    int next = deck.back();
    deck.pop_back();
    bool right = (guess == 'h' && next > current) || (guess == 'l' && next < current);
    std::cout << "Next card: " << cardName(next) << " ... " << (right ? "Correct!" : "Wrong!") << "\n";
    if (right) {
      streak++;
      best = std::max(best, streak);
    } else {
      streak = 0;
    }
    current = next;
  }
  std::cout << "\nBest streak: " << best << ". " << (deck.empty() ? "You went through the whole deck!" : "Thanks for playing!") << "\n";
  return 0;
}

#include <iostream>
#include <vector>

int main() {
  const int W = 80, H = 52;
  std::vector<std::vector<bool>> black(H, std::vector<bool>(W, false));
  int x = 49, y = 25, dir = 0;  // 0 up, 1 right, 2 down, 3 left
  const int dx[] = {0, 1, 0, -1}, dy[] = {-1, 0, 1, 0};

  long steps = 11500;
  std::cout << "How many steps (try 500, 5000 or 11500)? ";
  long typed;
  if (std::cin >> typed && typed >= 0 && typed <= 100000) steps = typed;

  long done = 0;
  for (; done < steps; done++) {
    // Rule 1: on a white square, turn right. Rule 2: on a black square, turn left.
    dir = black[y][x] ? (dir + 3) % 4 : (dir + 1) % 4;
    black[y][x] = !black[y][x];  // flip the color of the square
    x += dx[dir];
    y += dy[dir];
    if (x < 0 || x >= W || y < 0 || y >= H) { std::cout << "The ant walked off the edge!\n"; break; }
  }

  for (int r = 0; r < H; r++) {
    for (int c = 0; c < W; c++) std::cout << (r == y && c == x ? 'A' : black[r][c] ? '#' : ' ');
    std::cout << "\n";
  }
  std::cout << "After " << done << " steps. Around step 10000 the ant starts building a diagonal 'highway'.\n";
  return 0;
}

#include <algorithm>
#include <iomanip>
#include <iostream>
#include <random>

int main() {
  std::mt19937 rng(std::random_device{}());
  double money = 10.00;
  const double cupCost = 0.20;
  const char *weather[] = {"Rainy", "Cloudy", "Sunny", "Hot!"};
  const int baseCustomers[] = {8, 20, 40, 70};

  std::cout << std::fixed << std::setprecision(2);
  std::cout << "You start with $10. Each cup of lemonade costs you $0.20 to make.\n";
  for (int day = 1; day <= 7; day++) {
    int w = std::uniform_int_distribution<int>(0, 3)(rng);
    std::cout << "\n=== Day " << day << " ===  Money: $" << money << "   Weather: " << weather[w] << "\n";
    std::cout << "How many cups will you make? ";
    int cups;
    if (!(std::cin >> cups)) break;
    cups = std::max(0, std::min(cups, static_cast<int>(money / cupCost)));
    std::cout << "Price per cup in dollars (like 0.50)? ";
    double price;
    if (!(std::cin >> price)) break;
    price = std::max(0.05, std::min(price, 5.0));

    // Higher prices scare customers away. Good weather brings more people.
    double interest = std::max(0.0, 1.5 - price * 1.5);
    int customers = static_cast<int>(baseCustomers[w] * interest);
    int sold = std::min(cups, customers);
    double cost = cups * cupCost, income = sold * price;
    money += income - cost;

    std::cout << customers << " people wanted lemonade. You sold " << sold << " of " << cups << " cups.\n";
    std::cout << "Income $" << income << " - cost $" << cost << " = " << (income >= cost ? "profit $" : "loss $")
              << std::abs(income - cost) << "\n";
  }
  std::cout << "\nYou end the week with $" << money << ". " << (money > 10 ? "Nice business!" : "Try a different price next time.") << "\n";
  return 0;
}

