}

#include <array>
#include <iostream>
#include <sstream>
#include <string>

// The board: squares 1-9 start as their number.
std::array<char, 9> board = {'1', '2', '3', '4', '5', '6', '7', '8', '9'};

void drawBoard() {
  std::cout << "\n";
  for (int row = 0; row < 3; row++) {
    std::cout << " " << board[row * 3] << " | " << board[row * 3 + 1] << " | "
              << board[row * 3 + 2] << "\n";
    if (row < 2) std::cout << "---+---+---\n";
  }
  std::cout << "\n";
}

// Check every row, column and diagonal for three in a row.
bool hasWon(char player) {
  const int lines[8][3] = {{0, 1, 2}, {3, 4, 5}, {6, 7, 8},   // rows
                           {0, 3, 6}, {1, 4, 7}, {2, 5, 8},   // columns
                           {0, 4, 8}, {2, 4, 6}};             // diagonals
  for (const auto &line : lines) {
    if (board[line[0]] == player && board[line[1]] == player &&
        board[line[2]] == player) {
      return true;
    }
  }
  return false;
}

// Ask for a square number 1-9 that isn't taken yet.
// Returns -1 if the input is closed.
int askForSquare(char player) {
  std::string line;
  while (true) {
    std::cout << "Player " << player << ", pick a square (1-9): ";
    if (!std::getline(std::cin, line)) return -1;
    std::istringstream in(line);
    int square = 0;
    char extra;
    if (!(in >> square) || (in >> extra)) {
      std::cout << "Please type a number.\n";
    } else if (square < 1 || square > 9) {
      std::cout << "That square doesn't exist. Use 1 to 9.\n";
    } else if (board[square - 1] == 'X' || board[square - 1] == 'O') {
      std::cout << "That square is taken!\n";
    } else {
      return square - 1;
    }
  }
}

int main() {
  std::cout << "Tic-Tac-Toe! X goes first.\n";
  char player = 'X';

  for (int turn = 0; turn < 9; turn++) {
    drawBoard();
    int square = askForSquare(player);
    if (square < 0) return 0;
    board[square] = player;

    if (hasWon(player)) {
      drawBoard();
      std::cout << "Player " << player << " wins!\n";
      return 0;
    }
    player = (player == 'X') ? 'O' : 'X';  // swap turns
  }

  drawBoard();
  std::cout << "It's a draw!\n";
  return 0;
}

#include <cmath>
#include <iostream>
#include <random>

int main() {
  std::mt19937 rng(std::random_device{}());
  std::uniform_int_distribution<int> spot(0, 9);
  int tx = spot(rng), ty = spot(rng);
  char map[10][10];
  for (auto &row : map) for (char &c : row) c = '~';

  std::cout << "Treasure is buried somewhere on the island! Dig by typing x y (0-9 each). 12 digs.\n";
  double lastDist = -1;
  for (int dig = 1; dig <= 12; dig++) {
    std::cout << "\n  0123456789\n";
    for (int y = 0; y < 10; y++) {
      std::cout << y << " ";
      for (int x = 0; x < 10; x++) std::cout << map[y][x];
      std::cout << "\n";
    }
    std::cout << "Dig " << dig << ": ";
    int x, y;
    if (!(std::cin >> x >> y)) break;
    if (x < 0 || x > 9 || y < 0 || y > 9) { std::cout << "That's in the sea!\n"; dig--; continue; }
    if (x == tx && y == ty) { std::cout << "\n*** You found the TREASURE in " << dig << " digs! ***\n"; return 0; }

    map[y][x] = 'x';
    double dist = std::hypot(x - tx, y - ty);  // straight-line distance
    if (dist <= 1.5) std::cout << "BURNING HOT! It's right next to you!\n";
    else if (dist <= 3) std::cout << "Hot!\n";
    else if (dist <= 5) std::cout << "Warm.\n";
    else std::cout << "Cold.\n";
    if (lastDist >= 0) std::cout << (dist < lastDist ? "(warmer than last time)\n" : dist > lastDist ? "(colder than last time)\n" : "(same as last time)\n");
    lastDist = dist;
  }
  std::cout << "\nOut of digs! The treasure was at " << tx << " " << ty << ".\n";
  return 0;
}

#include <algorithm>
#include <iostream>
#include <random>
#include <string>

std::mt19937 rng(std::random_device{}());
int roll(int lo, int hi) { return std::uniform_int_distribution<int>(lo, hi)(rng); }

struct Fighter {
  std::string name;
  int hp, maxHp, attack;
};

int main() {
  Fighter hero{"Hero", 40, 40, 8};
  int mana = 10, potions = 3, level = 1;
  Fighter monsters[] = {{"Slime", 20, 20, 4}, {"Goblin", 30, 30, 6}, {"Robot Knight", 45, 45, 8}, {"DRAGON", 70, 70, 11}};

  for (Fighter &m : monsters) {
    std::cout << "\nA wild " << m.name << " appears! (" << m.hp << " HP)\n";
    while (m.hp > 0 && hero.hp > 0) {
      std::cout << "\n" << hero.name << " HP " << hero.hp << "/" << hero.maxHp << "  Mana " << mana << "  Potions " << potions
                << "   |   " << m.name << " HP " << m.hp << "\n";
      std::cout << "1 Attack  2 Fireball (5 mana)  3 Potion  > ";
      int choice;
      if (!(std::cin >> choice)) { std::cout << "\nYou ran away!\n"; return 0; }

      if (choice == 1) {
        int dmg = roll(hero.attack - 2, hero.attack + 3);
        if (roll(1, 10) == 10) { dmg *= 2; std::cout << "CRITICAL HIT! "; }
        m.hp -= dmg;
        std::cout << "You hit the " << m.name << " for " << dmg << ".\n";
      } else if (choice == 2 && mana >= 5) {
        int dmg = roll(12, 18);
        mana -= 5;
        m.hp -= dmg;
        std::cout << "FIREBALL! " << dmg << " damage.\n";
      } else if (choice == 3 && potions > 0) {
        potions--;
        hero.hp = std::min(hero.maxHp, hero.hp + 20);
        std::cout << "You drink a potion and heal.\n";
      } else {
        std::cout << "You can't do that! You lose your turn.\n";
      }

      if (m.hp > 0) {  // the monster strikes back
        int dmg = roll(m.attack - 2, m.attack + 2);
        if (roll(1, 6) == 1) std::cout << "The " << m.name << " misses!\n";
        else { hero.hp -= dmg; std::cout << "The " << m.name << " hits you for " << dmg << ".\n"; }
      }
    }
    if (hero.hp <= 0) { std::cout << "\nYou were defeated by the " << m.name << ". GAME OVER\n"; return 0; }

    level++;
    hero.maxHp += 10;
    hero.attack += 2;
    hero.hp = std::min(hero.maxHp, hero.hp + 15);
    mana += 5;
    std::cout << "You beat the " << m.name << "! LEVEL UP to " << level << ". Max HP " << hero.maxHp << ", attack " << hero.attack << ".\n";
  }
  std::cout << "\nYou defeated the DRAGON and saved the kingdom! YOU WIN!\n";
  return 0;
}

#include <algorithm>
#include <chrono>
#include <iostream>
#include <random>
#include <string>
#include <vector>

int main() {
  std::vector<std::string> sentences = {
    "the quick brown fox jumps over the lazy dog",
    "my robot can drive around the room and avoid walls",
    "arduino boards read sensors and control motors",
    "practice every day and your typing will get faster",
  };
  std::mt19937 rng(std::random_device{}());
  std::shuffle(sentences.begin(), sentences.end(), rng);

  for (int round = 0; round < 3; round++) {
    const std::string &target = sentences[round];
    std::cout << "\nType this, then press Enter:\n  " << target << "\n> ";
    auto start = std::chrono::steady_clock::now();
    std::string typed;
    if (!std::getline(std::cin, typed)) break;
    double seconds = std::chrono::duration<double>(std::chrono::steady_clock::now() - start).count();
    if (seconds < 0.5) seconds = 0.5;

    // Accuracy: compare letter by letter.
    size_t same = 0;
    for (size_t i = 0; i < std::min(typed.size(), target.size()); i++) if (typed[i] == target[i]) same++;
    double accuracy = 100.0 * same / std::max(typed.size(), target.size());

    // Typists count every 5 characters as one "word".
    double wpm = (typed.size() / 5.0) / (seconds / 60.0);
    std::cout << "Time: " << seconds << " s   Speed: " << static_cast<int>(wpm) << " words per minute   Accuracy: "
              << static_cast<int>(accuracy) << "%\n";
    if (typed == target) std::cout << "Perfect match!\n";
  }
  std::cout << "\nTip: keep your fingers on the home row (asdf jkl;) and don't look at the keys!\n";
  return 0;
}

#include <iostream>

char b[9] = {'1', '2', '3', '4', '5', '6', '7', '8', '9'};

char winner() {
  const int lines[8][3] = {{0, 1, 2}, {3, 4, 5}, {6, 7, 8}, {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, {0, 4, 8}, {2, 4, 6}};
  for (auto &l : lines)
    if (b[l[0]] == b[l[1]] && b[l[1]] == b[l[2]]) return b[l[0]];
  for (char c : b) if (c != 'X' && c != 'O') return 0;  // game not over yet
  return 'T';  // tie
}

// Score a position from O's point of view: +10 O wins, -10 X wins, 0 tie.
// O picks the highest score, X (you) is assumed to pick the lowest.
int minimax(bool oTurn, int depth) {
  char w = winner();
  if (w == 'O') return 10 - depth;  // win sooner = better
  if (w == 'X') return depth - 10;
  if (w == 'T') return 0;
  int best = oTurn ? -100 : 100;
  for (int i = 0; i < 9; i++) {
    if (b[i] == 'X' || b[i] == 'O') continue;
    char saved = b[i];
    b[i] = oTurn ? 'O' : 'X';  // try the move
    int s = minimax(!oTurn, depth + 1);
    b[i] = saved;              // undo it
    best = oTurn ? std::max(best, s) : std::min(best, s);
  }
  return best;
}

void draw() {
  for (int r = 0; r < 3; r++) {
    std::cout << " " << b[r * 3] << " | " << b[r * 3 + 1] << " | " << b[r * 3 + 2] << "\n";
    if (r < 2) std::cout << "---+---+---\n";
  }
}

int main() {
  std::cout << "You are X. Try to beat me... you can't!\n";
  while (!winner()) {
    draw();
    std::cout << "Your square (1-9): ";
    int sq;
    if (!(std::cin >> sq)) { std::cout << "\nBye!\n"; return 0; }
    if (sq < 1 || sq > 9 || b[sq - 1] == 'X' || b[sq - 1] == 'O') { std::cout << "Pick an empty square.\n"; continue; }
    b[sq - 1] = 'X';
    if (winner()) break;

    int bestMove = -1, bestScore = -100;
    for (int i = 0; i < 9; i++) {
      if (b[i] == 'X' || b[i] == 'O') continue;
      char saved = b[i];
      b[i] = 'O';
      int s = minimax(false, 1);
      b[i] = saved;
      if (s > bestScore) { bestScore = s; bestMove = i; }
    }
    b[bestMove] = 'O';
    std::cout << "I play " << bestMove + 1 << "\n";
  }
  draw();
  char w = winner();
  std::cout << (w == 'T' ? "A tie! That's the best anyone can do." : w == 'O' ? "I win!" : "You won?! That shouldn't happen!") << "\n";
  return 0;
}

#include <algorithm>
#include <iostream>
#include <string>

class RobotPet {
public:
  explicit RobotPet(std::string name) : name_(std::move(name)) {}

  void charge() { battery_ = std::min(100, battery_ + 30); fun_ -= 5; say("Bzzzt... battery recharging!"); }
  void play() { fun_ = std::min(100, fun_ + 25); battery_ -= 15; rust_ += 5; say("Wheee! Beep boop!"); }
  void oil() { rust_ = std::max(0, rust_ - 30); say("Ahh, squeaky clean gears."); }

  // Time passes: everything slowly gets worse.
  void tick() {
    battery_ -= 8;
    fun_ -= 6;
    rust_ += 4;
  }

  bool ok() const { return battery_ > 0 && fun_ > 0 && rust_ < 100; }

  void show() const {
    std::cout << "\n" << name_ << " " << face() << "\n";
    bar("Battery", battery_);
    bar("Fun    ", fun_);
    bar("Rust   ", rust_);
  }

private:
  std::string name_;
  int battery_ = 70, fun_ = 70, rust_ = 10;

  std::string face() const {
    if (!ok()) return "[x_x]";
    if (battery_ < 30 || fun_ < 30 || rust_ > 70) return "[o_o;]";
    return "[^_^]";
  }
  void say(const std::string &s) const { std::cout << name_ << ": " << s << "\n"; }
  static void bar(const char *label, int v) {
    int n = std::max(0, std::min(100, v)) / 10;
    std::cout << "  " << label << " [" << std::string(n, '#') << std::string(10 - n, ' ') << "] " << v << "\n";
  }
};

int main() {
  std::cout << "Name your robot pet: ";
  std::string name;
  if (!(std::cin >> name)) name = "Bolt";
  RobotPet pet(name);

  for (int turn = 1; turn <= 15 && pet.ok(); turn++) {
    pet.show();
    std::cout << "Turn " << turn << "/15: 1 Charge  2 Play  3 Oil  > ";
    int c;
    if (!(std::cin >> c)) break;
    if (c == 1) pet.charge();
    else if (c == 2) pet.play();
    else if (c == 3) pet.oil();
    pet.tick();
  }
  pet.show();
  std::cout << (pet.ok() ? "Your pet is happy and healthy. Great job!\n" : "Oh no, your pet shut down. Try again!\n");
  return 0;
}

#include <algorithm>
#include <iostream>
#include <random>
#include <string>
#include <vector>

const int W = 21, H = 11;  // odd sizes so walls and paths alternate
std::vector<std::string> maze(H, std::string(W, '#'));
std::mt19937 rng(std::random_device{}());

// Carve paths: from a cell, visit neighbours 2 steps away in random order, knocking down the wall between.
void carve(int x, int y) {
  maze[y][x] = ' ';
  int dirs[4][2] = {{2, 0}, {-2, 0}, {0, 2}, {0, -2}};
  std::shuffle(std::begin(dirs), std::end(dirs), rng);
  for (auto &d : dirs) {
    int nx = x + d[0], ny = y + d[1];
    if (nx > 0 && nx < W - 1 && ny > 0 && ny < H - 1 && maze[ny][nx] == '#') {
      maze[y + d[1] / 2][x + d[0] / 2] = ' ';
      carve(nx, ny);
    }
  }
}

int main() {
  carve(1, 1);
  maze[H - 2][W - 2] = 'E';  // the exit
  int px = 1, py = 1, steps = 0;

  while (true) {
    for (int y = 0; y < H; y++) {
      for (int x = 0; x < W; x++) std::cout << (x == px && y == py ? '@' : maze[y][x]);
      std::cout << "\n";
    }
    std::cout << "Steps: " << steps << ". Move with w a s d (type several like ddss), q to quit: ";
    std::string keys;
    if (!(std::cin >> keys) || keys == "q") { std::cout << "\nBye!\n"; return 0; }
    for (char k : keys) {
      int nx = px + (k == 'd') - (k == 'a');
      int ny = py + (k == 's') - (k == 'w');
      if (maze[ny][nx] == '#') { std::cout << "Bonk! A wall.\n"; break; }
      px = nx;
      py = ny;
      steps++;
      if (maze[py][px] == 'E') {
        std::cout << "\nYou escaped the maze in " << steps << " steps!\n";
        return 0;
      }
    }
  }
}

#include <algorithm>
#include <deque>
#include <iostream>
#include <random>
#include <vector>

int main() {
  std::mt19937 rng(std::random_device{}());
  std::vector<int> deck;
  for (int s = 0; s < 4; s++) for (int v = 2; v <= 14; v++) deck.push_back(v);
  std::shuffle(deck.begin(), deck.end(), rng);

  // A deque lets us take cards off the top and put won cards on the bottom.
  std::deque<int> p1(deck.begin(), deck.begin() + 26), p2(deck.begin() + 26, deck.end());
  std::cout << "Press Enter to watch each round, or type 'a' to auto-play the whole game.\n";
  bool autoPlay = false;
  int round = 0;

  while (!p1.empty() && !p2.empty() && round < 2000) {
    round++;
    if (!autoPlay) {
      std::string line;
      if (!std::getline(std::cin, line) || line == "a") autoPlay = true;
    }
    std::vector<int> pot;  // cards being fought over
    while (true) {
      if (p1.empty() || p2.empty()) break;
      int a = p1.front(), b = p2.front();
      p1.pop_front();
      p2.pop_front();
      pot.push_back(a);
      pot.push_back(b);
      if (!autoPlay || round % 100 == 0) std::cout << "Round " << round << ": " << a << " vs " << b;
      if (a != b) {
        std::shuffle(pot.begin(), pot.end(), rng);  // shuffle winnings so games don't loop forever
        auto &winner = (a > b) ? p1 : p2;
        for (int c : pot) winner.push_back(c);
        if (!autoPlay || round % 100 == 0)
          std::cout << " -> Player " << (a > b ? 1 : 2) << " takes " << pot.size() << " cards (" << p1.size() << " vs " << p2.size() << ")\n";
        break;
      }
      // Same card: WAR! Each player puts down 3 face-down cards, then flips again.
      if (!autoPlay) std::cout << " -> WAR!\n";
      for (int i = 0; i < 3 && p1.size() > 1 && p2.size() > 1; i++) {
        pot.push_back(p1.front()); p1.pop_front();
        pot.push_back(p2.front()); p2.pop_front();
      }
    }
  }
  std::cout << "\nAfter " << round << " rounds: ";
  if (p1.size() == p2.size()) std::cout << "it's a draw!\n";
  else std::cout << "Player " << (p1.size() > p2.size() ? 1 : 2) << " wins with " << std::max(p1.size(), p2.size()) << " cards!\n";
  return 0;
}

