#include <algorithm>
#include <iostream>
#include <random>
#include <string>

std::mt19937 rng(std::random_device{}());

int bestScore(int dice[5], std::string &what) {
  int counts[7] = {0};
  int sum = 0;
  for (int i = 0; i < 5; i++) { counts[dice[i]]++; sum += dice[i]; }
  int most = *std::max_element(counts + 1, counts + 7);
  bool pair = std::count(counts + 1, counts + 7, 2) == 1;
  int run = 0, longest = 0;
  for (int v = 1; v <= 6; v++) { run = counts[v] ? run + 1 : 0; longest = std::max(longest, run); }

  if (most == 5) { what = "YAHTZEE!"; return 50; }
  if (longest == 5) { what = "Large straight"; return 40; }
  if (most == 3 && pair) { what = "Full house"; return 25; }
  if (longest == 4) { what = "Small straight"; return 30; }
  if (most == 4) { what = "Four of a kind"; return sum; }
  if (most == 3) { what = "Three of a kind"; return sum; }
  what = "Chance (just the total)";
  return sum / 2;  // half points for nothing special
}

int main() {
  std::uniform_int_distribution<int> die(1, 6);
  int total = 0;
  for (int round = 1; round <= 5; round++) {
    int dice[5];
    for (int &d : dice) d = die(rng);
    std::cout << "\n=== Round " << round << " ===\n";
    for (int roll = 1; roll <= 3; roll++) {
      std::cout << "Roll " << roll << ":";
      for (int i = 0; i < 5; i++) std::cout << "  [" << i + 1 << "]=" << dice[i];
      std::cout << "\n";
      if (roll == 3) break;
      std::cout << "Type the dice positions to REROLL (like 135), or 0 to keep all: ";
      std::string pick;
      if (!(std::cin >> pick)) { std::cout << "\nBye! Score: " << total << "\n"; return 0; }
      if (pick == "0") break;
      for (char c : pick)
        if (c >= '1' && c <= '5') dice[c - '1'] = die(rng);
    }
    std::string what;
    int points = bestScore(dice, what);
    total += points;
    std::cout << what << ": " << points << " points. Total: " << total << "\n";
  }
  std::cout << "\nFinal score: " << total << (total >= 150 ? "  Amazing!" : "") << "\n";
  return 0;
}

#include <algorithm>
#include <iostream>
#include <random>

int main() {
  std::mt19937 rng(std::random_device{}());
  auto chance = [&](int percent) { return std::uniform_int_distribution<int>(1, 100)(rng) <= percent; };
  int health = 10, food = 5, walls = 2;

  std::cout << "The zombies are coming! Survive 10 days.\n";
  for (int day = 1; day <= 10; day++) {
    std::cout << "\n--- Day " << day << " ---  Health " << health << "  Food " << food << "  Barricades " << walls << "\n";
    std::cout << "1 Scavenge for food  2 Build barricades  3 Rest\n> ";
    int choice;
    if (!(std::cin >> choice)) { std::cout << "\nYou hide in the basement forever. The end.\n"; return 0; }

    if (choice == 1) {
      int found = std::uniform_int_distribution<int>(1, 4)(rng);
      food += found;
      std::cout << "You find " << found << " cans of beans.\n";
      if (chance(35)) { health -= 2; std::cout << "A zombie chases you! You trip and lose 2 health.\n"; }
    } else if (choice == 2) {
      walls++;
      std::cout << "You nail boards over the windows. Barricades up!\n";
    } else {
      health = std::min(10, health + 3);
      std::cout << "You take a nap and feel better.\n";
    }

    // Everyone needs to eat.
    if (food > 0) food--;
    else { health -= 2; std::cout << "No food! You're starving (-2 health).\n"; }

    // Night attack: barricades break before you get hurt.
    if (chance(20 + day * 5)) {
      std::cout << "Zombies attack in the night! ";
      if (walls > 0) { walls--; std::cout << "Your barricade holds, but breaks.\n"; }
      else { health -= 3; std::cout << "No barricades! You fight them off but lose 3 health.\n"; }
    }
    if (health <= 0) { std::cout << "\nYou didn't make it. You survived " << day - 1 << " days.\n"; return 0; }
  }
  std::cout << "\nThe rescue helicopter arrives! You SURVIVED with " << health << " health!\n";
  return 0;
}

