          std::cout << "Those sides can't make a triangle!\n";
          break;
        }
        double s = (a + b + c) / 2;  // Heron's formula uses half the perimeter
        std::cout << "Area (Heron's formula) = " << std::sqrt(s * (s - a) * (s - b) * (s - c))
                  << "\nPerimeter = a + b + c = " << a + b + c << "\n";
        break;
      }
