#include <iostream>
#include <sstream>
#include <string>
#include <vector>

struct Student {
  std::string name;
  std::vector<double> scores;
  double average = 0;
};

char letter(double avg) {
  if (avg >= 90) return 'A';
  if (avg >= 80) return 'B';
  if (avg >= 70) return 'C';
  if (avg >= 60) return 'D';
  return 'F';
}

int main() {
  std::cout << "Type one student per line: name then scores, like  Storm 95 88 100\n";
  std::cout << "Press Ctrl+D when done.\n";
  std::vector<Student> students;
  std::string line;
  while (std::getline(std::cin, line)) {
    std::istringstream in(line);
    Student s;
    if (!(in >> s.name)) continue;
    double x;
    while (in >> x) s.scores.push_back(std::clamp(x, 0.0, 100.0));
    if (s.scores.empty()) { std::cout << "(" << s.name << " has no scores, skipped)\n"; continue; }
    double sum = 0;
    for (double v : s.scores) sum += v;
    s.average = sum / s.scores.size();
    students.push_back(s);
  }
  if (students.empty()) {
    students = {{"Ada", {95, 90}, 92.5}, {"Ben", {72, 80}, 76}, {"Cy", {55, 68}, 61.5}};
    std::cout << "No students typed, so here's a sample class.\n";
  }

  std::sort(students.begin(), students.end(), [](const Student &a, const Student &b) { return a.average > b.average; });

  std::cout << "\n" << std::left << std::setw(12) << "Name" << "Avg    Grade\n";
  double classTotal = 0;
  for (const Student &s : students) {
    std::cout << std::left << std::setw(12) << s.name << std::fixed << std::setprecision(1) << std::setw(7)
              << s.average << letter(s.average) << "  " << std::string(static_cast<size_t>(s.average / 5), '#') << "\n";
    classTotal += s.average;
  }
  std::cout << "\nClass average: " << classTotal / students.size() << "\n";
  std::cout << "Top of the class: " << students.front().name << "!\n";
  return 0;
}

#include <cmath>
#include <iostream>
#include <vector>

int main() {
  // Work in cents so there are no rounding problems with decimals.
  const int money[] = {2000, 1000, 500, 100, 25, 10, 5, 1};
  const char *names[] = {"$20 bill", "$10 bill", "$5 bill", "$1 bill", "quarter", "dime", "nickel", "penny"};

  double price, paid;
  while (std::cout << "Price and money paid, like 3.47 10 (Ctrl+D to stop): " && std::cin >> price >> paid) {
    long cents = std::lround((paid - price) * 100);
    if (cents < 0) { std::cout << "Not enough money!\n"; continue; }
    if (cents > 10000000) { std::cout << "That's a lot of change. Try a smaller amount.\n"; continue; }
    std::cout << "Change: $" << cents / 100 << "." << (cents % 100 < 10 ? "0" : "") << cents % 100 << "\n";
    // Greedy: always give the biggest coin that fits.
    for (int i = 0; i < 8; i++) {
      long count = cents / money[i];
      if (count) std::cout << "  " << count << " x " << names[i] << "\n";
      cents %= money[i];
    }
  }

  // Greedy works for US coins, but not for every coin set! Coins 1, 3, 4 and 6 cents:
  std::cout << "\n\nWeird coins 1, 3, 4: greedy gives 6 = 4+1+1 (3 coins), best is 3+3 (2 coins).\n";
  std::vector<int> weird = {1, 3, 4};
  int target = 6;
  // Dynamic programming: best[x] = fewest coins to make x, built up from small amounts.
  std::vector<int> best(target + 1, 1000);
  best[0] = 0;
  for (int x = 1; x <= target; x++)
    for (int c : weird)
      if (c <= x && best[x - c] + 1 < best[x]) best[x] = best[x - c] + 1;
  std::cout << "Dynamic programming finds " << best[target] << " coins.\n";
  return 0;
}

#include <iostream>

// Count the steps to reach 1 from n.
int steps(unsigned long long n, unsigned long long &highest) {
  int count = 0;
  highest = n;
  while (n != 1) {
    n = (n % 2 == 0) ? n / 2 : 3 * n + 1;
    if (n > highest) highest = n;
    count++;
  }
  return count;
}

int main() {
  // Nobody has ever proved every number reaches 1. It's still an unsolved problem!
  std::cout << "Starting from 27:\n";
  unsigned long long n = 27;
  int col = 0;
  while (true) {
    std::cout << n << (n == 1 ? "\n" : " -> ");
    if (++col % 10 == 0 && n != 1) std::cout << "\n";
    if (n == 1) break;
    n = (n % 2 == 0) ? n / 2 : 3 * n + 1;
  }

  int bestStart = 1, bestSteps = 0;
  unsigned long long peak;
  for (int start = 1; start < 100000; start++) {
    int s = steps(start, peak);
    if (s > bestSteps) { bestSteps = s; bestStart = start; }
  }
  std::cout << "\nUnder 100000, the longest chain starts at " << bestStart << " with " << bestSteps << " steps.\n";

  std::cout << "\nType a starting number (1 to 1000000000, Ctrl+D to stop): ";
  long long start;
  while (std::cin >> start) {
    if (start < 1 || start > 1000000000LL) { std::cout << "Use 1 to 1000000000.\nStart: "; continue; }
    int s = steps(static_cast<unsigned long long>(start), peak);
    std::cout << start << " takes " << s << " steps and climbs as high as " << peak << "\nStart: ";
  }
  std::cout << "\n";
  return 0;
}

#include <iostream>

// n! = 1 x 2 x 3 x ... x n. Only fits in 64 bits up to 20!
unsigned long long factorial(int n) {
  unsigned long long f = 1;
  for (int i = 2; i <= n; i++) f *= i;
  return f;
}

// Combinations: ways to CHOOSE k things from n when order doesn't matter.
// Multiply and divide a step at a time so the numbers stay small.
unsigned long long choose(int n, int k) {
  if (k < 0 || k > n) return 0;
  if (k > n - k) k = n - k;
  unsigned long long result = 1;
  for (int i = 1; i <= k; i++) result = result * (n - k + i) / i;  // always divides exactly
  return result;
}

// Permutations: ways to ARRANGE k things from n when order matters.
unsigned long long permute(int n, int k) {
  if (k < 0 || k > n) return 0;
  unsigned long long result = 1;
  for (int i = 0; i < k; i++) result *= n - i;
  return result;
}

int main() {
  for (int i = 0; i <= 20; i += 5) std::cout << i << "! = " << factorial(i) << "\n";
  std::cout << "\nPizza with 3 toppings picked from 10: " << choose(10, 3) << " different pizzas\n";
  std::cout << "Gold, silver, bronze among 8 runners: " << permute(8, 3) << " ways\n";
  std::cout << "Lottery picking 6 numbers from 49: 1 in " << choose(49, 6) << "\n\n";

  std::cout << "Type n and k (both 0 to 60) to see nPk and nCk (Ctrl+D to stop): ";
  int n, k;
  while (std::cin >> n >> k) {
    if (n < 0 || n > 60 || k < 0 || k > n) {
      std::cout << "Need 0 <= k <= n <= 60.\nn and k: ";
      continue;
    }
    std::cout << n << "C" << k << " = " << choose(n, k);
    if (n <= 20) std::cout << "   " << n << "P" << k << " = " << permute(n, k);
    std::cout << "\nn and k: ";
  }
  std::cout << "\n";
  return 0;
}

#include <iostream>
#include <vector>

long long calls = 0;

// Simple but SLOW: it works out the same numbers again and again.
long long fibSlow(int n) {
  calls++;
  if (n < 2) return n;
  return fibSlow(n - 1) + fibSlow(n - 2);
}

// Memoization: remember answers in a "memo" so each one is worked out only once.
long long fibMemo(int n, std::vector<long long> &memo) {
  if (n < 2) return n;
  if (memo[n] != -1) return memo[n];
  return memo[n] = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
}

// A loop: just keep the last two numbers.
unsigned long long fibLoop(int n) {
  unsigned long long a = 0, b = 1;
  for (int i = 0; i < n; i++) {
    unsigned long long next = a + b;
    a = b;
    b = next;
  }
  return a;
}

int main() {
  std::cout << "First 20 Fibonacci numbers:";
  for (int i = 0; i < 20; i++) std::cout << " " << fibLoop(i);
  std::cout << "\n\n";

  calls = 0;
  std::cout << "fibSlow(30) = " << fibSlow(30) << " using " << calls << " function calls!\n";
  std::vector<long long> memo(91, -1);
  std::cout << "fibMemo(90) = " << fibMemo(90, memo) << " (each number worked out just once)\n";
  std::cout << "fibLoop(93) = " << fibLoop(93) << " (the biggest that fits in 64 bits)\n\n";

  // Divide each Fibonacci number by the one before: it gets closer and closer to 1.6180339...
  std::cout << "Golden ratio appears:\n";
  for (int i = 2; i <= 20; i += 3) {
    std::cout << "  F(" << i + 1 << ")/F(" << i << ") = " << static_cast<double>(fibLoop(i + 1)) / fibLoop(i) << "\n";
  }
  return 0;
}

#include <cmath>
#include <iomanip>
#include <iostream>
#include <random>

int main() {
  // A circle of radius 1 inside a 2 x 2 square. Circle area = pi, square area = 4.
  // So the fraction of darts landing inside the circle should be about pi / 4.
  std::mt19937 rng(2024);  // fixed seed so you get the same answer each time
  std::uniform_real_distribution<double> coord(-1.0, 1.0);

  const double REAL_PI = 3.14159265358979;
  long long inside = 0, thrown = 0;
  std::cout << std::setprecision(8);
  for (long long target = 10; target <= 10000000; target *= 10) {
    while (thrown < target) {
      double x = coord(rng), y = coord(rng);
      if (x * x + y * y <= 1.0) inside++;  // inside the circle?
      thrown++;
    }
    double estimate = 4.0 * inside / thrown;
    std::cout << std::setw(9) << thrown << " darts: pi is about " << std::setw(10) << estimate
              << "  (off by " << std::fabs(estimate - REAL_PI) << ")\n";
  }
  std::cout << "\nMore darts = a better guess, but it improves slowly.\n";

  // Small picture: 60 darts, * inside the circle, . outside
  char grid[11][21];
  for (auto &row : grid) for (char &c : row) c = ' ';
  for (int i = 0; i < 60; i++) {
    double x = coord(rng), y = coord(rng);
    grid[static_cast<int>((y + 1) * 5)][static_cast<int>((x + 1) * 10)] = (x * x + y * y <= 1) ? '*' : '.';
  }
  for (auto &row : grid) {
    for (char c : row) std::cout << c;
    std::cout << "\n";
  }
  return 0;
}

#include <iostream>
#include <numeric>
#include <stdexcept>

class Fraction {
public:
  Fraction(long long top = 0, long long bottom = 1) : num_(top), den_(bottom) {
    if (den_ == 0) throw std::invalid_argument("the bottom of a fraction can't be 0");
    simplify();
  }

  Fraction operator+(const Fraction &o) const { return {num_ * o.den_ + o.num_ * den_, den_ * o.den_}; }
  Fraction operator-(const Fraction &o) const { return {num_ * o.den_ - o.num_ * den_, den_ * o.den_}; }
  Fraction operator*(const Fraction &o) const { return {num_ * o.num_, den_ * o.den_}; }
  Fraction operator/(const Fraction &o) const { return {num_ * o.den_, den_ * o.num_}; }  // flip and multiply

  double toDouble() const { return static_cast<double>(num_) / den_; }

  friend std::ostream &operator<<(std::ostream &out, const Fraction &f) {
    if (f.den_ == 1) return out << f.num_;
    long long whole = f.num_ / f.den_;
    if (whole != 0) {  // show as a mixed number too, like 7/2 = 3 1/2
      long long rest = f.num_ % f.den_;
      return out << f.num_ << "/" << f.den_ << " (= " << whole << " " << (rest < 0 ? -rest : rest) << "/" << f.den_ << ")";
    }
    return out << f.num_ << "/" << f.den_;
  }

private:
  long long num_, den_;

  void simplify() {
    if (den_ < 0) { num_ = -num_; den_ = -den_; }  // keep the minus sign on top
    long long g = std::gcd(num_, den_);
    if (g != 0) { num_ /= g; den_ /= g; }
  }
};

int main() {
  std::cout << "Type a sum like 1/2 + 3/4 (signs: + - * /). Ctrl+D to stop.\n";
  long long a, b, c, d;
  char slash1, op, slash2;
  while (std::cout << "> " && std::cin >> a >> slash1 >> b >> op >> c >> slash2 >> d) {
    try {
      Fraction x(a, b), y(c, d), result;
      if (op == '+') result = x + y;
      else if (op == '-') result = x - y;
      else if (op == '*') result = x * y;
      else if (op == '/') result = x / y;
      else { std::cout << "Unknown sign " << op << "\n"; continue; }
      std::cout << x << " " << op << " " << y << " = " << result << "  ~ " << result.toDouble() << "\n";
    } catch (const std::invalid_argument &e) {
      std::cout << "Oops: " << e.what() << "\n";
    }
  }
  std::cout << "\n";
  return 0;
}

#include <iostream>
