// Euclid's trick: gcd(a, b) = gcd(b, a % b), until the remainder is 0.
long long gcdSteps(long long a, long long b) {
  while (b != 0) {
    std::cout << "  gcd(" << a << ", " << b << ") -> " << a << " % " << b << " = " << a % b << "\n";
    long long r = a % b;
    a = b;
    b = r;
  }
  return a;
}

int main() {
  std::cout << "Type two whole numbers (Ctrl+D to stop): ";
  long long a, b;
  while (std::cin >> a >> b) {
    if (a <= 0 || b <= 0) {
      std::cout << "Please use positive numbers.\nType two whole numbers: ";
      continue;
    }
    long long g = gcdSteps(a, b);
    long long l = a / g * b;  // divide first so the number stays smaller
    std::cout << "GCD = " << g << "   (std::gcd agrees: " << std::gcd(a, b) << ")\n";
    std::cout << "LCM = " << l << "   (std::lcm agrees: " << std::lcm(a, b) << ")\n";
    std::cout << "Fraction " << a << "/" << b << " simplifies to " << a / g << "/" << b / g << "\n";
    std::cout << "\nType two whole numbers: ";
  }
  std::cout << "\n";
  return 0;
}

#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

// Column addition, right to left, with carrying, just like on paper.
std::string add(const std::string &a, const std::string &b) {
  std::string out;
  int carry = 0;
  for (int i = static_cast<int>(a.size()) - 1, j = static_cast<int>(b.size()) - 1; i >= 0 || j >= 0 || carry; i--, j--) {
    int sum = carry + (i >= 0 ? a[i] - '0' : 0) + (j >= 0 ? b[j] - '0' : 0);
    out += static_cast<char>('0' + sum % 10);
    carry = sum / 10;
  }
  std::reverse(out.begin(), out.end());
  return out;
}

// Long multiplication: every digit times every digit, added into the right column.
std::string multiply(const std::string &a, const std::string &b) {
  std::vector<int> cols(a.size() + b.size(), 0);
  for (int i = static_cast<int>(a.size()) - 1; i >= 0; i--)
    for (int j = static_cast<int>(b.size()) - 1; j >= 0; j--) {
      int sum = (a[i] - '0') * (b[j] - '0') + cols[i + j + 1];
      cols[i + j + 1] = sum % 10;
      cols[i + j] += sum / 10;
    }
  std::string out;
  for (int d : cols) if (!(out.empty() && d == 0)) out += static_cast<char>('0' + d);
  return out.empty() ? "0" : out;
}

bool allDigits(const std::string &s) {
  return !s.empty() && std::all_of(s.begin(), s.end(), [](char c) { return c >= '0' && c <= '9'; });
}

int main() {
  std::string f = "1";
  for (int i = 2; i <= 50; i++) f = multiply(f, std::to_string(i));
  std::cout << "50! = " << f << " (" << f.size() << " digits)\n\n";

  std::cout << "Type two huge whole numbers (Ctrl+D to stop):\n";
  std::string a, b;
  while (std::cout << "> " && std::cin >> a >> b) {
    if (!allDigits(a) || !allDigits(b)) { std::cout << "Only digits please.\n"; continue; }
    std::cout << "Sum:     " << add(a, b) << "\nProduct: " << multiply(a, b) << "\n";
  }
  std::cout << "\n";
  return 0;
}

#include <iomanip>
#include <iostream>
#include <string>

int main() {
  double people = 1000, infected = 1, recovered = 0;
  double contacts = 0.4;  // chance per day of passing it on, per sick person
  double getWell = 0.1;   // fraction of sick people who get better each day (about 10 days sick)

  std::cout << "Spread rate per day (0.1 to 1, try 0.4 then 0.2): ";
  double typed;
  if (std::cin >> typed && typed >= 0.1 && typed <= 1) contacts = typed;

  double healthy = people - infected;
  double peak = 0;
  int peakDay = 0;
  std::cout << "R0 = " << contacts / getWell << " (each sick person infects this many at the start)\n\n";
  std::cout << "Day  Healthy   Sick  Better\n";
  for (int day = 0; day <= 120; day++) {
    if (infected > peak) { peak = infected; peakDay = day; }
    if (day % 4 == 0) {
      std::cout << std::setw(3) << day << std::setw(9) << static_cast<int>(healthy) << std::setw(7) << static_cast<int>(infected)
                << std::setw(8) << static_cast<int>(recovered) << " " << std::string(static_cast<int>(infected / 10), '#') << "\n";
    }
    // New infections need a sick person to meet a healthy one.
    double newSick = contacts * infected * healthy / people;
    double newBetter = getWell * infected;
    healthy -= newSick;
    infected += newSick - newBetter;
    recovered += newBetter;
  }
  std::cout << "\nThe most people sick at once was " << static_cast<int>(peak) << " on day " << peakDay << ".\n";
  std::cout << static_cast<int>(healthy) << " people never caught it.\n";
  std::cout << "Lower the spread rate (washing hands!) and the peak gets smaller: that's flattening the curve.\n";
  return 0;
}

#include <iomanip>
#include <iostream>

bool isLeap(int y) {
  // Every 4 years, except every 100, except every 400.
  return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
}

int daysIn(int month, int year) {
  const int days[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
  return (month == 2 && isLeap(year)) ? 29 : days[month - 1];
}

// Zeller's congruence: 0 = Sunday, 1 = Monday ... 6 = Saturday
int dayOfWeek(int d, int m, int y) {
  if (m < 3) { m += 12; y--; }  // January and February count as months 13 and 14 of last year
  int k = y % 100, j = y / 100;
  int h = (d + 13 * (m + 1) / 5 + k + k / 4 + j / 4 + 5 * j) % 7;  // 0 = Saturday here
  return (h + 6) % 7;
}

int main() {
  const char *names[] = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
  std::cout << "Type a date as day month year, like 4 7 1776 (Ctrl+D to stop): ";
  int d, m, y;
  while (std::cin >> d >> m >> y) {
    if (y < 1583 || y > 9999 || m < 1 || m > 12 || d < 1 || d > daysIn(m, y)) {
      std::cout << "That's not a real date (years 1583 to 9999).\nDate: ";
      continue;
    }
    std::cout << d << "/" << m << "/" << y << " is a " << names[dayOfWeek(d, m, y)] << ".\n";
    std::cout << y << (isLeap(y) ? " is" : " is not") << " a leap year.\n\n";

    std::cout << " Su Mo Tu We Th Fr Sa\n";
    int start = dayOfWeek(1, m, y);
    std::cout << std::string(start * 3, ' ');
    for (int day = 1; day <= daysIn(m, y); day++) {
      if (day == d) std::cout << std::setw(2) << day << "*";
      else std::cout << std::setw(3) << day;
      if ((start + day) % 7 == 0) std::cout << "\n";
    }
    std::cout << "\n\nDate: ";
  }
  std::cout << "\n";
  return 0;
}

