#include <cmath>
#include <iostream>

int main() {
  std::cout << "Solve a x^2 + b x + c = 0\nType a b c (Ctrl+D to stop): ";
  double a, b, c;
  while (std::cin >> a >> b >> c) {
    if (a == 0) {
      // Not really quadratic: b x + c = 0
      if (b == 0) std::cout << (c == 0 ? "Every x works!\n" : "No x works.\n");
      else std::cout << "It's a straight line: x = " << -c / b << "\n";
    } else {
      double disc = b * b - 4 * a * c;  // the discriminant decides how many answers
      std::cout << "Discriminant b^2 - 4ac = " << disc << "\n";
      if (disc > 0) {
        double root = std::sqrt(disc);
        std::cout << "Two answers: x = " << (-b + root) / (2 * a) << " and x = " << (-b - root) / (2 * a) << "\n";
      } else if (disc == 0) {
        std::cout << "One answer: x = " << -b / (2 * a) << "\n";
      } else {
        double real = -b / (2 * a), imag = std::sqrt(-disc) / (2 * a);
        std::cout << "No real answers (the curve never touches the x axis).\n"
                  << "Complex answers: x = " << real << " + " << std::fabs(imag) << "i and " << real << " - "
                  << std::fabs(imag) << "i\n";
      }
      std::cout << "The curve's turning point is at x = " << -b / (2 * a) << "\n";
    }
    std::cout << "\nType a b c: ";
  }
  std::cout << "\n";
  return 0;
}

#include <cmath>
#include <iostream>
#include <random>
#include <string>

int main() {
  std::mt19937 rng(std::random_device{}());
  std::bernoulli_distribution coin(0.5);

  // One walker on a 41-wide path, starting in the middle.
  std::cout << "One walker, 30 coin flips:\n";
  int pos = 0;
  for (int step = 0; step <= 30; step++) {
    std::string path(41, '.');
    path[20] = '|';
    if (pos >= -20 && pos <= 20) path[pos + 20] = '@';
    std::cout << path << "  " << (pos >= 0 ? "+" : "") << pos << "\n";
    pos += coin(rng) ? 1 : -1;
  }

  // Lots of walkers: how far away do they end up on average?
  std::cout << "\nSteps   Average distance   sqrt(steps)\n";
  for (int steps = 16; steps <= 4096; steps *= 4) {
    const int walkers = 2000;
    double total = 0;
    for (int w = 0; w < walkers; w++) {
      int p = 0;
      for (int s = 0; s < steps; s++) p += coin(rng) ? 1 : -1;
      total += static_cast<double>(p) * p;
    }
    // Root mean square distance: square, average, then square root.
    std::cout << steps << "\t" << std::sqrt(total / walkers) << "\t\t" << std::sqrt(steps) << "\n";
  }
  std::cout << "\nTo get twice as far away, a random walker needs four times as many steps!\n";
  return 0;
}

#include <cctype>
#include <iostream>
#include <string>

const int values[] = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};
const char *symbols[] = {"M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"};

// Greedy: take the biggest symbol that still fits, again and again.
std::string toRoman(int n) {
  std::string out;
  for (int i = 0; i < 13; i++) {
    while (n >= values[i]) { out += symbols[i]; n -= values[i]; }
  }
  return out;
}

int letterValue(char c) {
  switch (c) {
    case 'I': return 1;   case 'V': return 5;   case 'X': return 10;  case 'L': return 50;
    case 'C': return 100; case 'D': return 500; case 'M': return 1000; default: return 0;
  }
}

// A smaller letter before a bigger one is subtracted (IV = 4), otherwise added.
int fromRoman(const std::string &s) {
  int total = 0;
  for (size_t i = 0; i < s.size(); i++) {
    int v = letterValue(s[i]);
    if (v == 0) return -1;
    if (i + 1 < s.size() && v < letterValue(s[i + 1])) total -= v;
    else total += v;
  }
  return total;
}

int main() {
  std::cout << "Type a number (1-3999) or a Roman numeral like XIV (Ctrl+D to stop):\n";
  std::string word;
  while (std::cout << "> " && std::cin >> word) {
    if (std::isdigit(static_cast<unsigned char>(word[0]))) {
      long n = std::stol(word.substr(0, 9));
      if (n < 1 || n > 3999) std::cout << "Romans only wrote 1 to 3999 this way.\n";
      else std::cout << n << " = " << toRoman(static_cast<int>(n)) << "\n";
    } else {
      for (char &c : word) c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
      int n = fromRoman(word);
      // Check it by converting back: this catches badly written ones like IIII or VX.
      if (n <= 0 || n > 3999 || toRoman(n) != word) std::cout << word << " is not a proper Roman numeral.\n";
      else std::cout << word << " = " << n << "\n";
    }
  }
  std::cout << "\n";
  return 0;
}

