#include <iostream>
#include <vector>

int main() {
  int limit = 200;
  std::cout << "Find primes up to (2 to 10000000)? ";
  if (!(std::cin >> limit) || limit < 2 || limit > 10000000) limit = 200;

  // Start by assuming every number is prime, then cross out the ones that aren't.
  std::vector<bool> prime(limit + 1, true);
  prime[0] = prime[1] = false;
  for (long long p = 2; p * p <= limit; p++) {
    if (!prime[p]) continue;
    // Cross out p*p, p*p+p, p*p+2p... (smaller multiples were crossed out already).
    for (long long m = p * p; m <= limit; m += p) prime[m] = false;
  }

  int count = 0, twins = 0;
  for (int n = 2; n <= limit; n++) {
    if (!prime[n]) continue;
    count++;
    if (n + 2 <= limit && prime[n + 2]) twins++;  // primes 2 apart, like 11 and 13
  }

  if (limit <= 1000) {
    std::cout << "Primes:";
    for (int n = 2; n <= limit; n++) if (prime[n]) std::cout << " " << n;
    std::cout << "\n";
  }
  std::cout << "There are " << count << " primes up to " << limit << ".\n";
  std::cout << "Twin prime pairs: " << twins << "\n";
  for (int n = limit; n >= 2; n--) {
    if (prime[n]) { std::cout << "The biggest is " << n << ".\n"; break; }
  }
  return 0;
}

#include <cmath>
#include <iostream>

int main() {
  std::cout << "Equations look like:  a x + b y = c\n";
  std::cout << "Type a b c for the first, then a b c for the second (Ctrl+D to stop):\n";
  double a1, b1, c1, a2, b2, c2;
  while (std::cin >> a1 >> b1 >> c1 >> a2 >> b2 >> c2) {
    std::cout << a1 << "x + " << b1 << "y = " << c1 << "\n" << a2 << "x + " << b2 << "y = " << c2 << "\n";
    // The determinant tells us if the two lines cross at exactly one point.
    double det = a1 * b2 - a2 * b1;
    if (std::fabs(det) < 1e-12) {
      // Same slope: either the same line or parallel lines that never meet.
      bool same = std::fabs(a1 * c2 - a2 * c1) < 1e-12 && std::fabs(b1 * c2 - b2 * c1) < 1e-12;
      std::cout << (same ? "Same line: infinitely many answers!\n" : "Parallel lines: no answer.\n");
    } else {
      double x = (c1 * b2 - c2 * b1) / det;
      double y = (a1 * c2 - a2 * c1) / det;
      std::cout << "x = " << x << ", y = " << y << "\n";
      std::cout << "Check: " << a1 * x + b1 * y << " = " << c1 << " and " << a2 * x + b2 * y << " = " << c2 << "\n";
    }
    std::cout << "\nNext pair of equations:\n";
  }
  return 0;
}

