#include <iostream>
#include <string>
#include <vector>

std::vector<int> pegs[3];
int disks = 4;
long long moves = 0;

void draw() {
  for (int level = disks - 1; level >= 0; level--) {
    for (const auto &peg : pegs) {
      if (level < static_cast<int>(peg.size())) {
        int size = peg[level];
        std::cout << std::string(disks - size, ' ') << std::string(size * 2 + 1, '=') << std::string(disks - size, ' ');
      } else {
        std::cout << std::string(disks, ' ') << "|" << std::string(disks, ' ');
      }
      std::cout << "  ";
    }
    std::cout << "\n";
  }
  std::cout << std::string((disks * 2 + 3) * 3, '-') << "\n";
}

// To move n disks from A to C: move n-1 out of the way to B, move the biggest to C, then n-1 from B onto it.
void solve(int n, int from, int to, int spare, bool show) {
  if (n == 0) return;
  solve(n - 1, from, spare, to, show);
  pegs[to].push_back(pegs[from].back());
  pegs[from].pop_back();
  moves++;
  if (show) {
    std::cout << "Move " << moves << ": disk " << pegs[to].back() << " from peg " << "ABC"[from] << " to " << "ABC"[to] << "\n";
    draw();
  }
  solve(n - 1, spare, to, from, show);
}

int main() {
  std::cout << "How many disks (1-8)? ";
  if (!(std::cin >> disks) || disks < 1 || disks > 8) disks = 4;
  for (int d = disks; d >= 1; d--) pegs[0].push_back(d);
  draw();
  solve(disks, 0, 2, 1, disks <= 5);  // drawing every move gets long for big towers
  if (disks > 5) draw();
  std::cout << "Solved in " << moves << " moves. The fewest possible is 2^n - 1 = " << (1LL << disks) - 1 << ".\n";
  std::cout << "With 64 disks at one move per second, it would take about 585 billion years!\n";
  return 0;
}

#include <algorithm>
#include <cmath>
#include <iostream>

const double PI = 3.14159265358979;

// Law of cosines: angle opposite side c = acos((a^2 + b^2 - c^2) / 2ab)
double angleOpposite(double a, double b, double c) {
  double cosC = (a * a + b * b - c * c) / (2 * a * b);
  cosC = std::max(-1.0, std::min(1.0, cosC));  // keep rounding errors inside acos' range
  return std::acos(cosC) * 180 / PI;
}

int main() {
  std::cout << "Type three side lengths (Ctrl+D to stop): ";
  double a, b, c;
  while (std::cin >> a >> b >> c) {
    double s[3] = {a, b, c};
    std::sort(s, s + 3);  // s[2] is now the longest side
    if (s[0] <= 0 || s[0] + s[1] <= s[2]) {
      std::cout << "Not a triangle: the two short sides must add up to more than the long one.\n";
    } else {
      if (s[0] == s[2]) std::cout << "Equilateral (all sides equal). ";
      else if (s[0] == s[1] || s[1] == s[2]) std::cout << "Isosceles (two sides equal). ";
      else std::cout << "Scalene (no sides equal). ";

      double diff = s[0] * s[0] + s[1] * s[1] - s[2] * s[2];
      double tiny = 1e-9 * s[2] * s[2];
      if (std::fabs(diff) <= tiny) std::cout << "Right-angled!\n";
      else if (diff > 0) std::cout << "Acute (all angles under 90).\n";
      else std::cout << "Obtuse (one angle over 90).\n";

      double A = angleOpposite(b, c, a), B = angleOpposite(a, c, b), C = 180 - A - B;
      std::cout << "Angles: " << A << ", " << B << ", " << C << " degrees (they add to 180)\n";
    }
    std::cout << "\nType three side lengths: ";
  }
  std::cout << "\n";
  return 0;
}

