# Every recursive function needs a BASE CASE (when to stop)
# and a RECURSIVE CASE (call itself with a smaller problem).

def factorial(n):
    if n <= 1:          # base case
        return 1
    return n * factorial(n - 1)  # recursive case


def countdown(n):
    if n == 0:
        print("Blast off!")
        return
    print(n)
    countdown(n - 1)


def sum_of_digits(n):
    if n < 10:
        return n
    return n % 10 + sum_of_digits(n // 10)


def reverse(text):
    if text == "":
        return ""
    return reverse(text[1:]) + text[0]


for i in range(1, 8):
    print(f"{i}! = {factorial(i)}")

countdown(5)
print("Sum of digits of 98765:", sum_of_digits(98765))
print("Reverse of 'recursion':", reverse("recursion"))

from collections import deque

# STACK: like a pile of plates. You take from the top.
undo_stack = []
text = ""
for word in ["Hello", " there", " friend", " :)"]:
    undo_stack.append(text)  # save the old version
    text += word
    print("Typed:", repr(text))

for _ in range(2):
    text = undo_stack.pop()   # undo takes the most recent save
    print("Undo ->", repr(text))

# QUEUE: like a line at the store. First one in is first one out.
line = deque()
for player in ["Storm", "Doodle", "Nova", "Ace"]:
    line.append(player)
    print(player, "joined the line:", list(line))

while line:
    up_next = line.popleft()
    print(up_next, "is playing now. Still waiting:", list(line))

# Checking brackets is a classic stack problem
def balanced(code):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in code:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

for code in ["print((1 + 2) * [3])", "{[}]", "((("]:
    print(code, "->", "balanced" if balanced(code) else "NOT balanced")

