def explain_binary(n):
    """Show how a binary number is built from powers of 2."""
    bits = bin(n)[2:]
    parts = [f"{bit}x{2 ** power}" for power, bit in zip(range(len(bits) - 1, -1, -1), bits)]
    return " + ".join(parts)


