from fractions import Fraction


def mixed(f):
    """Turn 7/4 into '1 3/4'."""
    whole, rest = divmod(abs(f.numerator), f.denominator)
    sign = "-" if f < 0 else ""
    if rest == 0:
        return f"{sign}{whole}"
    if whole == 0:
        return f"{sign}{rest}/{f.denominator}"
    return f"{sign}{whole} {rest}/{f.denominator}"


