            robot.forward(speed)
        elif cmd == "s":
            robot.backward(speed)
        elif cmd == "a":
            robot.left(speed)
        elif cmd == "d":
            robot.right(speed)
        elif cmd == "x":
            robot.stop()
        elif cmd == "+":
            speed = min(1.0, speed + 0.1)
        elif cmd == "-":
            speed = max(0.2, speed - 0.1)
        elif cmd == "dance":
            for _ in range(3):
                robot.left(speed)
                sleep(0.3)
                robot.right(speed)
                sleep(0.3)
            robot.stop()
        elif cmd == "q":
            break
        else:
            print("Unknown command.")
finally:
    robot.stop()  # always stop the motors, even if something goes wrong
    print("Robot stopped.")

