struct MathSprintGameView: View {
    @State private var questionText = ""
    @State private var correctAnswer = 0
    @State private var options: [Int] = []
    @State private var score = 0
    @State private var timeLeft = 60
    @State private var playing = false
    @State private var flashColor = Color.clear

    let clock = Timer.publish(every: 1, on: .main, in: .common).autoconnect()

    var body: some View {
        VStack(spacing: 30) {
            HStack {
                Text("Score: \(score)")
                Spacer()
                Text("Time: \(timeLeft)")
            }
            .font(.title2.bold())
            .monospacedDigit()

            Text(playing ? questionText : "Math Sprint")
                .font(.system(size: 60, weight: .bold, design: .rounded))
                .padding()
                .frame(maxWidth: .infinity)
                .background(flashColor.opacity(0.3), in: RoundedRectangle(cornerRadius: 20))

            if playing {
                LazyVGrid(columns: [GridItem(.flexible()), GridItem(.flexible())], spacing: 16) {
                    ForEach(options, id: \.self) { option in
                        Button {
                            pick(option)
                        } label: {
                            Text("\(option)")
                                .font(.largeTitle.bold())
                                .frame(maxWidth: .infinity, minHeight: 80)
                        }
                        .buttonStyle(.borderedProminent)
                    }
                }
            } else {
                Button(timeLeft == 0 ? "Play again" : "Start") { start() }
                    .buttonStyle(.borderedProminent)
                    .font(.title)
            }
        }
        .padding()
        .onReceive(clock) { _ in
            guard playing else { return }
            timeLeft -= 1
            if timeLeft <= 0 { playing = false }
        }
    }

    func start() {
        score = 0
        timeLeft = 60
        playing = true
        newQuestion()
    }

    func newQuestion() {
        let a = Int.random(in: 2...12)
        let b = Int.random(in: 2...12)
        switch Int.random(in: 0..<3) {
        case 0:
            questionText = "\(a) + \(b)"
            correctAnswer = a + b
        case 1:
            questionText = "\(a + b) - \(b)"
            correctAnswer = a
        default:
            questionText = "\(a) x \(b)"
            correctAnswer = a * b
        }
        // Make three wrong answers that are close to the right one (a Set stops repeats)
        var choices: Set<Int> = [correctAnswer]
        while choices.count < 4 {
            let wrong = correctAnswer + Int.random(in: -10...10)
            if wrong >= 0 { choices.insert(wrong) }
        }
        options = Array(choices).shuffled()
    }

    func pick(_ option: Int) {
        if option == correctAnswer {
            score += 1
            flashColor = .green
        } else {
            score = max(0, score - 1)
            flashColor = .red
        }
        withAnimation(.easeOut(duration: 0.5)) { flashColor = .clear }
        newQuestion()
    }
}

import SwiftUI

struct MemoryTile: Identifiable {
    let id = UUID()
    let symbol: String
    var faceUp = false
    var matched = false
}

struct MemoryMatchGameView: View {
    @State private var tiles: [MemoryTile] = MemoryMatchGameView.newDeck()
    @State private var firstPick: Int? = nil
    @State private var moves = 0
    @State private var busy = false   // true while two wrong cards are showing

    var allMatched: Bool { tiles.allSatisfy { $0.matched } }

    // Two of each picture, shuffled
    static func newDeck() -> [MemoryTile] {
        let symbols = ["star.fill", "heart.fill", "bolt.fill", "leaf.fill", "moon.fill", "flame.fill", "cloud.fill", "gamecontroller.fill"]
        return (symbols + symbols).shuffled().map { MemoryTile(symbol: $0) }
    }

    var body: some View {
        VStack(spacing: 16) {
            Text(allMatched ? "You won in \(moves) moves!" : "Moves: \(moves)")
                .font(.title.bold())

            LazyVGrid(columns: Array(repeating: GridItem(.flexible()), count: 4), spacing: 12) {
                ForEach(tiles.indices, id: \.self) { index in
                    let tile = tiles[index]
                    ZStack {
                        RoundedRectangle(cornerRadius: 14)
                            .fill(tile.faceUp || tile.matched ? Color.white : Color.blue)
                        RoundedRectangle(cornerRadius: 14)
                            .stroke(Color.blue, lineWidth: 3)
                        if tile.faceUp || tile.matched {
                            Image(systemName: tile.symbol)
                                .font(.system(size: 40))
                                .foregroundStyle(tile.matched ? Color.green : Color.orange)
                        }
                    }
                    .frame(height: 100)
                    .rotation3DEffect(.degrees(tile.faceUp ? 0 : 180), axis: (x: 0, y: 1, z: 0))
                    .onTapGesture { tap(index) }
                }
            }

            Button("New game") {
                tiles = MemoryMatchGameView.newDeck()
                firstPick = nil
                moves = 0
                busy = false
            }
            .buttonStyle(.borderedProminent)
        }
        .padding()
    }

    func tap(_ index: Int) {
        guard !busy, !tiles[index].faceUp, !tiles[index].matched else { return }
        withAnimation(.easeInOut(duration: 0.3)) { tiles[index].faceUp = true }

        guard let first = firstPick else {
            firstPick = index   // this was the first card of the pair
            return
        }
        moves += 1
        firstPick = nil
        if tiles[first].symbol == tiles[index].symbol {
            tiles[first].matched = true
            tiles[index].matched = true
        } else {
            // Not a match: wait a moment so you can see them, then flip both back
            busy = true
            Task {
                try? await Task.sleep(for: .seconds(0.8))
                withAnimation(.easeInOut(duration: 0.3)) {
                    tiles[first].faceUp = false
                    tiles[index].faceUp = false
                }
                busy = false
            }
        }
    }
}

