// Matches one item from https://jsonplaceholder.typicode.com/posts
struct WebPost: Codable, Identifiable {
    let id: Int
    let userId: Int
    let title: String
    let body: String
}

struct PostsLoaderView: View {
    @State private var posts: [WebPost] = []
    @State private var errorMessage: String? = nil
    @State private var loading = false

    var body: some View {
        NavigationStack {
            List(posts) { post in
                VStack(alignment: .leading, spacing: 6) {
                    Text(post.title.capitalized).font(.headline)
                    Text(post.body).font(.subheadline).foregroundStyle(.secondary).lineLimit(2)
                    Text("Post \(post.id) by user \(post.userId)").font(.caption)
                }
            }
            .overlay {
                if loading {
                    ProgressView("Downloading...")
                } else if let errorMessage {
                    ContentUnavailableView("Couldn't load", systemImage: "wifi.slash", description: Text(errorMessage))
                }
            }
            .navigationTitle("Posts")
            .task { await loadPosts() }
            .refreshable { await loadPosts() }
        }
    }

    func loadPosts() async {
        guard let url = URL(string: "https://jsonplaceholder.typicode.com/posts") else { return }
        loading = posts.isEmpty
        errorMessage = nil
        do {
            // Wait for the download without freezing the screen
            let (data, _) = try await URLSession.shared.data(from: url)
            posts = try JSONDecoder().decode([WebPost].self, from: data)
        } catch {
            errorMessage = error.localizedDescription
        }
        loading = false
    }
}

import SwiftUI

struct PaintStroke {
    var points: [CGPoint] = []
    var color: Color
    var width: CGFloat
}

struct DrawingPadAppView: View {
    @State private var strokes: [PaintStroke] = []
    @State private var current = PaintStroke(color: .black, width: 6)
    @State private var color = Color.black
    @State private var brushSize = 6.0

    let palette: [Color] = [.black, .red, .orange, .yellow, .green, .blue, .purple]

    var body: some View {
        VStack {
            Canvas { context, _ in
                // Draw every finished stroke, then the one being drawn now
                for stroke in strokes + [current] {
                    var path = Path()
                    path.addLines(stroke.points)
                    context.stroke(path, with: .color(stroke.color),
                                   style: StrokeStyle(lineWidth: stroke.width, lineCap: .round, lineJoin: .round))
                }
            }
            .background(Color.white)
            .gesture(
                DragGesture(minimumDistance: 0)
                    .onChanged { value in
                        current.points.append(value.location)
                    }
                    .onEnded { _ in
                        strokes.append(current)
                        current = PaintStroke(color: color, width: CGFloat(brushSize))
                    }
            )

            HStack {
                ForEach(palette, id: \.self) { swatch in
                    Circle()
                        .fill(swatch)
                        .frame(width: 34, height: 34)
                        .overlay(Circle().stroke(Color.gray, lineWidth: swatch == color ? 4 : 0))
                        .onTapGesture {
                            color = swatch
                            current.color = swatch
                        }
                }
            }
            HStack {
                Text("Brush")
                Slider(value: $brushSize, in: 2...40)
                    .onChange(of: brushSize) { current.width = CGFloat(brushSize) }
                Button("Undo") { _ = strokes.popLast() }
                    .disabled(strokes.isEmpty)
                Button("Clear", role: .destructive) { strokes.removeAll() }
            }
            .padding(.horizontal)
        }
        .padding(.bottom)
    }
}

