// Codable lets us turn tasks into JSON text to save them
struct TodoTask: Identifiable, Codable, Equatable {
    var id = UUID()
    var title: String
    var done = false
}

struct TodoAppView: View {
    @State private var tasks: [TodoTask] = []
    @State private var newTitle = ""
    @AppStorage("todoAppSavedTasks") private var savedJSON = ""

    var remaining: Int { tasks.filter { !$0.done }.count }

    var body: some View {
        NavigationStack {
            List {
                Section {
                    HStack {
                        TextField("What do you need to do?", text: $newTitle)
                            .onSubmit(addTask)
                        Button("Add", action: addTask)
                            .disabled(newTitle.trimmingCharacters(in: .whitespaces).isEmpty)
                    }
                }
                Section("\(remaining) left to do") {
                    ForEach($tasks) { $task in
                        HStack {
                            Button {
                                task.done.toggle()
                            } label: {
                                Image(systemName: task.done ? "checkmark.circle.fill" : "circle")
                                    .font(.title2)
                                    .foregroundStyle(task.done ? Color.green : Color.gray)
                            }
                            .buttonStyle(.plain)
                            Text(task.title)
                                .strikethrough(task.done)
                                .foregroundStyle(task.done ? Color.secondary : Color.primary)
                        }
                    }
                    .onDelete { offsets in tasks.remove(atOffsets: offsets) }
                }
            }
            .navigationTitle("To-Do")
            .toolbar {
                Button("Clear done") { tasks.removeAll { $0.done } }
            }
            .onAppear(perform: load)
            // Save every time the list changes
            .onChange(of: tasks) { save() }
        }
    }

    func addTask() {
        let title = newTitle.trimmingCharacters(in: .whitespaces)
        guard !title.isEmpty else { return }
        tasks.append(TodoTask(title: title))
        newTitle = ""
    }

    func save() {
        if let data = try? JSONEncoder().encode(tasks), let text = String(data: data, encoding: .utf8) {
            savedJSON = text
        }
    }

    func load() {
        guard let data = savedJSON.data(using: .utf8) else { return }
        if let saved = try? JSONDecoder().decode([TodoTask].self, from: data) {
            tasks = saved
        }
    }
}

import SwiftUI

struct UnitConverterAppView: View {
    @State private var amount = 1.0
    @State private var kind = 0
    @State private var fromIndex = 0
    @State private var toIndex = 1

    let kinds = ["Length", "Temperature", "Weight"]
    // Each kind has its own list of units. Dimension is the parent class of all of them.
    let units: [[Dimension]] = [
        [UnitLength.meters, UnitLength.feet, UnitLength.inches, UnitLength.kilometers, UnitLength.miles],
        [UnitTemperature.celsius, UnitTemperature.fahrenheit, UnitTemperature.kelvin],
        [UnitMass.kilograms, UnitMass.pounds, UnitMass.grams, UnitMass.ounces],
    ]

    var currentUnits: [Dimension] { units[kind] }

    var resultText: String {
        // min() keeps the index safe for a moment after switching to a shorter list
        let fromUnit = currentUnits[min(fromIndex, currentUnits.count - 1)]
        let toUnit = currentUnits[min(toIndex, currentUnits.count - 1)]
        let from = Measurement(value: amount, unit: fromUnit)
        let converted = from.converted(to: toUnit)
        let formatter = MeasurementFormatter()
        formatter.unitOptions = .providedUnit  // keep the unit we picked
        formatter.numberFormatter.maximumFractionDigits = 3
        return formatter.string(from: converted)
    }

    func name(of unit: Dimension) -> String {
        let formatter = MeasurementFormatter()
        formatter.unitStyle = .long
        return formatter.string(from: unit).capitalized
    }

    var body: some View {
        NavigationStack {
            Form {
                Picker("Type", selection: $kind) {
                    ForEach(kinds.indices, id: \.self) { index in
                        Text(kinds[index]).tag(index)
                    }
                }
                .pickerStyle(.segmented)
                .onChange(of: kind) {
                    fromIndex = 0
                    toIndex = 1
                }

                Section("Convert") {
                    TextField("Amount", value: $amount, format: .number)
                        .keyboardType(.decimalPad)
                    Picker("From", selection: $fromIndex) {
                        ForEach(currentUnits.indices, id: \.self) { index in
                            Text(name(of: currentUnits[index])).tag(index)
                        }
                    }
                    Picker("To", selection: $toIndex) {
                        ForEach(currentUnits.indices, id: \.self) { index in
                            Text(name(of: currentUnits[index])).tag(index)
                        }
                    }
                }

                Section("Answer") {
                    Text(resultText).font(.title2.bold())
                }
            }
            .navigationTitle("Converter")
        }
    }
}

