import SwiftUI

struct TextFieldDemoView: View {
    @State private var name = ""
    @State private var age = ""
    @State private var password = ""
    @State private var submitted = false

    // Which field has the keyboard right now
    enum Field { case name, age, password }
    @FocusState private var focus: Field?

    var body: some View {
        VStack(alignment: .leading, spacing: 16) {
            TextField("Your name", text: $name)
                .textFieldStyle(.roundedBorder)
                .focused($focus, equals: .name)
                .submitLabel(.next)
                .onSubmit { focus = .age }  // pressing return jumps to the next box

            TextField("Age", text: $age)
                .textFieldStyle(.roundedBorder)
                .keyboardType(.numberPad)
                .focused($focus, equals: .age)

            SecureField("Password", text: $password)
                .textFieldStyle(.roundedBorder)
                .focused($focus, equals: .password)
                .onSubmit { submitted = true }

            Text("Password strength: \(password.count >= 8 ? "good" : "too short") (\(password.count) characters)")
                .font(.caption)
                .foregroundStyle(password.count >= 8 ? Color.green : Color.orange)

            Button("Sign up") {
                submitted = true
                focus = nil  // hide the keyboard
            }
            .buttonStyle(.borderedProminent)
            .disabled(name.isEmpty || password.count < 8)

            if submitted {
                Text("Welcome, \(displayName)! Age: \(ageText)")
                    .font(.headline)
            }
            Spacer()
        }
        .padding()
    }

    var displayName: String { name.isEmpty ? "friend" : name }

    // Int(age) is nil if the age box doesn't hold a number
    var ageText: String {
        if let number = Int(age) {
            return String(number)
        }
        return "unknown"
    }
}

import SwiftUI

struct TimelineClockView: View {
    var body: some View {
        VStack(spacing: 40) {
            // .periodic redraws once every second
            TimelineView(.periodic(from: .now, by: 1)) { context in
                VStack {
                    Text(context.date, format: .dateTime.hour().minute().second())
                        .font(.system(size: 54, weight: .bold, design: .monospaced))
                    Text(context.date, format: .dateTime.weekday(.wide).day().month(.wide))
                        .foregroundStyle(.secondary)
                }
            }

            // .animation redraws as fast as the screen can, for smooth motion
            TimelineView(.animation) { timeline in
                let seconds = timeline.date.timeIntervalSinceReferenceDate
                let angle = seconds.truncatingRemainder(dividingBy: 3) / 3 * 2 * Double.pi

                ZStack {
                    Circle()
                        .stroke(Color.gray.opacity(0.3), lineWidth: 4)
                        .frame(width: 160, height: 160)
                    Circle()
                        .fill(Color.orange)
                        .frame(width: 24, height: 24)
                        .offset(x: CGFloat(80 * cos(angle)), y: CGFloat(80 * sin(angle)))
                }
            }
            Text("The dot goes around once every 3 seconds")
                .font(.caption)
        }
        .padding()
    }
}

